         * под ощущение сколько угодно: физику он больше не ломает.
         */
        /**
         * ВЕС СХВАЧЕННОЙ КЛЕТКИ В SHAPE MATCHING. Был 200.0, стал 1.0.
         *
         * Появился, когда тяга была ПОЗИЦИОННОЙ: чтобы кость шла за курсором, её
         * жёсткую позу подгоняли под схваченную клетку, задрав ей вес. Теперь тяга
         * прикладывает импульс ко всему твёрдому телу как положено, и подгонять
         * позу под одну клетку больше не нужно.
         *
         * Двести означает, что при подборе позы одна клетка весит как две сотни
         * остальных: проекция кости каждый подшаг рвётся за ней, поправки выходят
         * огромные, скорость перелетает потолок и включается clampSpeed, который
         * импульс не сохраняет. В кадре это выглядело как разнос — пик 15.01 при
         * потолке 8.0, 867 срабатываний потолка, 100 порванных связей.
         *
         * ЗАМЕР НА ЗАПИСАННОМ ПЕРЕТАСКИВАНИИ. Обрыв резкий, между 20 и 5:
         *
         *     вес   пик   потолок  порвано  клетка до курсора в конце
         *     200  17.31    20194      248        134.51 связи
         *      20  13.90    22195       51        120.31
         *       5   3.48        0        0          0.00
         *       1   3.48        0        0          0.01
         *
         * При двухстах и двадцати клетка НЕ ВОЗВРАЩАЕТСЯ к курсору вовсе — это и
         * есть наблюдавшееся «тело улетело и не вернулось». При пяти и ниже всё
         * чисто: потолок молчит, связи целы, клетка садится на курсор.
         *
         * Единица выбрана не как «достаточно малое», а как ОТСУТСТВИЕ особого
         * веса: за костью теперь следит импульс, приложенный ко всему твёрдому
         * телу, и подгонять позу под одну клетку незачем.
         */
        private const val DRAG_MATCH_WEIGHT = 1.0

        private const val DRAG_SPEED_LIMIT = 0.25

        /**
         * ПОСТОЯННАЯ ВРЕМЕНИ ТЯГИ, в секундах: за сколько сервотяга РАССЧИТЫВАЕТ
         * закрыть разрыв между клеткой и курсором.
         *
         * Раньше здесь неявно стоял ОДИН ТИК: целевая скорость считалась как
         * расстояние делить на DT. Отставание всего в одну связь требовало при этом
         * тридцати связей в секунду, тело столько не развивает, ошибка сервотяги
         * никогда не обращалась в ноль — и сила давила без остановки. На записанном
         * перетаскивании это давало полторы секунды монотонного разгона: скорость
         * центра масс с 2.1 до 8.0 связей в секунду, вращение с 0.28 до 1.13 рад/с.
         * То есть получалась не рука, а буксир с постоянной тягой.
         *
         * С постоянной времени сервотяга выходит в режим регулирования: по мере
         * приближения к курсору цель падает, сила снимается сама, и клетка
         * останавливается у курсора вместо того, чтобы проскочить и качнуться назад.
         */
        private const val DRAG_TAU = 0.2

        /**
         * ПУЛЯ [P] — одиночная клетка, запущенная справа налево на потолке скорости.
         *
         * Проверка непроницаемости в самом злом допустимом случае: быстрее в стенде
         * не летает ничто, потому что clampSpeed режет всё выше. Если пуля прошла
         * насквозь, значит дыра настоящая, а не следствие слишком резкой мыши.
         * Так же сделано в прототипе, откуда переносились контакты.
         */
        /**
         * Доля потолка скорости для пули и тарана.
         *
         * Было 0.95, стало 0.8. Девяносто пять процентов оставляли запаса всего
         * пять, а его съедает первая же добавка от ограничений: удар, поправка
         * связи, отклик контакта. Потолок скорости при этом срабатывает, а он
         * правит частицы по одной и импульс не сохраняет — то есть стенд сам
         * создавал ту ошибку, которую призван ловить.
         *
         * Восемь десятых оставляют пятую часть потолка на отклик решателя. Проверка
         * непроницаемости от этого не слабеет: пуля по-прежнему летит быстрее, чем
         * что-либо в симуляции способно двигаться само.
         */
        private const val BULLET_SPEED_FRACTION = 0.8

        private val TEAR_FILL = Color(0.25f, 0.45f, 0.95f, 1f)
        private val TEAR_LINK = Color(0.45f, 0.65f, 1f, 1f)

        /**
         * ИЗГИБ ГРАНИЧНОГО КОНТУРА — податливости, которые перебирает клавиша E.
         * -1 — стадия выключена. ПО УМОЛЧАНИЮ ВЫКЛЮЧЕНА, см. почему ниже.
         *
         * ЗАЧЕМ. Единственное дешёвое, что вообще способно сделать дорогим заворот
         * ткани, при котором НИ ОДИН треугольник не вывернулся. Знаковая площадь —
         * признак ЛОКАЛЬНЫЙ: сложенный пополам лист нигде не выворачивается наизнанку,
         * каждый треугольник в нём положителен. Замер на этом теле: заворот при нулевом
         * числе вывернутых, и искажение формы не уходит, а РАСТЁТ — 1.09 клетки сразу
         * после скручивания и 2.79 через две секунды.
         *
         * КАК СЧИТАЕТСЯ, и это дешевле, чем кажется. Угол при вершине считать не нужно:
         * он однозначно связан с расстоянием между её двумя соседями, потому что стороны
         * уже держат обычные связи. Значит хватает ограничения РАССТОЯНИЯ «через одну»
         * вдоль границы — тот же решатель, ни одной новой формулы, никаких acos.
         *
         * ПОЧЕМУ ВЫКЛЮЧЕНО ПО УМОЛЧАНИЮ. Работает как задумано, но стоит ТЯГИ, и много.
         * Замер (стенд FoldRecovery, тело 947 клеток):
         *
         *      податливость   искажение через 2 с   тяга за цикл
         *      выключено             2.788             0.06502
         *      1e-3                  2.846             0.05586    -14%
         *      1e-4                  1.841             0.03400    -48%
         *      1e-5                  0.796             0.01768    -73%
         *
         * Причина прямая и неустранимая в лоб: мышца плывёт тем, что ИЗГИБАЕТ тело, а
         * тяга берётся с нормальной скорости граничных рёбер. Ограничение изгиба
         * сопротивляется ровно этому движению — это не побочный эффект, это одно и то же
         * движение. Сильнее всего бьёт по кончику хвоста, где кривизна меняется больше
         * всего и где гребок самый цепкий.
         *
         * ПРЕЖДЕ ЧЕМ ВКЛЮЧАТЬ НАСОВСЕМ — переподобрать параметры плавания: нынешние
         * искал SwimTuner без этой стадии, и новая жёсткость смещает весь оптимум.
         * bendCompliance уже заведена геном, диапазон включает «почти выключено».
         * И делать это имеет смысл уже вместе с пограничными коллизиями, иначе
         * подбирать придётся дважды.
         */
        private val BEND_LEVELS = doubleArrayOf(-1.0, 1.0e-3, 1.0e-4, 1.0e-5, 1.0e-6, 1.0e-7, 0.0)

        /**
         * ОТКУДА ВЗЯТЫ ЗНАЧЕНИЯ ГИДРОДИНАМИКИ И МЫШЦ (ниже и до конца companion).
         *
         * Не подобраны на глаз — найдены эволюционным поиском SwimTuner, см. его шапку.
         * Поиск максимизировал скорость плавания при жёстких штрафах за паразитное
         * движение: остаточный импульс через 50 секунд после гребков, дрейф в позе покоя
         * и толчок среды на чистом повороте. Итог против прежних значений:
         *
         *      показатель              было      стало
         *      скорость                0.053     0.400     в 7.6 раза
         *      накат (доля скорости)   0.148     0.649     в 4.4 раза
         *      затухание 25c -> 50c    1.76x     9.4x      было полкой, стало затуханием
         *      дрейф в покое           4.2e-2    9.4e-5    в 449 раз
         *      толчок на повороте      0.833     0.089     в 9.4 раза
         *
         * ПРЕЖНИЕ ЗАМЕРЫ В КОММЕНТАРИЯХ НИЖЕ НЕ УДАЛЕНЫ И НЕ УСТАРЕЛИ: они объясняют
         * ФОРМУ зависимостей (где максимум, что чем торгуется, почему знак такой), и это
         * знание переносится в движок. Устарели только пометки «стоит сейчас» — там, где
         * они мешали, я их снял.
         *
         * ВАЖНО ПРИ ПЕРЕСМОТРЕ: почти все эти величины связаны с GAIT_PERIOD и с масштабом
         * клетки. Меняете период гребка или размер тела — перезапускайте поиск, а не
         * подкручивайте по одной.
         */
        private const val GRAVITY = 0.0
        private const val GROUND_Y = -100.0
        private const val GROUND_FRICTION = 0.0
        private const val GROUND_RESTITUTION = 0.0
        /**
         * Изотропное сопротивление среды, 1/сек. Гасит скорость одинаково во всех
         * направлениях, поэтому ТЯГИ НЕ СОЗДАЁТ НИКОГДА: мышца сжалась — затормозило,
         * разжалась — затормозило ровно так же, фазы симметричны, сумма около нуля.
         * Поднимать его ради «плотности среды» бессмысленно — движение умрёт, а плавания
         * не появится. Здесь оно остаётся только общим успокоителем.
         */
        private const val MEDIUM_DRAG = 0.0921

        /**
         * АНИЗОТРОПНОЕ сопротивление на граничных рёбрах, 1/(сек * единица длины).
         *
         * Гасится только НОРМАЛЬНАЯ к ребру составляющая скорости, тангенциальная не
         * трогается. Отсюда и берётся тяга: плавник, идущий плашмя, гребёт среду, он же
         * ребром — почти нет. Эта асимметрия и превращает периодическое сокращение мышцы
         * в направленное движение.
         *
         * Только граница: внутренние рёбра средой не омываются. Граничным считается ребро,
         * входящее ровно в ОДИН треугольник (внутренние входят в два) — в движке тот же
         * признак уже есть готовым, это cellEntity.isOnEdge.
         *
         * Модель линейная по скорости, а не квадратичная: для малых существ это ближе к
         * правде (низкое число Рейнольдса) и заметно устойчивее.
         *
         * ВЕЛИЧИНА. Эффективное затухание равно NORMAL_DRAG * средняя_длина_ребра, то есть
         * коэффициент привязан к масштабу тела и при другом размере клеток его надо
         * пересчитывать. Замер быстрого рывка за кость — отношение «сдвиг центра масс к
         * сдвигу самой вершины»:
         *
         *     250  ->  7.1 1/с,  ratio 0.78  тело отстаёт на 22%, РАСТЯГИВАЕТСЯ
         *      60  ->  1.7 1/с,  ratio 1.06  следует за костью
         *       0  ->    0,      ratio 1.63  проскакивает по инерции
         *
         * Сначала здесь стояло 250 — я подбирал его так, чтобы плавание было заметно на
         * замере, и не проверил, каково тело на ощупь. Это в 14 раз плотнее изотропного
         * сопротивления, отсюда и ощущение вязкой субстанции при перетаскивании.
         */
        private const val NORMAL_DRAG = 43.33//184.12

        /**
         * КВАДРАТИЧНАЯ часть сопротивления: сила растёт как v*|v|, а не как v.
         *
         * Два механизма тяги здесь РАЗНЫЕ и складываются.
         *
         * Линейная работает по Пёрселлу — за счёт СМЕНЫ ОРИЕНТАЦИИ поверхности за цикл.
         * Квадратичная добавляет инерционный: быстрый взмах даёт непропорционально
         * больше медленного, как у рыб и медуз.
         *
         * Замер, путь центра масс за 10 секунд, цикл с рабочей фазой в треть периода:
         *
         *     линейное  + симметричная мышца  ->  0.070
         *     линейное  + асимметричная       ->  0.217   (3.1x)
         *     квадратичное + симметричная     ->  0.130   (1.8x)
         *     квадратичное + асимметричная    ->  0.310   (4.4x)
         *
         * Сначала я написал здесь, что на линейном сопротивлении асимметрия по времени
         * не даёт ничего: импульс за замкнутый цикл равен -k * (перемещение поверхности),
         * то есть от скорости не зависит. Замер это опроверг — строка B даёт 3.1x.
         * Рассуждение верно только для ЖЁСТКОЙ неповорачивающейся пластины; у мягкого
         * тела ориентация ребра меняется по ходу гребка, интеграл не сворачивается,
         * и профиль скорости начинает влиять даже на линейной модели.
         *
         * ЧТО ИЗ ДВУХ ЧЛЕНОВ ГЛАВНЫЙ. Квадратичный перевешивает линейный при
         * |vn| > NORMAL_DRAG / NORMAL_DRAG_QUADRATIC = 15/3600 = 0.004. Замер нормальной
         * скорости на граничных рёбрах во время гребка: средняя 0.24, пиковая до 1.9 —
         * то есть в 4 и в 28 раз выше порога. На практике режим квадратичный почти всегда,
         * линейный член работает только на затухании между гребками.
         *
         * БАЛАНС ЛИНЕЙНОГО И КВАДРАТИЧНОГО — ЭТО РУЧКА «СКОЛЬЖЕНИЯ».
         *
         * Линейный член тормозит на ЛЮБОЙ скорости, включая медленный накат после
         * толчка. Квадратичный заметен только на быстрых движениях, то есть на самом
         * взмахе. Значит сдвиг баланса в сторону квадратичного сохраняет тягу гребка
         * и убирает торможение наката.
         *
         * Замер: 6 полных циклов гребли (20 с), затем 10 с наката без гребков.
         *
         *     ND=60  Q=900   среда 0.5  ->  путь 0.0274  накат 0.0131   (было)
         *     ND=60  Q=900   среда 0.1  ->  путь 0.0283  накат 0.0111
         *     ND=15  Q=3600  среда 0.5  ->  путь 0.0147  накат 0.0174
         *     ND=15  Q=3600  среда 0.1  ->  путь 0.0593  накат 0.0221   (стоит сейчас)
         *
         * Последняя строка лучше первой и по тяге в 2.2 раза, и по накату в 1.7.
         * Третья строка выпадает из монотонности — замер по одной траектории шумит,
         * потому что тело ещё и поворачивает, а метрика берёт расстояние от старта.
         */
        private const val NORMAL_DRAG_QUADRATIC = 71.8//135.6

        /**
         * КАСАТЕЛЬНОЕ ТРЕНИЕ РЕБРА — вторая половина сопротивления среды.
         *
         * NORMAL_DRAG — это сопротивление ДАВЛЕНИЯ: ребро гребёт поперёк себя. Оно и даёт
         * тягу, и быстро гасит поступательное движение. Но вдоль ребра среда не мешала
         * вовсе, а в жидкости вдоль стенки есть трение о поверхность.
         *
         * ЧТО ЭТО ЧИНИТ. Оторвавшийся кусочек, раскрученный ударом, не останавливался почти
         * никогда. Журнал 17.09 18:04, метка на клетке #846: кусок из трёх клеток —
         * равносторонний треугольник, у него радиус до середины ребра перпендикулярен
         * ребру, поэтому при вращении вокруг центра середина ребра движется ВДОЛЬ ребра, и
         * нормальная составляющая равна нулю ТОЧНО. Вращение гасила одна изотропная среда:
         * 36.5 -> 0.8 рад/с за 42 секунды, постоянная времени 10.9 с — ровно 1/MEDIUM_DRAG.
         *
         * ВЕЛИЧИНА. В жидкости трение о поверхность на порядок-два слабее сопротивления
         * давления: для пластины коэффициент трения около 0.01 против 1-2 у плохо
         * обтекаемого тела. Поэтому здесь доля от NORMAL_DRAG, а не своё число.
         *
         * ЗАМЕР (стенд PERF_SPIN на теле body-spin-test.txt — тот самый треугольник,
         * раскрученный до 30 рад/с; доля начальной ω через 10 секунд):
         * выкл 0.398, 0.01 — 0.385, 0.05 — 0.335, 0.20 — 0.200. Гребок на журнале
         * плавания (скорость тела, клеток/тик): 0.0360, 0.0359, 0.0350, 0.0332.
         * Тик на игровом теле: 10.61 мс выкл, 10.82 мс при 0.05.
         *
         * ПО УМОЛЧАНИЮ ВЫКЛЮЧЕНО, и вот почему. Вечное вращение мелкого куска трение не
         * лечит: при правдоподобной величине затухание меняется на проценты, потому что
         * вращение гасит почти одна изотропная среда (MEDIUM_DRAG, постоянная времени
         * 10.9 с). Пользы не видно, а тяга и время тика страдают — включать незачем.
         * Механизм оставлен готовым: число здесь, зеркало в SwimSolver, ручка у тюнера.
         */
        private const val TANGENT_DRAG = 0.0

        /**
         * УВЛЕЧЁННЫЙ ПОТОК (присоединённая масса), 1/сек. 0 — выключено.
         *
         * Проблема, которую это решает: в чисто резистивной модели сопротивление считается
         * от АБСОЛЮТНОЙ скорости ребра, будто среда всегда неподвижна. В реальности тело
         * разгоняет среду вокруг себя, и через долю секунды она движется почти вместе с
         * ним — сопротивление падает почти до нуля. Именно поэтому толкнутое тело ещё
         * какое-то время плывёт, и это НЕ инерция тела, а импульс, запасённый в потоке.
         *
         * Модель: у каждого граничного ребра хранится нормальная скорость увлечённой
         * среды. Она экспоненциально догоняет скорость ребра, а сопротивление считается
         * от ОТНОСИТЕЛЬНОЙ скорости.
         *
         *   - резкий взмах: поток догнать не успел, относительная скорость велика,
         *     тяга максимальная;
         *   - равномерное скольжение: поток догнал, относительная скорость около нуля,
         *     торможения почти нет.
         *
         * То есть та же самая величина одновременно даёт и сильный гребок, и длинный
         * накат — без всяких порогов и без ущерба тяге.
         *
         * ВЕЛИЧИНА. Замер на теле 370 клеток с одной мышцей: путь за 20 секунд гребли
         * и накат за 5 секунд после толчка v = 0.5.
         *
         *      0  ->  тяга 1.34   накат 0.23   (классическая резистивная модель)
         *      2  ->  тяга 6.39   накат 0.93   максимум тяги
         *      8  ->  тяга 5.41   накат 1.45   стоит сейчас
         *     30  ->  тяга 0.31   накат 1.75   тяга ОБВАЛИЛАСЬ
         *
         * Тяга имеет максимум, накат растёт монотонно — это две разные вещи, и ручка
         * между ними торгует. Выше 8 среда догоняет плавник так быстро, что оттолкнуться
         * уже не от чего: при 30 путь вчетверо хуже, чем вообще без потока.
         *
         * Полезный диапазон 2..8. Меньше — хочется резкости, больше — скольжения.
         * Оптимум привязан к ДЛИТЕЛЬНОСТИ ГРЕБКА: постоянная времени потока должна быть
         * сравнима с ней, поэтому при смене GAIT_PERIOD значение надо пересматривать.
         */

        private const val FLOW_ENTRAIN = 2f//34.047

        /**
         * МАССА увлечённой среды, в массах тела. Тело — это n частиц массой 1.
         *
         * Появилась вместе с новой моделью памяти среды (см. applyNormalDrag). Смысл:
         * разгон увлечённой среды телу СТОИТ импульса, и вот это её инерция. Ноль —
         * среда безмассовая, разгонять её бесплатно, накопителя фактически нет.
         *
         * Найдено поиском: 0.088, то есть увлечённой среды примерно 9% массы тела.
         * Величина скромная, и это осмысленно — большая масса означает, что тело волочит
         * за собой много воды, и тогда гребок уходит в её разгон вместо движения.
         */
        private const val FLOW_MASS = 0.050

        /**
         * РАССЕЯНИЕ увлечённого потока, 1/сек. Пара к FLOW_ENTRAIN, без неё модель врёт.
         *
         * FLOW_ENTRAIN только ДОГОНЯЕТ тело и ничего не теряет, поэтому сам по себе
         * запас среды — вечный аккумулятор импульса. После нескольких гребков он накачан,
         * и разность (vn - поток) становится отрицательной: среда начинает толкать
         * тело ВПЕРЁД без единого гребка, а движение не кончается вовсе.
         *
         * В реальности вязкость уносит импульс потока в объём жидкости за конечное
         * время. Эта константа и задаёт это время: 1/сек — секунда, 4/сек — четверть.
         *
         *
         * ЗАМЕР: 8 гребков, затем мышца отпущена насовсем (FLOW_ENTRAIN = 0.2):
         *
         *     0  ->  за гребки 5.07,  ПОСЛЕ них ещё 3.32 за 20 с и всё ещё едет
         *     1  ->  за гребки 2.15,  после них 0.26
         *     3  ->  за гребки 1.92,  после них 0.26
         *    10  ->  за гребки 1.82,  после них 0.24
         *
         * Накат падает в 13 раз уже при 1, дальше не улучшается, а тяга продолжает
         * снижаться — поэтому стоит 1. Обратите внимание, во что обходится починка:
         * тяга упала с 5.07 до 2.15, то есть больше половины прежней «мощности»
         * была не гребком, а разряжающимся аккумулятором.
         * Осмысленное соотношение: рассеяние должно быть БЫСТРЕЕ, чем увлечение
         * (FLOW_DECAY > FLOW_ENTRAIN), иначе поток успевает накопиться больше, чем
         * потерять, и аккумулятор возвращается.
         */
        private const val FLOW_DECAY = 1.168//0.488

        private const val VISCOSITY = 10.0

        /**
         * Гасить паразитный дрейф от внутренних решателей.
         *
         * Ограничения расстояния, площади и проекция кости — воздействия ВНУТРЕННИЕ, и
         * центр масс сдвигать не имеют права вообще. Любое его смещение от них — это
         * накопленное округление float32: `px[i] += d` и `px[j] -= d` округляются
         * по-разному, потому что сами позиции разной величины. Замер этого показал:
         * в double дрейф ровно ноль, во float порядка 1e-3 импульса.
         *
         * Здесь он вычитается напрямую: центр масс запоминается до внутренних стадий и
         * восстанавливается после. Это O(n) и убирает ошибку точно.
         *
         * РАБОТАЕТ ТОЛЬКО КОГДА ТЕЛО НЕ ДЕРЖАТ МЫШЬЮ — см. simulate().
         *
         * При активной тяге зачёт даёт побочный эффект: тело остаётся растянутым всё
         * время, пока держишь, и распрямляется, стоило отпустить. Механизм я объяснить
         * не смог — две гипотезы (нарушение сохранения импульса в projectBone из-за
         * matchWeight = 200; вклад гидродинамики) проверены замером и обе неверны:
         * сдвиг центра масс от проекции равен 1e-6 при любом весе, а гидродинамика
         * зависит от скорости и при неподвижной мыши обращается в ноль.
         *
         * Поэтому поправка ограничена областью, где она заведомо законна: тяга — сила
         * внешняя, при ней «центр масс не должен двигаться» просто неверно как посылка.
         * Без тяги посылка верна, и там зачёт работает. Дрейф от мышц как раз копится
         * в свободном плавании, то есть ровно тогда, когда поправка включена.
         */
        private const val CANCEL_INTERNAL_DRIFT = false

        /**
         * Снимать ли импульс и момент, внесённые внутренними стадиями. См.
         * cancelInternalSpin: там же замеры, из-за которых это появилось.
         */
        private const val CANCEL_INTERNAL_SPIN = true

        /**
         * Сколько раз за подшаг прогнать связи и контакт ВМЕСТЕ. См. общий цикл.
         *
         * ЧТО ЭТО СТОИТ, замер perfBench на теле 1900 клеток, без окна, с прогревом:
         *
         *     заходов   мс на тик   тиков/с   дрожь в покое   самопроникновение
         *        1         4.84       207         2.64              0.331
         *        2         6.79       147         0.088             0.486
         *        4        10.39        96         0.079             0.243
         *
         * То есть просадка в 2.15 раза, а не в четыре: решатель ограничений занимает
         * около 1.85 мс из 4.84, остальное это широкая фаза контактов с сеткой и CCD,
         * среда, интегрирование и восстановление скоростей. Каждый лишний заход
         * добавляет ровно 1.85 мс.
         *
         * Два захода дают почти всю пользу по дрожи за +40% времени, но оставляют
         * самопроникновение 0.486 при пороге 0.5, то есть без запаса вовсе.
         *
         * КУДА ЖАТЬ, ЕСЛИ ПОНАДОБИТСЯ ВЕРНУТЬ ВРЕМЯ. По убыванию отдачи:
         *
         *   1. Не гонять ВСЕ стадии каждый заход. Сходимости мешает пара
         *      «связи против контакта», а площади, изгиб и проекция кости внутри
         *      одного подшага меняются мало. Если оставить в повторениях только
         *      solveConstraints и solveContacts, а остальное звать один раз, заход
         *      подешевеет заметно: площадей 3402 против 4924 связей.
         *   2. Повторять только там, где есть контакты. Клетки без единого контакта
         *      сходятся с первого раза; список затронутых уже собирается в frcList.
         *   3. Ранний выход по невязке. Если за заход наибольшая поправка меньше
         *      порога, дальше идти незачем; в покое это оборвёт цикл на втором заходе.
         *   4. Широкая фаза раз в несколько подшагов вместо каждого. Она уже вынесена
         *      из цикла заходов, но всё ещё идёт каждый подшаг, а это сетка, DDA и CCD,
         *      то есть худшая локальность во всём тике.
         */
        private const val SOLVER_ITERS = 4
        /**
         * КАК ЧАСТО МЕНЯТЬ НАПРАВЛЕНИЕ ОБХОДА СВЯЗЕЙ: 0 — никогда, 1 — раз в подшаг,
         * 2 — каждый проход решателя. Переменная окружения RB_SWEEP.
         *
         * Чередовать нужно обязательно, иначе порядок связей сам по себе крутит тело —
         * подробности у sweepBackwards. Но ЧЕРЕДОВАНИЕ РАЗ В ПОДШАГ даёт свою беду:
         * у обхода вперёд и назад разные точки равновесия, и там, где связи между собой
         * не сходятся, вершина прыгает между ними каждый подшаг. Медуза с зажатой мышцей:
         * тело стоит (центр масс 0.0005 клетки/тик), а клетка #178 вечно скачет на 0.183
         * связи туда-сюда — 2.80 клетки/тик, то есть 84 клетки в секунду на месте.
         * Проходами это не лечится (8 проходов — 3.16, 16 — 3.01): дело не в сходимости,
         * а в том, что точек равновесия две.
         *
         * А дальше дрожание ВЫПРЯМЛЯЕТСЯ В ТЯГУ на контакте. Контакт односторонний: он
         * толкает и никогда не тянет, поэтому вершина, которая дёргается туда-сюда у
         * чужого тела, за каждый период отдаёт наружу чуть больше, чем получает. Игрок
         * это и увидел: две медузы едва коснулись — и разлетелись. По журналу, 17 эпизодов
         * касания: в 9 тела УСКОРЯЛИСЬ, пока касались, суммарно +0.031 клетки/тик из
         * ничего.
         *
         * 2 — МЕНЯТЬ НАПРАВЛЕНИЕ КАЖДЫЙ ПРОХОД. Внутри подшага получается симметричный
         * Гаусс-Зейдель: четыре прохода идут вперёд-назад-вперёд-назад, перекос порядка
         * гасится там же, где возникает, и между подшагами прыгать уже нечему. Стоит
         * ровно ноль — проходов столько же, просто индекс идёт в другую сторону.
         *
         * ЗАМЕРЫ (было при 1 / стало при 2):
         *   дрожание при зажатой мышце, медуза  2.796 -> 0.013 клетки/тик
         *   то же, body-export                  1.651 -> 0.000
         *   касания в журнале, ускорились       9 из 17 -> 0 из 13; сумма +0.031 -> -0.403
         *   самый долгий контакт                41 тик -> 413 тиков (тела лежат, а не бьются)
         *   самораскрутка за 30..90 с           замедление 273x -> 20533x
         *   внутренний импульс                  8.4e-10 -> 1.1e-11 рад/с
         *   гребок медузы                       653.6 -> 653.1 связи за 30 с
         *   гребок body-export                  52.4 -> 48.8 связи, порвано 4 -> 2
         * Зеркало SwimSolver держит тот же порядок — иначе тюнер считал бы другое тело.
         */
        private const val SWEEP_FLIP = 2

        /**
         * Порог смерти клетки в долях контактного радиуса соседа.
         *
         * Единица означает буквально «центр зашёл внутрь чужого радиуса». Меньше —
         * умирать будут только совсем провалившиеся, больше — начнут гибнуть просто
         * при сильном сжатии.
         */
        private const val KILL_DEPTH = 1.0

        /**
         * ГЛАВНЫЙ ВЫКЛЮЧАТЕЛЬ СМЕРТИ ОТ ПРОНИКНОВЕНИЯ. false — не умирает никто нигде,
         * даже там, где стенд просит об этом через killOnDeep. Порог см. KILL_DEPTH.
         */
        private const val KILL_ON_DEEP_OVERLAP = false

        /** Прикладывать контакт к скорости до интегрирования. См. toVelocity. */
        private const val CONTACT_BEFORE_INTEGRATE = false

        /** Тяга — ограничение с потолком, а не телепорт (см. SoftBodyWithBoneDemo). */
        /**
         * Потолок на скорость тяги мышью, мировых единиц В СЕКУНДУ.
         *
         * РАНЬШЕ ЭТО БЫЛ ПОТОЛОК НА ПОДШАГ (MAX_DRAG_STEP = 0.008), и это была мина.
         * Смысл константы молча зависел от числа подшагов: за тик вершину можно было
         * сдвинуть на SUBSTEPS * 0.008, то есть при 4 подшагах на 0.72 средней связи,
         * а при 32 — уже на 5.7. Тяга становилась в восемь раз резче просто оттого, что
         * поменяли деление времени, и тело начинало дрожать под курсором. Особенно
         * заметно на кости: у схваченной вершины matchWeight = 200, вся кость жёстко
         * идёт за ней, и рывок уходит в мягкую ткань целиком.
         *
         * Теперь величина выражена в единицах в СЕКУНДУ и от DT с SUBSTEPS не зависит
         * вовсе. Значение 4.0 выбрано не на глаз: столько же составляет верхняя граница
         * скорости частиц в движке, так что тяга по определению не может разогнать
         * вершину быстрее, чем бывает в самой симуляции. При прежних настройках
         * (4 подшага, 144 тика) старая константа давала 4.6 единиц в секунду — то есть
         * прежнее ощущение сохраняется, меняется только устойчивость к смене режима.
         */
        private const val MAX_DRAG_SPEED = 4.0
        /**
         * Податливость тяги мышью. БОЛЬШЕ — мягче.
         *
         * Было 1e-6, и это оказалось слишком жёстко. Доля зазора, закрываемая за подшаг,
         * равна 1/(1 + DRAG_COMPLIANCE/h^2); при 1e-6 и h = 1/960 это 52%, то есть
         * вершина за один подшаг почти прыгает на курсор. Дальше ткань — а у кости
         * projectBone, который идёт СЛЕДОМ и просто перезаписывает позицию жёсткой
         * позой, — утаскивает её назад, и следующий подшаг повторяет рывок.
         *
         * Получается ПИЛА С ЧАСТОТОЙ ПОДШАГОВ. Она была всегда, но раньше отрисовка
         * показывала только состояние на границе тика — одну точку из шестнадцати, и
         * пила в выборку не попадала. С интерполяцией по подшагам она стала видна.
         * То есть интерполяция дрожание не создала, а вскрыла.
         *
         * 1e-5 даёт около 10% за подшаг и примерно 81% за тик: тяга остаётся отзывчивой,
         * но перестаёт биться о ткань каждый подшаг.
         *
         * Настоящая причина глубже и не чинится константой: solveDrag стоит ПЕРЕД
         * projectBone, поэтому на кости его результат отменяется всегда. Правильно было
         * бы тянуть кость за её жёсткое тело целиком, а не за одну вершину, — но это
         * уже другая механика, и для стенда она не нужна.
         */
        private const val DRAG_COMPLIANCE = 1e-5

        /**
         * ГЛУБИНА СОКРАЩЕНИЯ МЫШЦЫ: во сколько раз укорачивается связь при полной активации.
         *
         * Было 0.200 — укорочение на 80%, и это рвало ткань собственной тягой. Стенд
         * PERF_GAIT на медузе: 226 порванных связей за 30 секунд, тело распадалось на 62
         * куска, соседние связи сжимались до 0.006 длины покоя при пороге разрыва 0.35
         * (LINK_CRUSH_RATIO). Все разрывы приходились на ПЕРВОЕ сокращение.
         *
         * Такие константы выбрал прежний подбор: зеркало SwimSolver топологию не меняет и
         * рвать не умеет, так что наказывать за разрыв было нечем. Теперь зеркало считает
         * худшее сжатие и растяжение (worstCrush, worstStretch), а тюнер бракует варианты
         * за порогами разрыва — и ищет ТОЛЬКО мышечные параметры, среда заморожена.
         *
         * Подбор дал 0.363 при скорости 15, но на настоящем теле это всё ещё рвало 70
         * связей: зеркало не знает ни разрыва, ни лопающихся от давления клеток. Дальше
         * искалось перебором прямо на настоящей физике, стендом PERF_GAIT.
         *
         * Медуза, 30 секунд гребка (порвано связей / проплыл крупнейший кусок, в связях):
         * было 226 / 12.9; 0.363 при 15 — 70 / 508; 0.45 при 15 — 2 / 687;
         * 0.46 при 12 — 0 / 436; 0.50 при 12 — 0 / 306; 0.55 при 15 — 0 / 335.
         * На 90 секундах выбранный набор держит запас: сжатие 0.627 при пороге 0.35,
         * растяжение 1.265 при пороге 1.30.
         *
         * ВТОРОЕ ТЕЛО (body-export) с этим набором тоже перестало рваться: было 42 связи и
         * 14 кусков, стало 0. Плывёт оно медленнее — 6.6 связи против 25.5, — но прежние
         * 25.5 оно и набирало, разрывая себя: ни один набор без разрывов не дал ему больше
         * 8.8. Мышцы у тел разные (2 кластера против 12), и общий набор для обоих —
         * компромисс; когда параметры станут свойством генома, каждому телу достанется своё.
         *
         * ПОСЛЕ ЗАХВАТА КРАЯ (MUSCLE_TOUCH = 1) мышца стала больше — у медузы 294
         * сокращающихся связи вместо 216, у body-export 1036 вместо 314, — и прежние 0.46
         * оказались для неё слишком глубокими: body-export рвал 26 связей. Развёртка на
         * настоящей физике, 30 секунд гребка, медуза / body-export (проплыл, в связях;
         * порвано): 0.46 — 760 / 63, 0 и 26; 0.47 — 735 / 67, 0 и 16; 0.48 — 709 / 55,
         * 0 и 26; 0.49 — 681 / 55, 0 и 16; 0.50 — 654 / 52, 0 и 4; 0.52 — 596 / 38,
         * 0 и 4; 0.58 — 385 / 21; 0.64 — 200 / 2.
         *
         * Выбрано 0.50: оба тела плывут кратно дальше прежнего (654 против 436 и 52
         * против 6.6), медуза не рвётся вовсе, а у body-export остаются ровно две пары
         * связей — вырожденные, см. ниже.
         *
         * ЧТО ИМЕННО РВЁТСЯ У body-export. Связи #929-#926 и #930-#927 (и их зеркала):
         * длина 0.125 при средней 0.593 — самая короткая и третья с конца из 2617 связей
         * выгрузки, клетки радиусом 0.5 стоят почти друг на друге. Порог считается в
         * ДОЛЯХ длины покоя, поэтому такой паре хватает разойтись на 0.04, то есть на 7%
         * средней связи. Это свойство самого тела, а не правила: та же пара рвётся и без
         * захвата края, стоит сделать сокращение чуть глубже (0.40 — рвётся она одна).
         * Чинить это в физике нечем, чинится в редакторе тела.
         *
         * ПЕРЕПРОВЕРЕНО после SWEEP_FLIP = 2 и сглаживания длины покоя по подшагам (см.
         * muscleScaleOf), 30 секунд гребка, медуза / body-export (проплыл; порвано):
         * 0.44 — 802 / 70, 0 и 12; 0.46 — 752 / 59, 0 и 14; 0.48 — 699 / 44, 0 и 12;
         * 0.50 — 643 / 30, 0 и 0. Глубже 0.50 второе тело снова рвётся и распадается на
         * 10 кусков вместо 8, поэтому 0.50 остаётся.
         */
        private const val MUSCLE_CONTRACTION = 0.50
        /**
         * МЫШЦА ЗАХВАТЫВАЕТ КРАЙ. 0 — нет, 1 — кластер растёт на кольцо треугольников,
         * 2 — бахрома. Переменная окружения RB_TOUCH.
         *
         * Связь сокращается, когда ОБА её конца в одном кластере, треугольник — когда все
         * три вершины. Из-за этого стык мышцы с костью оставался обычной тканью: мышца
         * тянула не кость, а шов, который тянул кость. Шов и рвался — см.
         * TENDON_TEAR_FACTOR. На экране мышца тоже выглядела уже, чем в редакторе.
         *
         * 1 — КЛАСТЕР РАСТЁТ. Треугольник, у которого хотя бы одна вершина мышечная,
         * целиком уходит в кластер: его вершины становятся клетками мышцы, и дальше всё
         * считается прежним правилом. Мышца остаётся сплошной областью, просто на кольцо
         * шире, и кость на её краю тянется мышцей напрямую.
         *
         * 2 — БАХРОМА: мышечным считается само ограничение, если мышечная хотя бы одна
         * его клетка. Звучит так же, но это НЕСОГЛАСОВАННО. У треугольника с одной
         * мышечной вершиной сокращаются две стороны из трёх, а площадь — как у целой
         * мышцы: третья сторона длину держит, и треугольнику остаётся только схлопнуться
         * по высоте. Первый замер на body-export: 36 связей рвалось на нулевом же тике,
         * худшая сжата до 0.132 длины покоя при пороге 0.35. Оставлено для сравнения.
         *
         * СКОЛЬКО ДАЁТ. 30 секунд гребка, проплыл крупнейший кусок (в связях) / порвано,
         * при сокращении 0.46: медуза 436 / 0 без захвата, 760 / 0 режимом 1, 767 / 0
         * режимом 2; body-export 6.6 / 0 без захвата, 63 / 26 режимом 1, 13 / 8 режимом 2.
         * Режим 1 быстрее режима 2 там, где мышц много и они сходятся вплотную, и он же
         * согласован по построению. Со сжатием 0.50 разрывы уходят, см. MUSCLE_CONTRACTION.
         *
         * ТРИ МЕЛОЧИ, БЕЗ КОТОРЫХ РЕЖИМ 1 РВЁТ ТЕЛО, — каждая измерена отдельно:
         * площадь у кости не сокращается (см. muscleOfTri), шов между соседними мышцами
         * сокращается (см. muscleOfPair), и само сжатие уменьшено с 0.46 до 0.50.
         */
        private const val MUSCLE_TOUCH = 1
        /**
         * Скорость сокращения и РАСПРЯМЛЕНИЯ, 1/сек — намеренно разные.
         *
         * Резкий гребок и медленный возврат: рабочая фаза идёт быстро и на квадратичном
         * сопротивлении даёт большой импульс, возвратная — медленно и почти не гребёт.
         * Это и есть асимметрия по времени, которой пользуются рыбы и медузы.
         *
         * Работает и БЕЗ квадратичной части — замер дал 3.1x на чисто линейной модели
         * (см. таблицу у NORMAL_DRAG_QUADRATIC). Вместе они складываются до 4.4x.
         *
         * СКОЛЬКО ИМЕННО. Развёртка по отношению скоростей, период гребка 48 кадров,
         * путь центра масс за 10 секунд:
         *
         *      1x (симметрично)  ->  0.221
         *      3x                ->  0.418   максимум
         *      5x                ->  0.391   (стоит сейчас)
         *     10x                ->  0.099
         *     20x                ->  0.118
         *
         * Выше 5x тяга ОБВАЛИВАЕТСЯ, и это не случайность: при rate = 2.5 постоянная
         * времени распрямления равна 0.4 с, а весь цикл длится 0.33 с. Мышца просто
         * не успевает разжаться до следующего гребка, остаётся полусокращённой, и
         * амплитуда взмаха схлопывается. То есть предел задаёт не физика среды, а
         * соотношение с ПЕРИОДОМ: распрямление обязано укладываться в возвратную фазу.
         * Поменяете период гребка — оптимум сместится.
         */
        /**
         * Период автоматического гребка В КАДРАХ и доля периода на рабочую фазу.
         *
         * Доля была захардкожена третью, теперь это параметр: поиск её и подобрал.
         *
         * Таблицы у NORMAL_DRAG_QUADRATIC и MUSCLE_RATE_RELAX мерились при периоде 48
         * и DT = 1/144. Меняете период — оптимум асимметрии сместится: распрямление
         * обязано укладываться в возвратную фазу, иначе амплитуда взмаха схлопывается.
         *
         * ПРОВЕРКА, КОТОРУЮ СТОИТ ДЕЛАТЬ ВСЕГДА при смене этой пары: помещается ли
         * распрямление в возвратную фазу. Здесь возвратная фаза равна
         * 104 * (1 - 0.402) = 62 кадра = 0.43 с, а постоянная времени распрямления
         * 1/35.3 = 0.028 с, то есть влезает с запасом в 15 раз. Ровно на этом
         * ПЕРВЫЙ прогон поиска и сломался: он выдал распрямление 0.4/с при периоде
         * 16 кадров, мышца не разжималась вообще, гребка не было, а метрика скорости
         * зачла разовый толчок с последующим выкатом. SwimTuner теперь печатает размах
         * активации в замерном окне — при этих значениях он равен 1.0, то есть мышца
         * действительно ходит от нуля до полного сокращения.
         */
        // 43 кадра при 60 UPS = 0.722 с — тот же период В СЕКУНДАХ, при котором тюнер
        // искал остальные константы. Задан в КАДРАХ, поэтому при смене DT его надо
        // пересчитывать, иначе молча меняется само существо, а не настройки решателя.
        // Период и рабочая доля подобраны там же, см. MUSCLE_CONTRACTION. При периоде 8 доли
        // 0.40 и 0.47 дают одно и то же: рабочая фаза округляется до трёх тиков.
        private const val GAIT_PERIOD = 8
        private const val GAIT_DUTY = 0.45

        // Скорость сокращения 15 (потолок) рвала медузу даже при мягкой глубине: первый взмах
        // слишком резкий. 12 — граница, на которой разрывов уже нет. См. MUSCLE_CONTRACTION.
        private const val MUSCLE_RATE_CONTRACT = 12.0
        private const val MUSCLE_RATE_RELAX = 8.546

        /** Радиусы захвата масштабируются от средней связи: тело мельче синтетического. */
        private const val PICK_FACTOR = 1.2f
        private const val EDGE_PICK_FACTOR = 0.8f

        /**
         * УСКОРЕНИЕ СИМУЛЯЦИИ (клавиша F): сколько миллисекунд кадра отдавать физике.
         *
         * Ускорение сделано БЮДЖЕТОМ ВРЕМЕНИ, а не множителем шагов, и это важно.
         * Множитель пришлось бы подбирать под машину: слишком маленький — ждёшь зря,
         * слишком большой — кадр не укладывается, окно перестаёт отвечать и наблюдать
         * уже нечего. Бюджет даёт ровно ту скорость, которую машина может, и сам
         * подстраивается, если рядом запустили что-то тяжёлое.
         *
         * 10 мс при 144 кадрах в секунду: кадр длится 6.9 мс, так что частота просядет
         * примерно до 80, а физика получит около 1400 шагов в секунду вместо 144, то есть
         * ускорение примерно в 10 раз. Точное достигнутое число показывается в HUD —
         * подбирать эту константу на глаз не нужно, достаточно посмотреть на «x».
         */
        private const val FAST_BUDGET_MS = 10L

        /**
         * Предохранитель: больше этого числа шагов за кадр не делать НИ ПРИ КАКИХ
         * условиях. Нужен на случай, когда System.nanoTime идёт грубо или кадр уже
         * просрочен — без него цикл мог бы уйти в тысячи шагов и подвесить окно.
         */
        private const val FAST_MAX_STEPS = 4096

        /** Потолок на догон после подвисания, секунды. Больше — не отрабатываем. */
        private const val MAX_CATCHUP = 0.25

        /**
         * Сколько организмов создать из одного файла тела.
         *
         * Копии независимы: связей между ними нет, кластеры костей и мышц у каждой
         * свои, решатель обходится с ними как с разными телами. Нужны, чтобы проверять
         * МЕЖОРГАНИЗМЕННЫЕ контакты — самоконтакт границы и так работал, а вот встреча
         * двух тел до сих пор не проверялась ничем.
         *
         * Мышцы у копий управляются вместе (гребок G, цифры), а наведением мыши — по
         * отдельности: hoveredMuscle указывает на конкретный кластер.
         */
        private const val ORGANISMS = 2

        /**
         * СВОБОДНЫЕ ЧАСТИЦЫ — проверка непроницаемости контура вручную.
         *
         * Тащишь такую мышью в бок организма и смотришь, пролезет или нет. Связного
         * тела для этой проверки мало: его частицы держат соседи, и внутрь чужого
         * тела его не пускает вся сетка связей сразу, а не только контакт. Одиночную
         * не держит ничто, поэтому дыру в контуре она находит честно.
         *
         * Стоят рядом с телами, каждая — сам себе связная компонента, то есть
         * отдельный организм со своим запасом среды.
         */
        private const val FREE_PARTICLES = 6

        private const val VIEW_WIDTH = 3.4f
        private const val VIEW_HEIGHT = 2.125f

        private val BG            = Color.valueOf("12161E")
        private val GROUND_COLOR  = Color.valueOf("2B3341")
        private val SOFT_FILL     = Color.valueOf("5A96DC44")
        private val LINK          = Color.valueOf("96B4DC2A")
        private val BONE_FILL     = Color.valueOf("E8A33DAA")
        private val BONE_FILL_OFF = Color.valueOf("E8A33D25")
        private val MUSCLE_FILL   = Color.valueOf("D65A6BCC")
        private val MUSCLE_IDLE   = Color.valueOf("9E5560AA")
        private val INVERTED_FILL = Color.valueOf("FF3B30EE")
        private val DOT           = Color.valueOf("DFE6F055")
        private val ACTIVE        = Color.valueOf("FFFFFFFF")
        private val HUD_TEXT      = Color.valueOf("EAF0F8FF")
        private val HUD_MUTED     = Color.valueOf("76818FFF")
        private val HUD_WARN      = Color.valueOf("E8A33DFF")
        private val MARK_COLOR    = Color.valueOf("FF4FD8FF")
        private val BOUNDARY_COLOR = Color.valueOf("4BE08AFF")
        private val BEND_COLOR     = Color.valueOf("E8A33D88")
        private val CONTACT_COLOR  = Color.valueOf("4BE08A22")
    }

    private lateinit var body: BodyFile

    // --- частицы (SoA) ---
    private var n = 0
    private lateinit var px: DoubleArray
    private lateinit var py: DoubleArray
    private lateinit var prevX: DoubleArray
    private lateinit var prevY: DoubleArray
    private lateinit var vx: DoubleArray
    private lateinit var vy: DoubleArray
    private lateinit var invMass: DoubleArray

    /** Обратная масса позы покоя: из радиуса клетки, см. buildMasses(). */
    private lateinit var restInvMass: DoubleArray

    // --- самоконтакт границы ---
    private var contacts: BoundaryContacts? = null
    /** Связи ЦЕЛОГО тела: снимается один раз и переживает все пересборки. */
    private var everLinked: Set<Long>? = null
    private var contactsOn = CONTACTS_ON
    private lateinit var radius: DoubleArray

    /** Клетка без единой связи — свободная частица, см. FREE_PARTICLES. */
    private lateinit var isFree: BooleanArray

    /**
     * УМЕРШИЕ КЛЕТКИ: центр зашёл внутрь радиуса чужой. См. killOnDeep в контактах.
     *
     * Смерть тут окончательная и означает три вещи: все связи клетки объявлены
     * мёртвыми, из контактного множества она исключена, и её не рисуют. Физически
     * она остаётся в массивах — выкидывать клетку из середины значило бы
     * перенумеровать всё тело, а на это завязаны кости, мышцы и организмы.
     */
    private lateinit var cellDead: BooleanArray
    private var deadCount = 0
    /** Максимальная длина каждой связи: LINK_MAX_STRETCH * длина покоя. */
    private lateinit var conMaxLen: DoubleArray
    private lateinit var matchWeight: DoubleArray
    private lateinit var inContact: BooleanArray

    // --- связи ---
    private var conCount = 0
    private lateinit var conA: IntArray
    private lateinit var conB: IntArray
    private lateinit var conRest: DoubleArray
    private lateinit var conMuscle: IntArray

    // --- граничные рёбра (омываемая поверхность) ---
    // --- изгиб граничного контура ---
    /** Пары «через одну» вдоль границы и расстояние между ними в позе покоя. */
    private var bendCount = 0
    private lateinit var bendA: IntArray
    private lateinit var bendB: IntArray
    private lateinit var bendRest: DoubleArray

    /** Индекс в BEND_LEVELS. 0 — выключено. Переключается клавишей E. */
    private var bendLevel = 0

    /** Текущая податливость изгиба. Отдельным методом — его читает сверка в SwimTuner. */
    private fun bendCompliance(): Double = BEND_LEVELS[bendLevel]

    private var boundCount = 0
    private lateinit var boundA: IntArray
    private lateinit var boundB: IntArray

    /**
     * ОДИН вектор скорости увлечённой среды на организм. Не на ребро.
     *
     * ИСТОРИЯ ЭТОГО ПОЛЯ — ЭТО ИСТОРИЯ ПОИСКА ИСТОЧНИКА БЛУЖДАНИЯ, поэтому она здесь.
     * Замер, который всё решает: тело жёстко вращают вокруг центра масс, решатель
     * отключён, работает только сопротивление среды. Сила от среды в системе тела при
     * этом ПОСТОЯННА, в мировой крутится вместе с телом, значит импульс за полный оборот
     * обязан вернуться в ноль. Что получалось:
     *
     *     памяти среды нет вовсе                        ->  0.001   (эталон)
     *     скаляр «вдоль нормали ребра»  (было сначала)  ->  870
     *     вектор в мировых осях, но у каждого ребра      ->  308
     *     один общий запас, заряжаемый ОТ РЁБЕР         ->  815
     *     один общий запас, заряжаемый ОТ СКОРОСТИ ЦМ   ->  0.089  (стоит сейчас)
     *
     * Импульс 870 на массе 370 — это 2.35 единицы скорости ИЗ НИОТКУДА, разово, за один
     * поворот тела. Вот откуда было «тело вдруг поехало не туда»: организм повернулся,
     * и накопитель среды выдал ему толчок в стороне, никак не связанной с гребком.
     *
     * ЧЕТВЁРТАЯ СТРОКА — САМАЯ ПОУЧИТЕЛЬНАЯ. Сделать запас общим НЕ ПОМОГАЕТ: 815 против
     * 833. Значит дело было не в том, что запасов много, а в том, ОТ ЧЕГО они заряжаются.
     * Пока запас питается импульсами на рёбрах, вращение в него попадает, потому что
     * рёбра при вращении движутся.
     *
     * ЧТО РАБОТАЕТ. Заряжать запас от скорости ЦЕНТРА МАСС. Тогда:
     *   - при чистом вращении скорость ЦМ равна нулю, запас не заряжается ВООБЩЕ, и
     *     поворотного толчка нет ПО ПОСТРОЕНИЮ, а не по удачному подбору констант;
     *   - запас всегда сонаправлен с уже имеющимся движением тела, поэтому подтолкнуть
     *     тело он может только ВПЕРЁД по его же курсу. Это накат, а не блуждание:
     *     «в случайную сторону» тут физически неоткуда взяться;
     *   - эффект, ради которого память среды и вводилась, сохраняется полностью —
     *     разогнанное тело какое-то время несёт разогнанная им же среда. Доля скорости,
     *     сохраняемая после прекращения гребков, выросла с 0.148 до 0.649.
     *
     * ПОЧЕМУ ТЯГА НЕ СТРАДАЕТ от вычитания общего вектора: тяга живёт на ЛОКАЛЬНЫХ
     * скоростях плавника (0.24..1.9), а вычитается величина порядка скорости корпуса
     * (около 0.01) — на два порядка меньше.
     *
     * ЧТО ЕЩЁ ПРОБОВАЛОСЬ И ОТВЕРГНУТО: присоединённая порция среды у каждого ребра
     * с массой и строго симметричным обменом. Наивная версия расходится в NaN (отношение
     * масс 90:1), через приведённую массу устойчива, но разовый толчок оказался
     * ПРОПОРЦИОНАЛЕН массе порции (70 при массе 10, 250 при 40, 1068 при 400), а
     * повторяемость гребка развалилась с 1% до 40..55%.
     */
    /**
     * К какому организму принадлежит частица. Связные компоненты графа связей.
     *
     * Нужны, потому что запас увлечённой среды обязан быть СВОИМ у каждого тела.
     * Пока организм был один, разницы не существовало и здесь стоял один скаляр на
     * весь мир — и это оказалось прямой ошибкой: два тела делили один запас, поэтому
     * движение одного толкало другое НА ЛЮБОМ РАССТОЯНИИ, а тяга у обоих падала,
     * потому что запас следовал за средней скоростью пары, а не за своей.
     *
     * В движке это ровно те же острова, которые понадобятся для сна и для разбиения
     * по аренам.
     */
    private lateinit var organismOf: IntArray
    private var organismCount = 0
    private lateinit var organismSize: IntArray
    private lateinit var organismMass: DoubleArray

    private lateinit var flowVX: DoubleArray
    private lateinit var flowVY: DoubleArray
    /** Номера организмов и их запас ДО перенумерации — по ним куски наследуют накат. */
    private var orgPrev = IntArray(0)
    private var orgSeed = IntArray(0)
    private var orgFlowX = DoubleArray(0)
    private var orgFlowY = DoubleArray(0)
    /** Черновик под сумму скоростей организма. Заводится один раз, в цикле не аллоцируется. */
    private lateinit var comAccX: DoubleArray
    private lateinit var comAccY: DoubleArray

    // ================================================================
    //  ТОПОЛОГИЯ ХРАНИТСЯ СВОЯ, А НЕ ЧИТАЕТСЯ ИЗ BodyFile.
    //
    //  BodyFile — это ВЫГРУЗКА, снимок из редактора, и он неизменен. Ткань же
    //  рвётся: связи и треугольники исчезают, контур перестраивается, тело может
    //  распасться надвое. Поэтому здесь лежат СОБСТВЕННЫЕ изменяемые копии, а из
    //  body берутся только позы покоя, радиусы и кластеры.
    //
    //  В движке это ровно та же развилка: топология живая и меняется, а выгрузка
    //  редактора остаётся исходником.
    // ================================================================
    private lateinit var lnkA: IntArray
    private lateinit var lnkB: IntArray
    private var lnkCount = 0

    private lateinit var triA: IntArray
    private lateinit var triB: IntArray
    private lateinit var triC: IntArray
    private lateinit var triRestArea2: FloatArray
    private var triCount = 0

    /**
     * Запечённая топология целого тела и что в ней ещё живо. Живые списки выше — её
     * сжатые копии в исходном порядке; рядом с каждым лежит номер в запечённой. См.
     * BakedTopology и rebuildAfterTear.
     */
    private lateinit var baked: BakedTopology
    /** Ребро каждой связи полного списка. */
    private var lnkEdge = IntArray(0)
    /** Номер каждого живого треугольника в выгрузке. */
    private var triId = IntArray(0)
    /** Ребро каждой рабочей связи решателя. */
    private var conEdge = IntArray(0)
    /** Рабочая связь на ребре, -1 — нет. Отрисовке порванного и разбору журнала. */
    private var conOfEdge = IntArray(0)
    /** Кандидаты касания в позе покоя: запекаются один раз на тело. */
    private var restPairs: RestPairs? = null

    // --- треугольники ---
    private lateinit var triMuscle: IntArray
    private lateinit var triInverted: BooleanArray
    private var invertedNow = 0
    private var invertedPeak = 0

    // --- кости ---
    /**
     * Только кластеры, которые могут быть жёсткими. Кластер из одной клетки отбрасывается:
     * поворот по единственной точке не определён, проекция стала бы тождеством, а строка
     * в списке создавала бы ложное впечатление, что кость есть.
     */
    private lateinit var rigidBones: Array<IntArray>
    private var degenerateBones = 0

    /** Номер кости у вершины, -1 если не в жёсткой кости. */
    private lateinit var boneOf: IntArray

    /**
     * Поза покоя каждой кости — смещения от её центроида, предпосчитанные один раз.
     *
     * Это то самое r0, которое в движке надо запечь в BakedLayout. Здесь оно не только
     * экономит работу: сумма w*q0 досажена в НОЛЬ ровно во float, и без этого зачёт
     * поправки в projectBone не имел бы смысла — см. её комментарий.
     */
    private lateinit var boneRestQx: Array<DoubleArray>
    private lateinit var boneRestQy: Array<DoubleArray>

    /** Черновик поправок самой большой кости. Заводится один раз, в горячем цикле не аллоцируется. */
    private lateinit var boneDx: DoubleArray
    private lateinit var boneDy: DoubleArray

    // --- мышцы ---
    private lateinit var muscleOf: IntArray
    private lateinit var muscleActivation: DoubleArray
    private var hoveredMuscle = -1

    /**
     * Куда каждая мышца едет в этом кадре: 1 — сокращаться, 0 — распрямляться.
     *
     * Отдельно от muscleActivation, потому что источников команды теперь три —
     * наведение мышью, цифровые клавиши и автоматический гребок, — и они должны
     * складываться, а не перебивать друг друга.
     */
    private lateinit var muscleTarget: DoubleArray

    /** Автоматический ритмичный гребок (клавиша G). */
    private var gait = false
    private var gaitFrame = 0

    private var bonesRigid = true
    private var paused = false
    private var viewMode = 0

    // --- ускорение симуляции и наблюдение за дрейфом ---
    private var fastForward = false

    /** Сколько шагов физики уложилось в кадр. Сглаженное — мгновенное слишком дёргается. */
    private var stepsAvg = 1f

    /**
     * СИМУЛИРОВАННОЕ время, а не настоящее. При ускорении они расходятся в разы, и
     * смотреть на дрейф надо именно по этому: «уехал на столько-то за 200 секунд
     * своей жизни» — величина, воспроизводимая между запусками и сравнимая с цифрами
     * из PhysicsAudit. Настоящее время наблюдения не значит ничего.
     */
    /** Долг нерасходованного реального времени. См. аккумулятор в render(). */
    private var accumulator = 0.0

    // --- интерполяция отрисовки ---
    /** История позиций по подшагам: SUBSTEPS + 1 состояний за тик. См. fx(). */
    private lateinit var histX: Array<DoubleArray>
    private lateinit var histY: Array<DoubleArray>
    private var histCount = 0

    /** Доля тика, уже покрытая реальным временем. 0 — начало тика, 1 — конец. */
    private var renderAlpha = 0.0

    /**
     * Режим интерполяции: 0 — выключена (сырое состояние физики), 1 — по границам
     * тиков, 2 — по подшагам. Переключается клавишей I.
     *
     * ПО УМОЛЧАНИЮ 1, И ЭТО ПРАВИЛЬНЫЙ ВЫБОР, а не компромисс.
     *
     * Цена режима 2 — не память, а КЭШ. Снимок за подшаг копирует 2*n чисел; при 16
     * подшагах и 947 частицах это 242 КБ за тик, то есть 7.3 МБ/с при 30 UPS. Сама
     * пропускная способность копеечная, но это копирование каждый подшаг вымывает из
     * кэша ровно те массивы, по которым работает решатель. Режиму 1 нужны ДВА снимка на
     * тик вместо семнадцати.
     *
     * Точность при этом почти не теряется. Хорда вместо дуги врёт тем сильнее, чем
     * больше тело успевает повернуться за тик, а при верхней границе скорости 4
     * единицы в секунду и 30 UPS за тик проходится 0.13 единицы при клетке 1 — срезать
     * там нечего. Режим 2 нужен, если тик станет длинным или появятся быстро
     * вращающиеся обломки.
     *
     * И отдельно он полезен как ДИАГНОСТИКА: если дрожание видно на 2 и пропадает на 1,
     * значит это пила внутри тика — что-то бьётся с частотой подшагов, обычно тяга
     * против projectBone. Если видно на всех трёх — дрожит сама физика, и смотреть надо
     * не на отрисовку.
     */
    private var interpMode = 1

    /** Заполнены ли промежуточные слоты истории. Нужно на кадр после переключения. */
    private var histHasSubsteps = false

    private val controls = SimControls()

    private var simTime = 0.0

    /** Где был центр масс на сбросе. Дрейф считается от него. */
    private var startCx = 0.0
    private var startCy = 0.0

    private lateinit var shapes: ShapeRenderer
    private lateinit var batch: SpriteBatch
    private lateinit var font: BitmapFont
    private lateinit var viewport: FitViewport
    private lateinit var camera: OrthographicCamera
    private lateinit var hudCamera: OrthographicCamera
    private val tmp = Vector3()
    private val tmpColor = Color()
    private val tmpColor2 = Color()

    private var dragId = -1
    private var hoverId = -1
    private var mouseX = 0.0
    private var mouseY = 0.0
    private var wasTouched = false

    private var pickRadius = 0.05f
    private var edgePickRadius = 0.03f

    // =================================================================
    //  ПОСТРОЕНИЕ ИЗ ФАЙЛА
    // =================================================================

    private fun buildFromFile() {
        body = BodyFile.load(bodyPath, copies = copies, freeParticles = freeParticles)
        n = body.count
        cellDead = BooleanArray(n)

        px = DoubleArray(n); py = DoubleArray(n)
        prevX = DoubleArray(n); prevY = DoubleArray(n)
        vx = DoubleArray(n); vy = DoubleArray(n)
        invMass = DoubleArray(n); matchWeight = DoubleArray(n)
        inContact = BooleanArray(n)

        boneOf = IntArray(n) { -1 }
        muscleOf = IntArray(n) { -1 }

        // Жёсткими считаются кластеры от трёх клеток: две дают лишь жёсткий стержень,
        // то есть ровно то же, что обычная связь, и заводить ради них проекцию незачем.
        val rigid = body.boneClusters.filter { it.size >= 3 }
        degenerateBones = body.boneClusters.size - rigid.size
        rigidBones = rigid.toTypedArray()
        rigidBones.forEachIndexed { b, ids -> for (i in ids) boneOf[i] = b }
        buildBoneRestPose()

        body.muscleClusters.forEachIndexed { m, ids -> for (i in ids) muscleOf[i] = m }
        growMuscles()
        muscleActivation = DoubleArray(body.muscleClusters.size)
        muscleScaleOf = DoubleArray(body.muscleClusters.size) { 1.0 }
        muscleTarget = DoubleArray(body.muscleClusters.size)

        // Свои копии топологии: дальше они живут отдельно от выгрузки и меняются
        // при разрывах. См. объявления выше.
        lnkCount = body.linkCount
        lnkA = body.linkA.copyOf(); lnkB = body.linkB.copyOf()
        triCount = body.triCount
        baked = BakedTopology(body)
        lnkEdge = baked.linkEdge.copyOf()
        triId = IntArray(triCount) { it }
        triA = body.triA.copyOf(); triB = body.triB.copyOf(); triC = body.triC.copyOf()
        triRestArea2 = body.triRestArea2.copyOf()

        // --- связи: внутрикостные не создаются, их держит проекция ---

        val a = ArrayList<Int>(lnkCount)
        val b = ArrayList<Int>(lnkCount)
        val rest = ArrayList<Double>(lnkCount)
        val mus = ArrayList<Int>(lnkCount)
        val ed = ArrayList<Int>(lnkCount)
        for (k in 0 until lnkCount) {
            val i = lnkA[k]
            val j = lnkB[k]
            if (boneOf[i] != -1 && boneOf[i] == boneOf[j]) continue
            val dx = body.x[i] - body.x[j]
            val dy = body.y[i] - body.y[j]
            a.add(i); b.add(j); rest.add(sqrt((dx * dx + dy * dy).toDouble())); ed.add(lnkEdge[k])
            mus.add(muscleOfPair(i, j))
        }
        conCount = a.size
        conA = a.toIntArray(); conB = b.toIntArray()
        conRest = rest.toDoubleArray(); conMuscle = mus.toIntArray()
        conEdge = ed.toIntArray()

        triMuscle = IntArray(triCount) { t -> muscleOfTri(triA[t], triB[t], triC[t]) }
        triInverted = BooleanArray(triCount)

        buildBoundary()
        buildBend(); buildFlaps()
        buildMasses()
        buildOrganisms()
        buildContacts()
        histX = Array(SUBSTEPS + 1) { DoubleArray(n) }
        histY = Array(SUBSTEPS + 1) { DoubleArray(n) }

        pickRadius = body.meanLinkLength * PICK_FACTOR
        edgePickRadius = body.meanLinkLength * EDGE_PICK_FACTOR

        if (!quiet) println("[RealBodyDemo] " + body.describe())
        if (!quiet) println("[RealBodyDemo] rigid bones = ${rigidBones.size}, degenerate clusters dropped = $degenerateBones" +
            ", largest = ${rigidBones.maxOfOrNull { it.size } ?: 0} cells (drag on it is that many times weaker)")
        if (!quiet) {
            var mc = 0
            for (i in 0 until n) if (muscleOf[i] >= 0) mc++
            var cm = 0
            for (c in 0 until conCount) if (conMuscle[c] >= 0) cm++
            var tm = 0
            for (t in 0 until triCount) if (triMuscle[t] >= 0) tm++
            println("[RealBodyDemo] muscle cells = $mc (grown from ${body.muscleClusters.sumOf { it.size }}, edge grab $muscleTouch)" +
                ", contracting links = $cm, contracting triangles = $tm")
        }
    }

    /**
     * Пары изгиба вдоль границы: соседи «через одну» и расстояние между ними в позе покоя.
     *
     * Обходить контур по порядку не требуется и было бы хрупко — у рваных краёв и
     * развилок порядок неоднозначен. Достаточно локального признака: вершина, у которой
     * ровно ДВА граничных ребра, лежит внутри гладкого участка контура, и её соседи
     * через одну образуют пару. Вершины развилок (три и более граничных ребра)
     * пропускаются: там «изгиб» не определён.
     */
    /**
     * МАССА ИЗ РАДИУСА КЛЕТКИ. Раньше у всех стояла единица, а body.radius разбирался
     * из файла и не использовался нигде.
     *
     * Масса берётся пропорционально ПЛОЩАДИ, то есть квадрату радиуса — мир двумерный,
     * и клетка вдвое большего радиуса весит вчетверо больше, а не вдвое.
     *
     * НОРМИРОВКА НА СРЕДНЮЮ МАССУ ОБЯЗАТЕЛЬНА. Все подобранные константы — податливости,
     * сопротивление среды, вязкость, скорости мышц — взаимодействуют с массой. Если
     * задать массу в абсолютных единицах радиуса, весь набор придётся подбирать заново
     * просто оттого, что редактор сохранил клетки другого размера. При нормировке
     * средняя масса всегда единица, и константы остаются переносимыми между телами.
     *
     * НА ТЕКУЩЕМ ТЕЛЕ ЭТО ТОЖДЕСТВЕННОЕ ПРЕОБРАЗОВАНИЕ: у всех 370 клеток радиус 0.5,
     * значит после нормировки у всех ровно 1.0, и ни одно измеренное число не меняется.
     * Это и хорошо — механизм заводится, а настройки не сбиваются. Разница появится
     * на телах, где геном вырастил клетки разного размера.
     */
    /**
     * Строит самоконтакт и предельные длины связей.
     *
     * Предел длины считается на КАЖДУЮ связь отдельно, а не общим числом: радиусы у
     * клеток разные, и общий предел был бы неверен для обеих сторон сразу.
     */
    /**
     * Связные компоненты графа связей — это и есть отдельные организмы.
     *
     * ПОЛНЫЙ ОБХОД ТОЛЬКО ПРИ РАСПАДЕ. Разрыв чаще всего ничего не разделяет: концы
     * порванного ребра остаются связаны через соседний треугольник. Поэтому сначала
     * дешёвая проверка (см. splits), и лишь если кусок действительно отвалился —
     * разметка заново. Смежность берётся из запечённой топологии, строить её на каждую
     * пересборку больше не нужно.
     *
     * Смежность по ПОЛНОМУ списку связей, а не по conA/conB: внутрикостные связи в
     * решатель намеренно не попадают (их держит проекция кости), и по ним кости
     * распались бы на отдельные компоненты. На двух телах это давало 126 «организмов»
     * вместо двух.
     */
    private fun buildOrganisms(relabel: Boolean = true) {
        if (!::organismOf.isInitialized || organismOf.size != n) {
            organismOf = IntArray(n); orgQueue = IntArray(n)
        }
        var comp = organismCount
        if (relabel) {
            // Кто чем был ДО перенумерации — по этому куски унаследуют запас среды.
            if (orgPrev.size != n) { orgPrev = IntArray(n); orgSeed = IntArray(n) }
            System.arraycopy(organismOf, 0, orgPrev, 0, n)
            java.util.Arrays.fill(organismOf, -1)
            val vs = baked.vertStart; val vo = baked.vertOther; val ve = baked.vertEdge
            val dead = baked.edgeDead
            val queue = orgQueue
            comp = 0
            for (s in 0 until n) {
                if (organismOf[s] != -1) continue
                orgSeed[comp] = s
                var head = 0; var tail = 0
                organismOf[s] = comp; queue[tail++] = s
                while (head < tail) {
                    val v = queue[head++]
                    for (k in vs[v] until vs[v + 1]) {
                        if (dead[ve[k]]) continue
                        val u = vo[k]
                        if (organismOf[u] == -1) { organismOf[u] = comp; queue[tail++] = u }
                    }
                }
                comp++
            }
            organismCount = comp
        }
        // Ёмкость держится по числу клеток: больше компонент, чем клеток, не бывает.
        val fresh = !::organismSize.isInitialized || organismSize.size < n
        if (fresh) {
            organismSize = IntArray(n); organismMass = DoubleArray(n)
            flowVX = DoubleArray(n); flowVY = DoubleArray(n)
            comAccX = DoubleArray(n); comAccY = DoubleArray(n)
        }
        // КУСОК УНАСЛЕДУЕТ ЗАПАС СРЕДЫ У ТОГО, ИЗ КОГО ВЫШЕЛ.
        //
        // Раньше запас здесь просто обнулялся всем. А зовётся эта разметка при ЛЮБОМ
        // разрыве, и обнуление стояло вне проверки на распад, поэтому одна порванная
        // связь где угодно в сцене стирала накат у ВСЕХ тел, включая целые и далёкие.
        // Замер (стенд PERF_FLOW): медуза после 10 с гребка, запас 0.663; рвём одну
        // связь, ничего не распадается, организмов как было 8 — запас 0.068, и 2.4
        // секунды обратно. Тело вдруг снова чувствует полное сопротивление и тормозит
        // из-за события, к нему не относящегося.
        //
        // Запас — это СКОРОСТЬ увлечённой воды, а не её импульс: за разгон среды тело уже
        // заплатило (см. FLOW_MASS в applyNormalDrag), и ничего не дублируется оттого, что
        // обе половины получат одну и ту же скорость. Сразу после распада половины и
        // движутся примерно с прежней скоростью, так что это как раз непрерывное
        // продолжение, а обнуление было разрывом.
        if (relabel && !fresh) {
            if (orgFlowX.size < n) { orgFlowX = DoubleArray(n); orgFlowY = DoubleArray(n) }
            System.arraycopy(flowVX, 0, orgFlowX, 0, n)
            System.arraycopy(flowVY, 0, orgFlowY, 0, n)
            for (o in 0 until comp) {
                val was = orgPrev[orgSeed[o]]
                if (was < 0) { flowVX[o] = 0.0; flowVY[o] = 0.0 }
                else { flowVX[o] = orgFlowX[was]; flowVY[o] = orgFlowY[was] }
            }
        }
        java.util.Arrays.fill(organismSize, 0, comp, 0)
        java.util.Arrays.fill(organismMass, 0, comp, 0.0)
        java.util.Arrays.fill(comAccX, 0, comp, 0.0)
        java.util.Arrays.fill(comAccY, 0, comp, 0.0)
        for (i in 0 until n) organismSize[organismOf[i]]++
        // МАССА организма, а не число клеток: запас среды заряжается от скорости
        // ЦЕНТРА МАСС, а она есть сумма m*v делённая на сумму m. См. applyNormalDrag.
        for (i in 0 until n) {
            if (restInvMass[i] <= 0.0) continue
            organismMass[organismOf[i]] += 1.0 / restInvMass[i]
        }
        if (!rebuilding && !quiet) println("[RealBodyDemo] organisms = $comp (own flow reservoir each)")
    }

    /**
     * РАЗДЕЛИЛ ЛИ РАЗРЫВ ХОТЬ ОДИН КУСОК: встречный обход от концов каждого порванного
     * ребра. Обходы растут по одной клетке по очереди и останавливаются, как только
     * встретились, — цена выходит по МЕНЬШЕЙ из сторон, а при обычном разрыве внутри
     * ткани они встречаются через два-три шага.
     */
    private fun splits(edges: IntArray, count: Int): Boolean {
        val vs = baked.vertStart; val vo = baked.vertOther; val ve = baked.vertEdge
        val dead = baked.edgeDead
        if (orgSeen.size != n) { orgSeen = IntArray(n); orgFrontA = IntArray(n); orgFrontB = IntArray(n) }
        val seen = orgSeen
        for (e in 0 until count) {
            val u = baked.edgeU(edges[e]); val v = baked.edgeV(edges[e])
            orgStamp += 2
            val markA = orgStamp; val markB = orgStamp + 1
            seen[u] = markA; seen[v] = markB
            var ah = 0; var at = 0; var bh = 0; var bt = 0
            orgFrontA[at++] = u; orgFrontB[bt++] = v
            var met = false
            while (!met && (ah < at || bh < bt)) {
                if (ah >= at || bh >= bt) break      // одна сторона исчерпана — это распад
                var x = orgFrontA[ah++]
                for (k in vs[x] until vs[x + 1]) {
                    if (dead[ve[k]]) continue
                    val w = vo[k]
                    if (seen[w] == markB) { met = true; break }
                    if (seen[w] == markA) continue
                    seen[w] = markA; orgFrontA[at++] = w
                }
                if (met) break
                x = orgFrontB[bh++]
                for (k in vs[x] until vs[x + 1]) {
                    if (dead[ve[k]]) continue
                    val w = vo[k]
                    if (seen[w] == markA) { met = true; break }
                    if (seen[w] == markB) continue
                    seen[w] = markB; orgFrontB[bt++] = w
                }
            }
            if (!met) return true
        }
        return false
    }

    private var orgQueue = IntArray(0)
    private var orgSeen = IntArray(0)
    private var orgFrontA = IntArray(0)
    private var orgFrontB = IntArray(0)
    private var orgStamp = 0

    private fun buildContacts() {
        if (!::radius.isInitialized) radius = DoubleArray(n) { body.radius[it].toDouble() }
        if (!::isFree.isInitialized) isFree = BooleanArray(n)
        isFree.fill(true)
        for (k in 0 until lnkCount) { isFree[lnkA[k]] = false; isFree[lnkB[k]] = false }
        // Ёмкость по целому телу, длина — в conCount: после разрыва списки сжимаются на месте.
        val cap = conA.size
        if (!::conMaxLen.isInitialized || conMaxLen.size != cap) {
            conMaxLen = DoubleArray(cap); linkTorn = BooleanArray(cap); conDead = BooleanArray(cap)
            conBoundary = BooleanArray(cap); conTendon = BooleanArray(cap)
        } else {
            linkTorn.fill(false); conDead.fill(false)
        }
        // Рабочая связь каждого ребра нужна отрисовке, чтобы покрасить ТРЕУГОЛЬНИК по его
        // рёбрам. Раньше это была HashMap пар на пять тысяч записей, заново на каждой пересборке.
        // Связи на контуре (свой порог разрыва, см. MEMBRANE_TEAR_STRAIN) — рёбра не больше чем
        // с одним живым треугольником. Всё это заполняется ОДНИМ проходом по связям.
        if (conOfEdge.size != baked.edgeCount) { conOfEdge = IntArray(baked.edgeCount); conOfEdge.fill(-1) }
        val use = baked.triUse
        for (c in 0 until conCount) {
            conMaxLen[c] = LINK_MAX_STRETCH * conRest[c]
            val e = conEdge[c]
            conOfEdge[e] = c
            conBoundary[c] = use[e] <= 1
            // СУХОЖИЛИЕ: связь мышцы с костью. Мышца тянет, кость не поддаётся, и всю
            // деформацию берёт на себя эта связь. См. TENDON_TEAR_FACTOR.
            val a = conA[c]; val b = conB[c]
            conTendon[c] = (muscleOf[a] >= 0) != (muscleOf[b] >= 0)
        }
        if (everLinked == null) everLinked = BoundaryContacts.linkedPairs(conA, conB, conCount)
        // Кандидаты касания в позе покоя считаются по ЦЕЛОМУ телу и от разрывов не зависят:
        // радиус контакта клетки не бывает больше половины её самой длинной связи с запасом шва.
        if (restPairs == null) restPairs = BoundaryContacts.bakeRestPairs(
            n,
            BoundaryContacts.maxContactRadius(n, body.linkA, body.linkB, body.linkCount,
                radius, CONTACT_SCALE, body.x, body.y),
            body.x, body.y, everLinked!!)
        val ct = contacts
        if (ct == null) {
            contacts = BoundaryContacts.build(
                n, conA, conB, conCount, boundA, boundB, boundCount, radius,
                CONTACT_SCALE, CCD_CORE, CONTACT_RESTITUTION, CONTACT_FRICTION,
                body.x, body.y,
                body.meanLinkLength.toDouble(), CONTACT_MAX_STEP, isFree, everLinked,
                cellDead, restPairs,
            )
        } else {
            // Объект переиспользуется: заводить его заново на каждой пересборке стоило
            // дороже всего остального разрыва вместе взятого. См. reconfigure.
            ct.reconfigure(conA, conB, conCount, boundA, boundB, boundCount,
                body.x, body.y, isFree, cellDead, restPairs, everLinked)
        }
        contacts!!.also {
            it.killOnDeep = killOnDeep && KILL_ON_DEEP_OVERLAP
            it.killDepth = KILL_DEPTH
            if (internalMom?.n != n) internalMom = InternalMomentum(n)
            if (contactPressure.size != n) contactPressure = DoubleArray(n)
            it.pressure = contactPressure
            if (crushedCell.size != n) crushedCell = BooleanArray(n)
        }
        if (!rebuilding && !quiet) println("[RealBodyDemo] contact particles = ${boundCount} boundary edges, " +
            "contact radius from boundary edges, seal margin")
    }

    private fun buildMasses() {
        restInvMass = DoubleArray(n)
        var meanArea = 0.0
        for (i in 0 until n) {
            val r = body.radius[i].toDouble()
            meanArea += r * r
        }
        meanArea /= n
        for (i in 0 until n) {
            val r = body.radius[i].toDouble()
            val m = if (meanArea > 0.0) (r * r) / meanArea else 1.0
            restInvMass[i] = if (m > 1e-12) 1.0 / m else 1.0
        }
    }

    /**
     * УГОЛ ЛОСКУТА: единственное, что мешает тонкому отростку сложиться сам на себя.
     *
     * ЗАЧЕМ ОТДЕЛЬНАЯ СТАДИЯ, А НЕ ИЗГИБ. Изгиб по умолчанию выключен (bendLevel = 0
     * даёт податливость -1, и solveBend выходит на первой строке), да и строится он
     * только для клеток ровно с двумя граничными рёбрами, то есть развилку контура
     * пропускает. А связь ЛОСКУТА не входит ни в один треугольник, поэтому её угол не
     * держит и площадь. В итоге не держит вообще ничто.
     *
     * ЧТО ЭТО ЛОМАЛО. Замер на оторвавшемся куске: клетки #939 и #940, у каждой по
     * одной связи, обе в одну и ту же клетку #566, треугольников на этих связях ноль.
     * Лоскуты свободно сложились друг на друга и сошлись на 0.014 средней связи, то
     * есть перекрылись на 99% контактного диаметра. Дальше контакт упирался в свой
     * предохранительный потолок, расталкивал их каждый подшаг на 4 клетки за тик,
     * связи тянули обратно на 7.7, и кусок дребезжал вечно, а среда превращала эту
     * пилу в тягу. Это же и есть «маятник, который от касания резко отскакивает»:
     * делить контактную поправку такой клетке не с кем.
     *
     * ОГРАНИЧЕНИЕ ОДНОСТОРОННЕЕ. Оно мешает лоскутам СХОДИТЬСЯ ближе, чем в позе
     * покоя, и не мешает им расходиться. Поэтому тело не становится жёстче нигде:
     * там, где ткань цела, лоскутов нет вовсе, а где есть — они просто не могут
     * сложиться в точку.
     *
     * Пар тут единицы: нужны ДВЕ связи одной клетки, и обе без треугольника.
     */

    /** Идёт пересборка после разрыва: печатать нельзя, она бывает десятки раз за тик. */
    private var rebuilding = false

    private fun buildFlaps() {
        val use = baked.triUse
        val bare = HashMap<Int, MutableList<Int>>()
        for (c in 0 until conCount) {
            val i = conA[c]; val j = conB[c]
            if (use[conEdge[c]] > 0) continue
            bare.getOrPut(i) { ArrayList() }.add(j)
            bare.getOrPut(j) { ArrayList() }.add(i)
        }
        val a = ArrayList<Int>(); val b = ArrayList<Int>(); val r = ArrayList<Double>()
        for ((_, list) in bare) {
            if (list.size < 2) continue
            for (p in list.indices) for (q in p + 1 until list.size) {
                val i = list[p]; val j = list[q]
                if (i == j) continue
                val dx = (body.x[i] - body.x[j]).toDouble()
                val dy = (body.y[i] - body.y[j]).toDouble()
                a.add(i); b.add(j); r.add(sqrt(dx * dx + dy * dy))
            }
        }
        flapCount = a.size
        flapA = a.toIntArray(); flapB = b.toIntArray(); flapRest = r.toDoubleArray()
        if (!rebuilding && !quiet) println("[RealBodyDemo] flap angles = $flapCount")
    }

    private var flapCount = 0
    private var flapA = IntArray(0)
    private var flapB = IntArray(0)
    private var flapRest = DoubleArray(0)

    /** Односторонняя: только не даёт сойтись ближе позы покоя. */
    private fun solveFlaps(h: Double) {
        if (flapCount == 0) return
        val alpha = FLAP_COMPLIANCE / (h * h)
        for (c in 0 until flapCount) {
            val i = flapA[c]; val j = flapB[c]
            val wi = invMass[i]; val wj = invMass[j]
            val w = wi + wj
            if (w == 0.0) continue
            var dx = px[i] - px[j]
            var dy = py[i] - py[j]
            val len = sqrt(dx * dx + dy * dy)
            val rest = flapRest[c]
            if (len >= rest || len < 1e-12) continue
            dx /= len; dy /= len
            val dL = -(len - rest) / (w + alpha)
            px[i] += dx * dL * wi; py[i] += dy * dL * wi
            px[j] -= dx * dL * wj; py[j] -= dy * dL * wj
        }
    }

    private fun buildBend() {
        if (bendNb0.size != n) { bendNb0 = IntArray(n); bendNb1 = IntArray(n); bendDeg = IntArray(n) }
        val nb0 = bendNb0; val nb1 = bendNb1; val deg = bendDeg
        java.util.Arrays.fill(nb0, -1); java.util.Arrays.fill(nb1, -1); java.util.Arrays.fill(deg, 0)
        for (e in 0 until boundCount) {
            val i = boundA[e]; val j = boundB[e]
            if (deg[i] == 0) nb0[i] = j else if (deg[i] == 1) nb1[i] = j
            deg[i]++
            if (deg[j] == 0) nb0[j] = i else if (deg[j] == 1) nb1[j] = i
            deg[j]++
        }
        if (!::bendA.isInitialized || bendA.size < n) {
            bendA = IntArray(n); bendB = IntArray(n); bendRest = DoubleArray(n)
        }
        var m = 0
        for (v in 0 until n) {
            if (deg[v] != 2) continue
            val i = nb0[v]; val j = nb1[v]
            if (i < 0 || j < 0 || i == j) continue
            val dx = (body.x[i] - body.x[j]).toDouble()
            val dy = (body.y[i] - body.y[j]).toDouble()
            bendA[m] = i; bendB[m] = j; bendRest[m] = sqrt(dx * dx + dy * dy); m++
        }
        bendCount = m
        if (!rebuilding && !quiet) println("[RealBodyDemo] bend pairs = $bendCount on $boundCount boundary edges")
    }

    private var bendNb0 = IntArray(0)
    private var bendNb1 = IntArray(0)
    private var bendDeg = IntArray(0)

    /**
     * Поза покоя костей: смещения от центроида кластера, один раз и навсегда.
     *
     * Центроид считается в double НАМЕРЕННО: это подготовка, а не горячий путь, и
     * именно здесь дешевле всего убить сокращение разрядов. В движке это делает
     * запекатель BakedLayout, в рантайме double не появляется.
     *
     * Сумма смещений досаживается в ноль итерацией: после вычитания среднего во float
     * сумма остаётся порядка 1e-6, второй проход убирает и её. Без этого проекция кости
     * каждый подшаг сдвигала бы кость на этот остаток — а это и был дрейф.
     */
    private fun buildBoneRestPose() {
        boneRestQx = Array(rigidBones.size) { DoubleArray(rigidBones[it].size) }
        boneRestQy = Array(rigidBones.size) { DoubleArray(rigidBones[it].size) }
        var maxSize = 1
        rigidBones.forEachIndexed { b, ids ->
            if (ids.size > maxSize) maxSize = ids.size
            val qx = boneRestQx[b]; val qy = boneRestQy[b]
            var cx = 0.0; var cy = 0.0
            for (i in ids) { cx += body.x[i]; cy += body.y[i] }
            cx /= ids.size; cy /= ids.size
            for (k in ids.indices) {
                qx[k] = body.x[ids[k]] - cx
                qy[k] = body.y[ids[k]] - cy
            }
            for (pass in 0 until 3) {
                var sx = 0.0; var sy = 0.0
                for (k in ids.indices) { sx += qx[k]; sy += qy[k] }
                if (sx == 0.0 && sy == 0.0) break
                val dx = sx / ids.size; val dy = sy / ids.size
                for (k in ids.indices) { qx[k] -= dx; qy[k] -= dy }
            }
        }
        boneDx = DoubleArray(maxSize)
        boneDy = DoubleArray(maxSize)
    }

    /**
     * Граница тела — рёбра, входящие ровно в ОДИН треугольник.
     *
     * Внутреннее ребро делят два треугольника, граничное — только один. Это работает на
     * любой топологии, включая рваные края и отростки, и не требует ни обхода контура,
     * ни знания порядка вершин.
     *
     * Считается по ВСЕМ треугольникам, а не по списку связей решателя: внутрикостных
     * связей мы не создаём, но поверхность кости средой омывается точно так же.
     */
    private fun buildBoundary() {
        val use = baked.triUse
        // Обход идёт по ВСЕМ связям, а не по ключам карты треугольников. Связь в тонком
        // отростке (шириной в одну клетку) не входит НИ В ОДИН треугольник, в карту не
        // попадает вовсе — и, считая только по карте, я терял такие рёбра целиком.
        // А это как раз хвост и плавники, то есть основная гребущая поверхность.
        if (!::boundA.isInitialized || boundA.size < lnkCount) {
            boundA = IntArray(lnkCount); boundB = IntArray(lnkCount)
        }
        var m = 0
        for (k in 0 until lnkCount) {
            if (use[lnkEdge[k]] > 1) continue
            boundA[m] = lnkA[k]; boundB[m] = lnkB[k]; m++
        }
        boundCount = m
        if (!rebuilding && !quiet) println("[RealBodyDemo] boundary edges = $boundCount")
    }

    private fun reset() {
        // Ткань могла порваться — топология возвращается к целой вместе с позами.
        restoreTopology()
        for (i in 0 until n) {
            px[i] = body.x[i].toDouble(); py[i] = body.y[i].toDouble()
            vx[i] = 0.0; vy[i] = 0.0
            invMass[i] = restInvMass[i]; matchWeight[i] = 1.0
        }
        trapTicks.fill(0); foldTicks.fill(0)
        flowVX.fill(0.0); flowVY.fill(0.0)
        muscleActivation.fill(0.0)
        muscleTarget.fill(0.0)
        gaitFrame = 0
        hoveredMuscle = -1
        hoverId = -1
        dragId = -1
        // Зум под число копий: две рядом в исходный кадр не влезают. Без окна камеры
        // нет вовсе — сброс зовёт и воспроизведение журнала.
        if (::camera.isInitialized) {
            camera.zoom = ORGANISMS.toFloat()
            camera.position.set(viewCenterX(), 0.85f, 0f)
            camera.update()
        }
        invertedPeak = 0
        boneCapHits = 0
        linkCapHits = 0
        if (::linkTorn.isInitialized) linkTorn.fill(false)
        speedCapHits = 0
        simTime = 0.0
        accumulator = 0.0
        stepsAvg = 1f
        startCx = comX()
        startCy = comY()
        applyLabDamage()
    }

    /**
     * РАЗРУШЕНИЕ ДЛЯ СТЕНДА: убить долю связей случайно, но ТЕМ ЖЕ ПУТЁМ, что в игре.
     *
     * Зачем не проще. Сначала я убивал связи прямо в файле тела, и это оказалось
     * неверно по существу: движок тогда считает, что такие пары НИКОГДА не были
     * связаны. А исключение из контактов даётся ровно таким парам — перекрытым в позе
     * покоя и никогда не связанным, — иначе соседи на 0.6 связи при контактном
     * диаметре 1.0 были бы в вечном контакте и тело распирало бы само себя. В итоге
     * ни одна пара по краям дыр не сталкивалась вовсе, что сразу и было замечено
     * глазами.
     *
     * Здесь связи умирают ПОСЛЕ загрузки целого тела и после того, как список
     * «когда-либо связанных» уже снят с целого графа. Тогда такие пары от исключения
     * защищены и сталкиваются, ровно как после настоящего разрыва.
     *
     * Зовётся из reset, поэтому клавиша сброса не возвращает целую решётку молча.
     */
    private fun applyLabDamage() {
        if (labKillFraction <= 0.0 || conCount == 0) return
        val rnd = java.util.Random(labKillSeed)
        val before = conCount
        val target = (conCount * labKillFraction).toInt()
        var killed = 0
        var guard = 0
        while (killed < target && guard < conCount * 64) {
            guard++
            val c = rnd.nextInt(conCount)
            if (conDead[c]) continue
            conDead[c] = true; killed++
        }
        tearsPending = true
        rebuildAfterTear()
        if (!quiet) println("[SoftGridLab] убито связей $killed из $before, осталось $conCount, тел $organismCount, сид $labKillSeed")
    }

    /**
     * Применить заявки на смерть, накопленные контактом за проход.
     *
     * Смерть клетки это смерть всех её связей: тогда её треугольники распадаются сами,
     * компоненты пересобираются, и кусок вокруг дыры живёт дальше по обычным правилам
     * разрушения. Отдельного механизма для этого не нужно вовсе.
     *
     * Заявки применяются ПОСЛЕ прохода, а не внутри: список контактов и смежность
     * собраны на текущую топологию, и менять её посреди обхода нельзя.
     */
    private fun applyKills(ct: BoundaryContacts) {
        var any = false
        for (k in 0 until ct.killN) {
            val v = ct.killList[k]
            if (cellDead[v]) continue
            cellDead[v] = true
            deadCount++
            any = true
            for (c in 0 until conCount) {
                if (conA[c] == v || conB[c] == v) conDead[c] = true
            }
            vx[v] = 0.0; vy[v] = 0.0
        }
        if (any) { tearsPending = true; rebuildTimed() }
    }

    private fun comX(): Double { var s = 0.0; for (i in 0 until n) s += px[i]; return s / n }
    private fun comY(): Double { var s = 0.0; for (i in 0 until n) s += py[i]; return s / n }

    // =================================================================
    //  РЕШАТЕЛЬ  (тот же, что в SoftBodyWithBoneDemo)
    // =================================================================

    /**
     * Во сколько раз сжат кластер мышцы: 1 в покое, MUSCLE_CONTRACTION при полном
     * сокращении. -1 (не мышца, шов между кластерами) — всегда 1.
     *
     * Именно ЭТО и есть вся модель мышцы: меняется длина покоя ограничения, а не сила.
     * Жёсткость остаётся прежней, поэтому мышца тянет ровно с той силой, которая нужна,
     * чтобы дотащить ткань до новой длины, и упирается, если ей мешают. Прямой аналог
     * degreeOfShortening в движке.
     */
    /**
     * МЫШЕЧНЫЕ ПАРАМЕТРЫ ЖИВУТ ПЕРЕМЕННЫМИ, а не только константами.
     *
     * Подбор идёт на зеркале (`swimTune`), а зеркало рвать не умеет, поэтому найденное
     * обязательно проверяется на настоящем теле с разрывом — стенд `PERF_GAIT`. Чтобы
     * прогнать кандидата, не пересобирая проект, значения берутся из окружения:
     * RB_CONTRACTION, RB_RATE_CONTRACT, RB_RATE_RELAX, RB_PERIOD, RB_DUTY.
     * Без переменных это ровно константы выше.
     */
    internal var muscleContraction = System.getenv("RB_CONTRACTION")?.toDoubleOrNull() ?: MUSCLE_CONTRACTION
    internal var muscleRateContract = System.getenv("RB_RATE_CONTRACT")?.toDoubleOrNull() ?: MUSCLE_RATE_CONTRACT
    internal var muscleRateRelax = System.getenv("RB_RATE_RELAX")?.toDoubleOrNull() ?: MUSCLE_RATE_RELAX
    internal var gaitPeriod = System.getenv("RB_PERIOD")?.toIntOrNull() ?: GAIT_PERIOD
    internal var gaitDuty = System.getenv("RB_DUTY")?.toDoubleOrNull() ?: GAIT_DUTY

    /** Захватывает ли мышца край: 0/1/2. См. MUSCLE_TOUCH. Окружение RB_TOUCH. */
    internal var muscleTouch = System.getenv("RB_TOUCH")?.toIntOrNull() ?: MUSCLE_TOUCH

    /**
     * Кластер мышцы у связи и у треугольника. См. MUSCLE_TOUCH.
     *
     * Строгое правило: оба конца связи и все три вершины треугольника в ОДНОМ кластере.
     * Кольцо вокруг мышцы попадает внутрь не здесь, а раньше — расширением самого списка
     * клеток, см. growMuscles(). Бахрома (режим 2) считается прямо тут.
     *
     * Когда клетки в РАЗНЫХ кластерах, побеждает большинство вершин, а при равенстве —
     * меньший номер. Правило не зависит от того, в каком порядке записаны концы связи и
     * вершины треугольника: иначе физика зависела бы от порядка строк в выгрузке.
     */
    private fun muscleOfPair(i: Int, j: Int): Int {
        val a = muscleOf[i]; val b = muscleOf[j]
        if (a == b) return a
        if (muscleTouch == 0) return -1
        // ШОВ МЕЖДУ СОСЕДНИМИ МЫШЦАМИ ТОЖЕ СОКРАЩАЕТСЯ. Пока между кластерами лежала
        // обычная ткань, шва не было; после роста они сходятся вплотную, и связь на стыке
        // осталась бы единственной, кто держит длину, пока обе стороны от неё уходят. На
        // body-export таких связей 92, и все они рвались растяжением на нулевом же тике.
        if (a >= 0 && b >= 0) return if (a < b) a else b
        if (muscleTouch != 2) return -1
        return if (a < 0) b else a
    }

    private fun muscleOfTri(i0: Int, i1: Int, i2: Int): Int {
        // ПЛОЩАДЬ У КОСТИ НЕ СОКРАЩАЕТСЯ. Кость жёсткая, её сторона треугольника длину не
        // меняет, а площадь просят уменьшить в s^2 раз — выполнить это можно только
        // уронив вершину на кость. Связи при этом тянут её же на s, и стадии дерутся:
        // на body-export это рвало 52 связи на нулевом тике, худшая связь сжималась до
        // 0.111 длины покоя. Тянет кость СВЯЗЬ, ей для этого площадь не нужна.
        if (boneOf[i0] >= 0 || boneOf[i1] >= 0 || boneOf[i2] >= 0) return -1
        val a = muscleOf[i0]; val b = muscleOf[i1]; val c = muscleOf[i2]
        if (a >= 0 && a == b && a == c) return a
        if (muscleTouch == 0) return -1
        // Все три вершины мышечные, но кластеры разные — см. шов у muscleOfPair.
        if (muscleTouch != 2 && (a < 0 || b < 0 || c < 0)) return -1
        var best = -1
        var votes = 0
        if (a >= 0) { val v = 1 + (if (b == a) 1 else 0) + (if (c == a) 1 else 0)
            if (v > votes || (v == votes && a < best)) { best = a; votes = v } }
        if (b >= 0) { val v = 1 + (if (a == b) 1 else 0) + (if (c == b) 1 else 0)
            if (v > votes || (v == votes && b < best)) { best = b; votes = v } }
        if (c >= 0) { val v = 1 + (if (a == c) 1 else 0) + (if (b == c) 1 else 0)
            if (v > votes || (v == votes && c < best)) { best = c; votes = v } }
        return best
    }

    /**
     * КОЛЬЦО ВОКРУГ МЫШЦЫ УХОДИТ В МЫШЦУ. Режим 1, см. MUSCLE_TOUCH.
     *
     * Треугольник с хотя бы одной мышечной вершиной отдаёт кластеру все три свои клетки.
     * Спорную клетку — ту, что граничит сразу с двумя мышцами, — забирает кластер с
     * меньшим номером: правило должно быть одинаковым при любом порядке треугольников.
     * Смотрим на ИСХОДНЫЙ список клеток, а не на растущий, иначе мышца расползлась бы по
     * телу на столько колец, сколько треугольников попадётся по дороге.
     */
    private fun growMuscles() {
        if (muscleTouch != 1) return
        val core = muscleOf
        val grown = core.copyOf()
        for (t in 0 until body.triCount) {
            val i0 = body.triA[t]; val i1 = body.triB[t]; val i2 = body.triC[t]
            val a = core[i0]; val b = core[i1]; val c = core[i2]
            var m = -1
            if (a >= 0) m = a
            if (b >= 0 && (m < 0 || b < m)) m = b
            if (c >= 0 && (m < 0 || c < m)) m = c
            if (m < 0) continue
            if (a < 0 && (grown[i0] < 0 || m < grown[i0])) grown[i0] = m
            if (b < 0 && (grown[i1] < 0 || m < grown[i1])) grown[i1] = m
            if (c < 0 && (grown[i2] < 0 || m < grown[i2])) grown[i2] = m
        }
        muscleOf = grown
    }

    private fun muscleScale(m: Int) = if (m < 0) 1.0 else muscleScaleOf[m]

    /**
     * Во сколько раз сжат каждый кластер мышцы — считается РАЗ В ПОДШАГ.
     *
     * Связей и треугольников с мышцей тысячи, и каждая спрашивала это на каждой из 64
     * итераций решателя, поэтому значение считается заранее. Кластеров при этом единицы,
     * так что подшаг вместо тика ничего не стоит.
     *
     * ПОЧЕМУ ПОДШАГ, А НЕ ТИК. updateMuscles двигает активацию раз в тик, и длина покоя
     * прыгала ступенькой: весь шаг мышцы решатель отрабатывал в ПЕРВОМ же подшаге, а
     * updateVelocities делит смещение на h = DT/16. Скорость выходила вшестнадцатеро
     * больше настоящей, и эта вспышка успевала уйти в среду настоящим импульсом —
     * рывок при отпускании мышцы как раз оттуда. Теперь активация проходит свой шаг
     * РОВНО за тик, но по подшагам: доля f = (step + 1) / SUBSTEPS. За тик изменение то
     * же самое, только размазано, как оно и происходит на самом деле.
     */
    private var muscleScaleOf = DoubleArray(0)

    /** Активация на НАЧАЛО тика — между ней и текущей идёт разгон по подшагам. */
    private var muscleActivationPrev = DoubleArray(0)

    private fun updateMuscleScale(f: Double) {
        if (muscleScaleOf.size != muscleActivation.size) muscleScaleOf = DoubleArray(muscleActivation.size)
        if (muscleActivationPrev.size != muscleActivation.size) muscleActivationPrev = DoubleArray(muscleActivation.size)
        for (m in muscleActivation.indices) {
            val a = muscleActivationPrev[m] + (muscleActivation[m] - muscleActivationPrev[m]) * f
            muscleScaleOf[m] = 1.0 - a * (1.0 - muscleContraction)
        }
    }

    private fun solveConstraints(h: Double) {
        val alpha = SOFT_COMPLIANCE / (h * h)
        // ВСЁ В ЛОКАЛЬНЫЕ. Стадия идёт 64 раза за тик по пяти тысячам связей, и на таком
        // числе проходов заметно даже обращение к полю: у lateinit оно с проверкой.
        val px = px; val py = py; val invMass = invMass
        val conA = conA; val conB = conB; val conRest = conRest; val conMuscle = conMuscle
        val conDead = conDead; val ms = muscleScaleOf
        // Направление обхода ЧЕРЕДУЕТСЯ. См. sweepBackwards. Индексом, а не диапазоном:
        // диапазон с переменным направлением — объект с итератором на каждый шаг.
        val step = if (sweepBackwards) -1 else 1
        var c = if (sweepBackwards) conCount - 1 else 0
        var left = conCount
        while (left > 0) {
            left--
            val cc = c
            c += step
            // Порванная связь не тянет ни мгновения — даже до пересборки топологии.
            if (conDead[cc]) continue
            val i = conA[cc]; val j = conB[cc]
            val wi = invMass[i]; val wj = invMass[j]
            val w = wi + wj
            if (w == 0.0) continue
            var dx = px[i] - px[j]
            var dy = py[i] - py[j]
            val len = sqrt(dx * dx + dy * dy)
            if (len < 1e-12) continue
            dx /= len; dy /= len
            val m = conMuscle[cc]
            val rest = conRest[cc] * (if (m < 0) 1.0 else ms[m])
            val dL = -(len - rest) / (w + alpha)
            px[i] += dx * dL * wi; py[i] += dy * dL * wi
            px[j] -= dx * dL * wj; py[j] -= dy * dL * wj
        }
    }

    /**
     * Изгиб границы: обычное ограничение расстояния между соседями через одну.
     * Стоит ПОСЛЕ площадей и перед проекцией кости, вместе с остальными позиционными.
     * См. BEND_LEVELS — по умолчанию стадия выключена и выходит на первой же строке.
     */
    /**
     * ПРЕДЕЛ ДЛИНЫ СВЯЗИ. Жёстко, без податливости — см. LINK_MAX_LENGTH.
     *
     * Односторонний: сжатию не мешает вовсе, срабатывает только на растяжении сверх
     * суммы радиусов. Стоит СРАЗУ ПОСЛЕ solveConstraints, чтобы мягкая пружина не могла
     * оставить связь растянутой до конца подшага.
     *
     * В движке ровно это условие — сигнал к разрыву связи. Здесь рвать нечем, поэтому
     * связь просто бесконечно крепкая.
     */
    /**
     * ПЛАСТИЧЕСКОЕ ТЕЧЕНИЕ ТКАНИ. Зовётся РАЗ В ТИК, см. PLASTIC_RATE.
     *
     * Деформация сверх предела текучести медленно переезжает в длину покоя, то есть
     * перестаёт быть деформацией. Ниже предела не делается ничего — ткань упругая.
     *
     * ДЕФОРМАЦИЯ СЧИТАЕТСЯ ОТ ТЕКУЩЕЙ ЦЕЛИ, а не от conRest: у мышцы цель короче на
     * muscleScale, и мерить от conRest значило бы считать сокращение мышцы пластикой.
     * Тогда сокращённая мышца за несколько секунд «забывала» бы свою длину покоя и
     * переставала тянуть вовсе.
     *
     * Площади текут ВМЕСТЕ с длинами и отдельно от них. Отпустить только длины нельзя:
     * несжимаемая площадь удержит смятый треугольник в прежнем виде, и несовместимость
     * останется — просто переедет со связей на площади.
     */
    private var conHold = ByteArray(0)
    private var triHold = ByteArray(0)

    private fun applyPlasticity(dt: Double) {
        if (PLASTIC_RATE <= 0.0) return
        var k = PLASTIC_RATE * dt
        if (k > 1.0) k = 1.0
        // Счётчики выдержки живут ровно столько же, сколько топология: после разрыва
        // размеры меняются, и старые значения относились бы к другим связям.
        if (conHold.size != conCount) conHold = ByteArray(conCount)
        if (triHold.size != triCount) triHold = ByteArray(triCount)

        for (c in 0 until conCount) {
            // МЫШЦЫ НЕ ТЕКУТ, и это не осторожность, а необходимость.
            //
            // У сокращённой мышцы цель заметно короче (MUSCLE_CONTRACTION = 0.50), а
            // окружающая ткань дотянуться не даёт. Деформация относительно цели выходит
            // в сотни процентов — не потому что ткань смялась, а потому что мышца
            // работает. Пластика на этом разносит длину покоя, мышца «забывает» свою
            // длину и тянуть перестаёт. Проверка ловила это сразу: тело переставало
            // останавливаться вовсе (замедление 1.0x вместо 20x за минуту), потому что
            // ползущая длина покоя вечно шевелила границу, а среда это выпрямляла в тягу.
            if (conMuscle[c] >= 0) continue
            val target = conRest[c]
            if (target < 1e-12) continue
            val dx = px[conA[c]] - px[conB[c]]
            val dy = py[conA[c]] - py[conB[c]]
            val len = sqrt(dx * dx + dy * dy)
            val strain = len / target - 1.0
            val over = when {
                strain > PLASTIC_YIELD -> strain - PLASTIC_YIELD
                strain < -PLASTIC_YIELD -> strain + PLASTIC_YIELD
                else -> 0.0
            }
            if (over == 0.0) { conHold[c] = 0; continue }
            if (conHold[c] < PLASTIC_HOLD) { conHold[c]++; continue }
            conRest[c] *= 1.0 + over * k
            // Предел длины идёт ЗА длиной покоя: иначе потёкшая связь окажется
            // растянутой по старой мерке и стадия предела начнёт с ней воевать.
            conMaxLen[c] = LINK_MAX_STRETCH * conRest[c]
        }

        for (t in 0 until triCount) {
            if (triMuscle[t] >= 0) continue          // мышечные — по той же причине
            val rest2 = triRestArea2[t].toDouble()
            if (abs(rest2) < 1e-18) continue
            val i0 = triA[t]; val i1 = triB[t]; val i2 = triC[t]
            val area2 = (px[i1] - px[i0]) * (py[i2] - py[i0]) -
                (py[i1] - py[i0]) * (px[i2] - px[i0])
            // ВЫВЕРНУТЫМ ТЕЧЬ НЕЛЬЗЯ: подогнав площадь покоя под сложенное состояние,
            // пластика УЗАКОНИТ складку, и та не разойдётся уже никогда. Проверка
            // ловила это прямо: складка 50% и 75% переставали расходиться за 8 секунд.
            if (area2 <= 0.0) continue
            val strain = area2 / rest2 - 1.0
            val over = when {
                strain > PLASTIC_YIELD -> strain - PLASTIC_YIELD
                strain < -PLASTIC_YIELD -> strain + PLASTIC_YIELD
                else -> 0.0
            }
            if (over == 0.0) { triHold[t] = 0; continue }
            if (triHold[t] < PLASTIC_HOLD) { triHold[t]++; continue }
            triRestArea2[t] = (triRestArea2[t] * (1.0 + over * k)).toFloat()
        }
    }

    private fun solveLinkMaxLength() {
        // Всё в локальные: стадия идёт 80 раз за тик по пяти тысячам связей.
        val px = px; val py = py; val invMass = invMass
        val conA = conA; val conB = conB; val conRest = conRest; val conMuscle = conMuscle
        val conDead = conDead; val conMaxLen = conMaxLen; val ms = muscleScaleOf
        val meanLink = body.meanLinkLength
        for (c in 0 until conCount) {
            if (conDead[c]) continue
            val i = conA[c]; val j = conB[c]
            val wi = invMass[i]; val wj = invMass[j]
            val w = wi + wj
            if (w == 0.0) continue
            var dx = px[i] - px[j]
            var dy = py[i] - py[j]
            val len = sqrt(dx * dx + dy * dy)
            // РАЗДАВЛЕННАЯ СВЯЗЬ РВЁТСЯ ТАК ЖЕ, КАК ПЕРЕРАСТЯНУТАЯ. См. LINK_CRUSH_RATIO.
            val mus = conMuscle[c]
            val scale = if (mus < 0) 1.0 else ms[mus]
            // Запас до разрыва за прогон: видно, насколько близко ткань подошла к порогам.
            val cr = len / (conRest[c] * scale)
            if (cr < dbgWorstCrush) dbgWorstCrush = cr
            val st = len / conRest[c]
            if (st > dbgWorstStretch) dbgWorstStretch = st
            if (tearingOn && len < LINK_CRUSH_RATIO * conRest[c] * scale) {
                linkTorn[c] = true; conDead[c] = true; tearsPending = true
                crushedCell[i] = true; crushedCell[j] = true
                dbgTornCrush++; if (mus >= 0) dbgTornCrushMuscle++
                dbgTear(c, i, j, "сжатие", len / (conRest[c] * scale))
                continue
            }
            val max = conMaxLen[c]
            if (len <= max || len < 1e-12) continue
            val overStrain = (len - max) / conRest[c]
            if (overStrain > dbgMaxOverStrain) dbgMaxOverStrain = overStrain
            // Пик недобора за всё время: сколько связь хотела сверх предела.
            val tear = if (conTendon[c]) LINK_TEAR_STRAIN * tendonTear else LINK_TEAR_STRAIN
            if (len - max > tear * conRest[c]) {
                linkTorn[c] = true
                if (tearingOn) { conDead[c] = true; tearsPending = true }
                dbgTornPull++; if (mus >= 0) dbgTornPullMuscle++
                dbgTear(c, i, j, "растяжение", len / conRest[c])
            }
            // МЕМБРАНА ХРУПЧЕ ТКАНИ. См. MEMBRANE_TEAR_STRAIN.
            if (tearingOn && membraneTearStrain >= 0.0 && conBoundary[c] && !conDead[c] &&
                len - max > membraneTearStrain * conRest[c]) {
                linkTorn[c] = true; conDead[c] = true; tearsPending = true
                membraneTearCount++
            }
            dx /= len; dy /= len
            // Тот же потолок поправки за подшаг, что и у контакта, и по той же
            // причине: стадия ЖЁСТКАЯ, перерастяжение она снимает целиком за один
            // подшаг, а updateVelocities делит поправку на крошечное h. При загибе
            // связи растягиваются сильно, и отсюда шёл остаток выброса скорости.
            // Делится по паре в тех же долях, поэтому импульс пары сохраняется.
            var dL = -(len - max) / w
            val capL = CONTACT_MAX_STEP * meanLink / w
            if (dL < -capL) dL = -capL
            px[i] += dx * dL * wi; py[i] += dy * dL * wi
            px[j] -= dx * dL * wj; py[j] -= dy * dL * wj
            linkCapHits++
        }
    }

    /** Сколько раз предел длины связи сработал с последнего сброса. Видно в HUD. */
    private var linkCapHits = 0

    /** Разбор: журнал разрывов — кто, когда и почему. Включает читатель, см. PR_TEARS. */
    internal var dbgTearLog: StringBuilder? = null

    private fun dbgTear(c: Int, i: Int, j: Int, why: String, ratio: Double) {
        val log = dbgTearLog ?: return
        if (log.length > 20000) return
        log.append("    тик %d: связь #%d-#%d %s %.3f, связь мышцы %d, клетки: мышцы %d/%d, кости %d/%d, сухожилие %s".format(
            playTick, i, j, why, ratio, conMuscle[c], muscleOf[i], muscleOf[j], boneOf[i], boneOf[j],
            if (conTendon[c]) "да" else "нет"))
        log.append(10.toChar())
    }

    /** Разбор: самая смятая и самая растянутая связь за прогон, в долях длины покоя. */
    internal var dbgWorstCrush = 1.0
    internal var dbgWorstStretch = 1.0

    /** Разбор: чем порвано — сжатием или растяжением, и сколько из этого мышечные связи. */
    internal var dbgTornCrush = 0
    internal var dbgTornCrushMuscle = 0
    internal var dbgTornPull = 0
    internal var dbgTornPullMuscle = 0

    /** Разбор: наибольший недобор связи сверх предела, в долях покоя. Сбрасывает читатель. */
    internal var dbgMaxOverStrain = 0.0

    /** Контакты пересобраны посреди подшага — список пар надо строить заново. */
    private var contactsStale = false

    /** Цена пересборки после разрыва: суммарное время и число вызовов. */
    internal var dbgRebuildNs = 0L
    internal var dbgRebuildN = 0

    private fun rebuildTimed() {
        val t0 = System.nanoTime()
        rebuilding = true
        try { rebuildAfterTear() } finally { rebuilding = false }
        dbgRebuildNs += System.nanoTime() - t0
        dbgRebuildN++
    }

    /** Связь хоть раз требовала растяжения сверх порога разрыва. См. LINK_TEAR_STRAIN. */
    private lateinit var linkTorn: BooleanArray

    // ================================================================
    //  НАСТОЯЩИЙ РАЗРЫВ ТКАНИ [X]
    //
    //  До этого связь при перегрузке лишь КРАСИЛАСЬ синим, а держалась вечно. Из-за
    //  этого оставался открытым вопрос, который и заставил всё это сделать: может ли
    //  тело войти в мягкую ткань БЕЗ разрыва. С вечными связями ответ было не
    //  получить — ткань обязана была выдержать что угодно.
    //
    //  Порядок такой: перегруженная связь помечается мёртвой прямо в подшаге, но
    //  топология перестраивается ОДИН РАЗ в конце тика. Иначе пришлось бы
    //  пересобирать контур и контакты по шестнадцать раз за тик, а рвётся обычно
    //  сразу пучок связей за один удар.
    //
    //  ПРИ ПЕРЕНОСЕ: здесь пересборка ПОЛНАЯ, потому что разрывы редки, а код проще
    //  читать. В движке так нельзя — там нужна инкрементальная правка контура и
    //  смежности, иначе один разрыв будет стоить полного обхода тела.
    // ================================================================
    private var tearingOn = TEARING_DEFAULT
    private lateinit var conDead: BooleanArray
    private var tearsPending = false
    private var tornTotal = 0

    /**
     * Пересборка после разрывов. Зовётся из конца тика, только если что-то порвалось.
     *
     * Треугольник умирает вместе с ЛЮБЫМ своим ребром: без ребра он больше не
     * ограничивает площадь той ткани, которой уже нет. Контур после этого
     * перестраивается сам — ребро, потерявшее второй треугольник, становится
     * граничным, и на нём появляются новые точки контакта. Это и есть «назначение
     * новых частиц на границу»: отдельного списка нет, граница выводится из
     * топологии.
     */
    /**
     * Возврат топологии к целой. Обязателен при сбросе: без него порванное тело
     * оставалось бы порванным навсегда, и любой следующий замер шёл бы уже по
     * другому телу. В регрессионной проверке это било бы особенно тихо — тесты
     * идут подряд по одному экземпляру.
     */
    fun restoreTopology() {
        // Целое тело — это и живые клетки. Без этого лопнувшие при сбросе оставались
        // мёртвыми: не рисовались, не сталкивались, а первое же лопание снова рвало все
        // их восстановленные связи — в свежем теле появлялись дыры. Стенд столкновений
        // сбрасывается перед каждой вариацией, и мёртвые копились там от сцены к сцене.
        cellDead.fill(false)
        deadCount = 0
        crushedCell.fill(false)
        lnkCount = body.linkCount
        lnkA = body.linkA.copyOf(); lnkB = body.linkB.copyOf()
        triCount = body.triCount
        baked.restore()
        lnkEdge = baked.linkEdge.copyOf()
        triId = IntArray(triCount) { it }
        triA = body.triA.copyOf(); triB = body.triB.copyOf(); triC = body.triC.copyOf()
        triRestArea2 = body.triRestArea2.copyOf()
        triMuscle = IntArray(triCount) { t -> muscleOfTri(triA[t], triB[t], triC[t]) }
        triInverted = BooleanArray(triCount)

        val ed = ArrayList<Int>(lnkCount)
        val a = ArrayList<Int>(lnkCount); val b = ArrayList<Int>(lnkCount)
        val rest = ArrayList<Double>(lnkCount); val mus = ArrayList<Int>(lnkCount)
        for (k in 0 until lnkCount) {
            val i = lnkA[k]; val j = lnkB[k]
            if (boneOf[i] != -1 && boneOf[i] == boneOf[j]) continue
            val dx = body.x[i] - body.x[j]; val dy = body.y[i] - body.y[j]
            a.add(i); b.add(j); rest.add(sqrt((dx * dx + dy * dy).toDouble()))
            ed.add(lnkEdge[k])
            mus.add(muscleOfPair(i, j))
        }
        conCount = a.size
        conA = a.toIntArray(); conB = b.toIntArray()
        conRest = rest.toDoubleArray(); conMuscle = mus.toIntArray()
        conEdge = ed.toIntArray()

        tearsPending = false
        tornTotal = 0
        buildBoundary(); buildBend(); buildFlaps(); buildOrganisms(); buildContacts()
    }

    private fun rebuildAfterTear() {
        tearsPending = false
        var t = System.nanoTime()
        fun lap(k: Int) { val now = System.nanoTime(); dbgRebuildSec[k] += now - t; t = now }

        // Мёртвые рёбра гасятся в запечённой топологии: треугольники на них умирают сами,
        // счётчики треугольников у соседних рёбер уменьшаются. Раньше мёртвые пары
        // сортировались, и каждая связь и каждый треугольник искались среди них двоичным
        // поиском. Ребро — пара клеток, поэтому все связи одной пары умирают вместе, как и
        // тогда. Порядок живых списков прежний, результат побитово тот же — проверено
        // контрольными суммами по каждому тику шести журналов игрока.
        if (deadEdges.size < conA.size) deadEdges = IntArray(conA.size)
        var nd = 0
        for (c in 0 until conCount) {
            if (!conDead[c] || !baked.kill(conEdge[c])) continue
            conOfEdge[conEdge[c]] = -1
            deadEdges[nd++] = conEdge[c]
        }
        if (nd == 0) return
        tornTotal += nd
        val edgeDead = baked.edgeDead

        // 1. Полный список связей. Сжатие НА МЕСТЕ: пишущий индекс никогда не обгоняет
        //    читающий, а массивы остаются прежней ёмкости — длина живёт в счётчике.
        run {
            var m = 0
            for (k in 0 until lnkCount) {
                if (edgeDead[lnkEdge[k]]) continue
                lnkA[m] = lnkA[k]; lnkB[m] = lnkB[k]; lnkEdge[m] = lnkEdge[k]; m++
            }
            lnkCount = m
        }

        // 2. Треугольники: умерли вместе с любым своим ребром — см. BakedTopology.kill
        run {
            val alive = baked.triAlive
            var m = 0
            for (k in 0 until triCount) {
                if (!alive[triId[k]]) continue
                triA[m] = triA[k]; triB[m] = triB[k]; triC[m] = triC[k]
                triRestArea2[m] = triRestArea2[k]; triMuscle[m] = triMuscle[k]; triId[m] = triId[k]
                m++
            }
            triCount = m
            java.util.Arrays.fill(triInverted, false)
        }

        // 3. Рабочие связи решателя — тем же правилом, что при загрузке.
        //
        // ДЛИНА ПОКОЯ ПЕРЕЕЗЖАЕТ, А НЕ СЧИТАЕТСЯ ЗАНОВО. При пластичности она уже не
        // равна длине в позе покоя: ткань текла. Пересчёт из body.x стирал бы всё
        // накопленное течение на каждом разрыве, то есть ровно там, где оно и нужно.
        // Треугольникам это уже сделано выше — их площадь покоя переносится из старого
        // массива, а не берётся из файла.
        //
        // Рабочие связи — это полный список без внутрикостных, в том же порядке. Новый
        // полный список — старый без мёртвых, значит новые рабочие связи — ровно старые
        // рабочие без мёртвых, в том же порядке. Их и оставляем, вместе с длиной покоя.
        run {
            var m = 0
            for (c in 0 until conCount) {
                if (edgeDead[conEdge[c]]) continue
                conA[m] = conA[c]; conB[m] = conB[c]; conRest[m] = conRest[c]
                conMuscle[m] = conMuscle[c]; conEdge[m] = conEdge[c]; m++
            }
            conCount = m
        }

        // 4. Всё производное — теми же функциями, что и при загрузке. Контур,
        //    изгиб, организмы (тело могло распасться надвое) и контакты.
        lap(0)
        buildBoundary(); lap(1)
        buildBend(); buildFlaps(); lap(2)
        buildOrganisms(relabel = splits(deadEdges, nd)); lap(3)
        buildContacts(); lap(4)
    }

    /** Рёбра, порванные последней пересборкой. См. splits. */
    private var deadEdges = IntArray(0)

    /** Разбор цены пересборки по частям: списки, контур, изгиб+лоскуты, организмы, контакты. */
    internal val dbgRebuildSec = LongArray(5)

    /** Срабатывания потолка на момент захвата — строка DRAG показывает разницу. */
    private var dragCapBase = 0

    /** Какую свободную частицу заряжать следующей. См. fireBullet. */
    private var nextBullet = 0

    /**
     * Запустить свободную частицу справа налево на потолке скорости.
     *
     * Берутся по кругу уже существующие свободные частицы: заводить новые значило бы
     * менять n на ходу, а от n зависят все массивы решателя и разбиение на организмы.
     */
    /**
     * ТАРАН [O]: два самых крупных организма разгоняются НАВСТРЕЧУ друг другу.
     *
     * Пуля проверяет мембрану на одиночной лёгкой клетке, и этого мало: там масса
     * ничтожная, ткань даже не напрягается. Здесь на контур наваливается вся масса
     * второго тела, и это уже настоящее условие — самое тяжёлое столкновение,
     * какое в симуляции вообще возможно при действующем потолке скорости.
     *
     * Импульс задаётся КАЖДОЙ частице организма, а не одной: тело должно лететь
     * целиком, как брошенное, а не растягиваться за разогнанным краем.
     */
    // ================================================================
    //  СЦЕНЫ СТЕНДА ПРЯМО В ДЕМО: N выбрать, M запустить.
    //
    //  Зачем. Стенд считает числа без окна, но собирает топологию САМ: рассыпал тело,
    //  разложил клетки. В живой симуляции та же куча получается ИНАЧЕ — из разрушения,
    //  с пересборкой контура, смежности и списка исключений. Если стенд спокоен, а в
    //  демо та же сцена дребезжит, значит ломается не решатель контактов, а пересборка
    //  после разрушения. Ровно так уже находилась ошибка, из-за которой бывшие соседи
    //  переставали сталкиваться.
    //
    //  Расстановка берётся из BenchScenes, ОДНА на стенд и на демо: две копии молча
    //  разъехались бы, и картинка перестала бы отвечать за числа.
    // ================================================================
    private var sceneIndex = 0
    private val scenes = BenchScenes.all()

    private fun sceneCtx() = SceneCtx(
        n = n, px = px, py = py, prevX = prevX, prevY = prevY, vx = vx, vy = vy,
        organismOfCell = { i -> organismOf[i] },
        organismSizeOf = { o -> organismSize[o] },
        organismCount = { organismCount },
        isFreeOf = { i -> isFree[i] },
        invMass = invMass,
        contactRadiusOf = { i -> contacts?.contactRadiusOf(i) ?: (radius[i] * CONTACT_SCALE) },
        meanLink = body.meanLinkLength.toDouble(),
        dt = DT,
        vmax = MAX_SPEED_CELLS_PER_TICK,
        shatter = { o ->
            for (c in 0 until conCount) if (organismOf[conA[c]] == o) conDead[c] = true
            tearsPending = true
            simulate()
        },
        step = { stepOnce() },
        stepContract = { gait = true; stepOnce() },
        inBoneOf = { i -> boneOf[i] >= 0 },
        focus = { x, y ->
            if (::camera.isInitialized) { camera.position.set(x.toFloat(), y.toFloat(), 0f); camera.update() }
        },
    )

    /** Поставить выбранную сцену. Сброс обязателен: сцены стартуют от целых тел. */
    private fun runScene() {
        reset()
        tearingOn = true
        scenes[sceneIndex].setup(sceneCtx(), 0.0, 0.0)
        // Гребок гасится ПОСЛЕ расстановки. Сцена с оторванным куском включает его
        // сама на своё окно, и без этой строки он оставался бы включённым дальше —
        // тогда глазами видно одно, а стенд считает другое.
        gait = false; gaitFrame = 0
    }

    private fun slamOrganisms() {
        // ЗАХВАТ ОТПУСКАЕТСЯ. Держать клетку и одновременно бить тараном —
        // противоречивая пара действий: таран НАЗНАЧАЕТ скорость всем частицам, а
        // рука тут же начинает с ней бороться. Замер: пик 9.32 при потолке 8.0 и
        // 136 срабатываний clampSpeed, хотя сам таран на кирпиче проходит чисто.
        if (dragId >= 0) { matchWeight[dragId] = 1.0; dragId = -1 }
        // Два самых крупных организма — это тела; свободные частицы отсеиваются
        // сами, они размером в одну клетку.
        val order = (0 until organismCount).sortedByDescending { organismSize[it] }
        if (order.size < 2) return
        val a = order[0]; val b = order[1]
        if (organismSize[b] < 2) return

        var ax = 0.0; var ay = 0.0; var an = 0
        var bx = 0.0; var by = 0.0; var bn = 0
        for (i in 0 until n) {
            when (organismOf[i]) {
                a -> { ax += px[i]; ay += py[i]; an++ }
                b -> { bx += px[i]; by += py[i]; bn++ }
            }
        }
        if (an == 0 || bn == 0) return
        ax /= an; ay /= an; bx /= bn; by /= bn

        var dx = bx - ax; var dy = by - ay
        val d = sqrt(dx * dx + dy * dy)
        if (d < 1e-12) return
        dx /= d; dy /= d

        val speed = BULLET_SPEED_FRACTION * MAX_SPEED_CELLS_PER_TICK * body.meanLinkLength / DT
        for (i in 0 until n) {
            when (organismOf[i]) {
                a -> { vx[i] = dx * speed; vy[i] = dy * speed }
                b -> { vx[i] = -dx * speed; vy[i] = -dy * speed }
            }
        }
        if (!quiet) println("[RealBodyDemo] таран: организмы $a и $b, по " +
            "%.1f клеток/тик навстречу".format(speed * DT / body.meanLinkLength))
    }

    private fun fireBullet() {
        val ids = (0 until n).filter { isFree[it] }
        if (ids.isEmpty()) return
        val i = ids[nextBullet % ids.size]
        nextBullet++

        // Справа от всего, что есть на сцене, на высоте середины тел.
        var maxX = -Double.MAX_VALUE
        var sumY = 0.0; var cnt = 0
        for (k in 0 until n) {
            if (isFree[k]) continue
            if (px[k] > maxX) maxX = px[k]
            sumY += py[k]; cnt++
        }
        if (cnt == 0) return
        val speed = BULLET_SPEED_FRACTION * MAX_SPEED_CELLS_PER_TICK * body.meanLinkLength / DT
        px[i] = maxX + body.meanLinkLength * 8.0
        py[i] = sumY / cnt
        prevX[i] = px[i]; prevY[i] = py[i]
        vx[i] = -speed; vy[i] = 0.0
        println("[RealBodyDemo] пуля: клетка #$i, скорость " +
            "%.1f клеток/тик".format(speed * DT / body.meanLinkLength))
    }

    /** Порвалась ли хоть одна из трёх сторон треугольника. */
    private fun triTorn(t: Int): Boolean {
        val te = baked.triEdge; val o = 3 * triId[t]
        for (k in 0..2) {
            val e = te[o + k]
            if (e < 0) continue
            val c = conOfEdge[e]
            if (c >= 0 && linkTorn[c]) return true
        }
        return false
    }

    /** Рабочая связь пары клеток или -1. Разбору журнала. */
    internal fun conIndexOf(i: Int, j: Int): Int {
        val e = baked.edgeOf(i, j)
        return if (e < 0) -1 else conOfEdge[e]
    }

    /**
     * ПОТОЛОК СКОРОСТИ — см. MAX_SPEED_CELLS_PER_TICK.
     *
     * Не физика, а гарантия для коллизий: путь за подшаг обязан оставаться конечным,
     * иначе DDA упрётся в размер буфера, а оценка «широкую фазу можно строить раз в
     * тик» перестанет быть верхней границей.
     */
    /** Диагностика: выключить потолок скорости. Он правит частицы ПО ОДНОЙ. */
    var dbgNoClamp = false

    private fun clampSpeed() {
        if (dbgNoClamp) return
        val maxV = MAX_SPEED_CELLS_PER_TICK * body.meanLinkLength / DT
        val maxV2 = maxV * maxV
        for (i in 0 until n) {
            val v2 = vx[i] * vx[i] + vy[i] * vy[i]
            if (v2 > peakSpeed2) peakSpeed2 = v2
            if (v2 <= maxV2) continue
            val s = maxV / sqrt(v2)
            vx[i] *= s; vy[i] *= s
            speedCapHits++
        }
    }

    /** Сколько раз потолок скорости сработал. Видно в HUD. */
    private var speedCapHits = 0

    /** Наибольшая увиденная скорость в квадрате, ДО обрезки. Замер, а не гадание. */
    private var peakSpeed2 = 0.0

    private fun solveBend(h: Double) {
        val compliance = bendCompliance()
        if (compliance < 0.0) return
        val alpha = compliance / (h * h)
        for (c in 0 until bendCount) {
            val i = bendA[c]; val j = bendB[c]
            val wi = invMass[i]; val wj = invMass[j]
            val w = wi + wj
            if (w == 0.0) continue
            var dx = px[i] - px[j]
            var dy = py[i] - py[j]
            val len = sqrt(dx * dx + dy * dy)
            if (len < 1e-12) continue
            dx /= len; dy /= len
            val dL = -(len - bendRest[c]) / (w + alpha)
            px[i] += dx * dL * wi; py[i] += dy * dL * wi
            px[j] -= dx * dL * wj; py[j] -= dy * dL * wj
        }
    }

    private fun solveAreas(h: Double) {
        val alpha = AREA_COMPLIANCE / (h * h)
        // Вывернутым треугольникам своя, нулевая — см. AREA_COMPLIANCE_INVERTED.
        val alphaInverted = AREA_COMPLIANCE_INVERTED / (h * h)
        val maxStep = AREA_MAX_STEP * body.meanLinkLength
        // Всё в локальные: стадия идёт 64 раза за тик по трём тысячам треугольников.
        val px = px; val py = py; val invMass = invMass
        val ta = triA; val tb = triB; val tc = triC
        val rest2 = triRestArea2; val tm = triMuscle; val ms = muscleScaleOf
        for (t in 0 until triCount) {
            val i0 = ta[t]; val i1 = tb[t]; val i2 = tc[t]
            val x0 = px[i0]; val y0 = py[i0]
            val x1 = px[i1]; val y1 = py[i1]
            val x2 = px[i2]; val y2 = py[i2]

            val g0x = y1 - y2; val g0y = x2 - x1
            val g1x = y2 - y0; val g1y = x0 - x2
            val g2x = y0 - y1; val g2y = x1 - x0

            val w0 = invMass[i0]; val w1 = invMass[i1]; val w2 = invMass[i2]
            val denom = w0 * (g0x * g0x + g0y * g0y) +
                w1 * (g1x * g1x + g1y * g1y) +
                w2 * (g2x * g2x + g2y * g2y)
            if (denom < 1e-18) continue

            // Площадь покоя едет вместе с длинами: иначе мышца тянет треугольник вниз,
            // а несжимаемая площадь держит его на месте, и ткань запирает.
            val m = tm[t]
            val s = if (m < 0) 1.0 else ms[m]
            val restArea2 = rest2[t].toDouble() * s * s
            val area2 = (x1 - x0) * (y2 - y0) - (y1 - y0) * (x2 - x0)
            // Плавный переход вместо ступеньки — см. AREA_SMOOTH_RAMP.
            val a = if (AREA_SMOOTH_RAMP) {
                val q = (area2 / restArea2).coerceIn(0.0, 1.0)
                alphaInverted + (alpha - alphaInverted) * q * q
            } else if (area2 < 0.0) alphaInverted else alpha
            var dL = -(area2 - restArea2) / (denom + a)
            // Потолок на длину поправки — см. AREA_MAX_STEP.
            if (maxStep > 0.0) {
                val corr = abs(dL) * sqrt(denom)
                if (corr > maxStep) dL *= maxStep / corr
            }

            px[i0] += w0 * dL * g0x; py[i0] += w0 * dL * g0y
            px[i1] += w1 * dL * g1x; py[i1] += w1 * dL * g1y
            px[i2] += w2 * dL * g2x; py[i2] += w2 * dL * g2y
        }
    }

    /**
     * ТЯГА МЫШИ — СИЛА, А НЕ ТЕЛЕПОРТ. Зовётся ПОСЛЕ updateVelocities.
     *
     * Раньше тяга правила ПОЗИЦИЮ прямо среди позиционных стадий, и из этого росли
     * сразу две беды, обе видимые руками.
     *
     * ПЕРВАЯ: сквозь тело можно было протащить что угодно. Контакт расталкивает
     * позиционно, но на следующем подшаге тяга снова ставила клетку туда же, куда
     * тянет курсор. Позиционная тяга ничем не ограничена и просто перетягивала
     * контакт, сколько бы тот ни отталкивал. Ткань при этом даже не напрягалась —
     * поэтому и синие треугольники не появлялись: рвать было нечего, клетка ехала
     * насквозь, а не продавливала.
     *
     * ВТОРАЯ: тяга за кость выходила тем сильнее, чем кость крупнее. projectBone
     * идёт ПОСЛЕ тяги и подтягивает ВЕСЬ кластер к сдвинутой клетке, так что одна
     * позиционная поправка двигала всю костную массу целиком.
     *
     * Обе беды снимает одно и то же: тяга задаёт СКОРОСТЬ, а положение получается
     * из неё через integrate на следующем подшаге. Тогда
     *   - контакт решает позиционно и ПОСЛЕДНИМ, значит выигрывает всегда;
     *   - кость сама делит тягу на свой размер: shape matching разносит смещение
     *     одной клетки по всему кластеру, и кость из N клеток трогается примерно
     *     в N раз медленнее. Делить вручную не нужно, это выходит из сохранения
     *     импульса.
     *
     * Ограничение по УСКОРЕНИЮ, а не по силе: тянуть надо одинаково отзывчиво и
     * лёгкую клетку, и тяжёлую, иначе мелкие клетки улетали бы от курсора. Деление
     * тяги по массе всё равно происходит, но уровнем ниже — в кости и в связях.
     */
    private fun applyDragVelocity(h: Double) {
        val i = dragId
        if (i < 0 || invMass[i] == 0.0) return
        val dx = mouseX - px[i]
        val dy = mouseY - py[i]
        val d = sqrt(dx * dx + dy * dy)
        if (d < 1e-12) return

        // РУКА ДАЁТ ПОСТОЯННУЮ СИЛУ, а не постоянное ускорение. Это и есть причина
        // несоразмерности тяги за кость.
        //
        // Раньше кость получала ТО ЖЕ УСКОРЕНИЕ, что одиночная клетка. Ускорение то
        // же, а масса в N раз больше — значит импульс в N раз больше, и чем крупнее
        // кластер, тем сильнее рывок. Именно это и наблюдалось: за самую большую
        // кость тело улетало несоизмеримо резче, чем за мягкую ткань.
        //
        // Теперь ограничена СИЛА. Одиночная клетка средней массы получает прежнее
        // ускорение, а кость из N клеток — в N раз меньшее, потому что тяжёлое и
        // разгоняется медленнее. Импульс за подшаг при насыщении выходит одинаковым
        // в обоих случаях, force * h, то есть тяга стала честной по импульсу.
        //
        // Массы нормированы так, что средняя клетка весит единицу (см. restInvMass),
        // поэтому эталонная масса здесь и есть единица, и отдельной константы для
        // неё не нужно.
        val b = if (bonesRigid) boneOf[i] else -1

        var mTotal = 0.0
        var cx = 0.0; var cy = 0.0
        val ids = if (b >= 0) rigidBones[b] else null
        if (ids != null) {
            for (k in ids) {
                if (invMass[k] <= 0.0) continue
                val m = 1.0 / invMass[k]
                mTotal += m; cx += m * px[k]; cy += m * py[k]
            }
            if (mTotal <= 0.0) return
            cx /= mTotal; cy /= mTotal
        }

        val force = DRAG_ACCEL * body.meanLinkLength / (DT * DT)
        val vLimit = DRAG_SPEED_LIMIT * MAX_SPEED_CELLS_PER_TICK * body.meanLinkLength / DT

        // ЦЕЛЬ ОБЯЗАНА БЫТЬ ДОСТИЖИМОЙ, иначе сервотяга превращается в ракету.
        //
        // Здесь стояло «доехать до курсора за один тик, но не быстрее
        // MAX_DRAG_SPEED», а это 4.0 мировых в секунду, то есть около 140 связей в
        // секунду. Схваченная клетка столько не развивает никогда: её держит тело,
        // и замер на записанном перетаскивании дал пик 1.37. Значит ошибка сервотяги
        // НИКОГДА не уменьшалась, полная сила давила без остановки, и тело полторы
        // секунды монотонно разгонялось: скорость центра масс 2.1 -> 8.0 связей/с,
        // вращение 0.28 -> 1.13 рад/с. Демпфирующее слагаемое в формуле есть, но
        // работает только у самой цели, куда дело не доходило.
        //
        // Вдобавок потолка было ДВА и они противоречили друг другу: цель
        // ограничивалась значением 4.0, а результат — vLimit, то есть 1.71. Цель
        // была заведомо недостижима по построению.
        //
        // Теперь потолок один. Как только клетка набирает vLimit, ошибка обращается
        // в ноль, сила снимается, и вместо бесконечного разгона получается
        // предельная скорость — то есть рука, а не ракета.
        var vWant = d / DRAG_TAU
        if (vWant > vLimit) vWant = vLimit

        val wantX = dx / d * vWant - vx[i]
        val wantY = dy / d * vWant - vy[i]

        if (ids == null) {
            var jx = wantX / invMass[i]
            var jy = wantY / invMass[i]
            val jm = sqrt(jx * jx + jy * jy)
            val jMax = force * h
            if (jm > jMax) { val s = jMax / jm; jx *= s; jy *= s }
            var nvx = vx[i] + jx * invMass[i]
            var nvy = vy[i] + jy * invMass[i]
            val v = sqrt(nvx * nvx + nvy * nvy)
            if (v > vLimit) { val sc = vLimit / v; nvx *= sc; nvy *= sc }
            vx[i] = nvx; vy[i] = nvy
            return
        }

        // КОСТЬ ТЯНЕТСЯ ЦЕЛИКОМ, а не через одну свою клетку.
        //
        // Дать скорость одной клетке жёсткой кости нельзя: projectBone тут же
        // вернёт её на жёсткую позу, updateVelocities сделает из возврата скорость
        // ПРОТИВОПОЛОЖНУЮ тяге, а на следующем подшаге тяга надавит снова. Кость
        // начинает перекачиваться сама с собой на частоте подшагов — отсюда и
        // хаотичная скорость, и разрывы ткани там, где рука её не касалась.
        //
        // Правильно — приложить импульс В ТОЧКУ ЗАХВАТА ко всему твёрдому телу и
        // разнести его как положено: поступательная часть J/M одинакова для всех,
        // вращательная (r x J)/I добавляет скорость по радиусу. Тогда поза кости
        // не нарушается вовсе, проекции нечего исправлять, и качаться нечему.
        //
        // Величина импульса подобрана так, чтобы кость получала ТО ЖЕ линейное
        // ускорение, что получила бы одиночная клетка. Значит тяжёлую кость тянуть
        // так же отзывчиво, как лёгкую, а вот тело вокруг неё сопротивляется по
        // своей массе — что и требуется.
        var inertia = 0.0
        var maxR = 0.0
        for (k in ids) {
            if (invMass[k] <= 0.0) continue
            val rx = px[k] - cx; val ry = py[k] - cy
            val r2 = rx * rx + ry * ry
            inertia += r2 / invMass[k]
            if (r2 > maxR) maxR = r2
        }
        maxR = sqrt(maxR)

        // ЭФФЕКТИВНАЯ МАССА В ТОЧКЕ ЗАХВАТА — вот где был баг с хвостом.
        //
        // Прежний код считал импульс как J = m * dv, будто точка захвата отзывается
        // на силу ускорением J/M. Для твёрдого тела это неверно: сила в точке на
        // расстоянии r от центра ещё и КРУТИТ, и та же точка отзывается сильнее —
        // J/M плюс вклад вращения (r x J)/I по радиусу.
        //
        // Насколько сильнее — считается точно. Для стержня, схваченного за кончик,
        // множитель 1 + M*r^2/I равен четырём. То есть сервотяга вчетверо
        // ПЕРЕДАВЛИВАЛА, точка проскакивала цель, на следующем подшаге тяга давила
        // в обратную сторону — и раскачка шла по вращательной степени свободы,
        // которую servo по одной точке вообще не видит: у твёрдого тела три
        // степени свободы, а скорость точки задаёт только две.
        //
        // Отсюда и наблюдаемое руками: схватить хвост, потянуть, отпустить,
        // потянуть снова — и организм начинает бешено вращаться. И отсюда же дрейф
        // кирпича от одного лишь удержания кости: 0.208 связи в секунду при полной
        // физике против 3.1e-14 без среды.
        //
        // Правильно — решить систему на импульс честно. Скорость точки меняется как
        //     dv = J/M + ((r x J)/I) x r,
        // что в двумерии есть линейная система dv = A*J с симметричной матрицей
        //     A = [[1/M + ry^2/I,  -rx*ry/I ],
        //          [ -rx*ry/I,     1/M + rx^2/I]].
        // Она положительно определена, обращается в две строки, и найденный J даёт
        // точке РОВНО заданное изменение скорости. Перелёту взяться неоткуда.
        val rgx = px[i] - cx; val rgy = py[i] - cy
        val invI = if (inertia > 1e-18) 1.0 / inertia else 0.0
        val invM = 1.0 / mTotal
        val a11 = invM + rgy * rgy * invI
        val a12 = -rgx * rgy * invI
        val a22 = invM + rgx * rgx * invI
        val det = a11 * a22 - a12 * a12
        if (det < 1e-24) return
        var jx = (a22 * wantX - a12 * wantY) / det
        var jy = (a11 * wantY - a12 * wantX) / det

        // Сила руки ограничена одинаково для любой кости — см. выше про постоянную
        // силу. Ограничивается ИМПУЛЬС, а не ускорение, иначе крупная кость снова
        // получала бы больше импульса, чем мелкая.
        val jm = sqrt(jx * jx + jy * jy)
        val jMax = force * h
        if (jm > jMax) { val sJ = jMax / jm; jx *= sJ; jy *= sJ }

        val dOmega = (rgx * jy - rgy * jx) * invI

        // Прикидываем итог и, если самая быстрая клетка кости выходит за потолок,
        // ослабляем ВЕСЬ импульс — и поступательную часть, и вращательную. Резать
        // скорости по одной здесь нельзя: это сломало бы и жёсткость позы, и
        // сохранение импульса, ради которого весь этот кусок и написан.
        var worst = 0.0
        for (k in ids) {
            if (invMass[k] <= 0.0) continue
            val rx = px[k] - cx; val ry = py[k] - cy
            val nvx = vx[k] + jx / mTotal - dOmega * ry
            val nvy = vy[k] + jy / mTotal + dOmega * rx
            val v = sqrt(nvx * nvx + nvy * nvy)
            if (v > worst) worst = v
        }
        var sc = 1.0
        if (worst > vLimit && worst > 1e-18) sc = vLimit / worst

        for (k in ids) {
            if (invMass[k] <= 0.0) continue
            val rx = px[k] - cx; val ry = py[k] - cy
            vx[k] += sc * (jx / mTotal - dOmega * ry)
            vy[k] += sc * (jy / mTotal + dOmega * rx)
        }
    }

    private var dragShiftX = 0.0
    private var dragShiftY = 0.0

    /**
     * Направление обхода связей в solveConstraints. Переворачивается каждый подшаг.
     *
     * ЭТО ЛЕЧИТ ВТОРОЙ ИСТОЧНИК БЛУЖДАНИЯ — паразитный МОМЕНТ, который к точности
     * счёта отношения не имеет вовсе.
     *
     * Откуда он берётся. Отдельно взятое ограничение расстояния момента не создаёт
     * никогда: поправка идёт вдоль связи, а плечо у неё — сама связь, и векторное
     * произведение равно нулю ТОЧНО. Но Гаусс-Зейдель обходит связи подряд, и каждая
     * следующая видит позиции, уже сдвинутые предыдущими. Плечо, относительно которого
     * поправка была безмоментной, к этому времени уже уехало. Ошибка второго порядка по
     * величине поправки, но она СИСТЕМАТИЧЕСКАЯ — знак у неё задаёт порядок нумерации
     * связей, а он от кадра к кадру один и тот же.
     *
     * ЗАМЕР, который это доказывает. Мышца сокращена и удерживается 2000 кадров,
     * внешних сил нет вовсе, всё в double (чтобы округление не мешало):
     *
     *     обход вперёд   ->  L = +4.4269
     *     обход назад    ->  L = -4.3953      знак ПЕРЕВЕРНУЛСЯ
     *     чередуя        ->  L = +0.0813      в 54 раза меньше
     *
     * Знак переворачивается вместе с порядком — значит дело именно в порядке, а не в
     * физике и не во float. Отсюда и лекарство: чередовать. Это симметричный
     * Гаусс-Зейдель, стандартный приём, а не подпорка; стоит он ровно ноль — цикл тот
     * же, просто индекс идёт в другую сторону.
     *
     * ЧТО БЫЛО БЕЗ ЭТОГО: омега 4.4e-2 рад/с, то есть тело само разворачивалось на
     * полный круг за 144 секунды симуляции. На ускорении это минута с небольшим.
     *
     * АЛЬТЕРНАТИВА, которая тоже работает, но дороже: поднять число подшагов. Замер
     * (double, обход вперёд): 4 -> L 4.43, 8 -> 1.15, 16 -> 0.29, 32 -> 0.017. То есть
     * восемь подшагов вместо чередования дадут вчетверо худший результат при вдвое
     * большей цене. Чередование лучше по обоим счётам.
     */
    private var sweepBackwards = false

    /**
     * Как часто менять направление обхода: 0 — никогда, 1 — раз в подшаг, 2 — каждый
     * проход решателя. Переменная окружения RB_SWEEP. См. SWEEP_FLIP.
     */
    internal var sweepFlip = System.getenv("RB_SWEEP")?.toIntOrNull() ?: SWEEP_FLIP

    /**
     * Убирает смещение центра масс, накопленное ВНУТРЕННИМИ стадиями подшага.
     *
     * [beforeX]/[beforeY] — сумма координат до них. Внутренние ограничения обязаны
     * сохранять центр масс точно, поэтому вся разница (за вычетом честного вклада
     * мыши) — это округление float32, и её можно вычесть без всякой физики.
     */
    // --- ЗАМЕР ПО СТАДИЯМ: кто сколько двигает позиции и во сколько скорости ---
    //
    // Смысл в одном: скорость здесь не интегрируется, а восстанавливается из
    // позиций как (px - prevX) / h. Значит любая позиционная поправка, чья угодно,
    // умножается на 480 и становится скоростью. Замер отвечает, чья именно.
    // Выключен по умолчанию: стоит копирования позиций на каждую стадию.
    var dbgStages = false
    /**
     * Стадии: 0 связи, 1 площади, 2 изгиб, 3 кость, 4 предел длины, 5 контакты,
     * 6 широкая фаза+CCD, 7 отскок, 8 мышь+вязкость, 9 лоскуты, 10 анизотропная среда,
     * 11 изотропная среда+пол+потолок скорости, 12 снятие дрейфа.
     */

    val dbgStageMove = DoubleArray(DBG_STAGES)
    /**
     * Сколько МОМЕНТА ИМПУЛЬСА внесла стадия. Считается как сумма m * (r x dp) / h.
     *
     * Парная поправка вдоль линии между клетками даёт тождественный ноль, и то же
     * верно для площади: сумма r x grad по трём вершинам треугольника сокращается
     * тождественно. Поэтому ненулевое число здесь сразу называет виновника, и гадать
     * по списку стадий больше не нужно.
     */
    val dbgStageL = DoubleArray(DBG_STAGES)
    /** Сколько ЛИНЕЙНОГО импульса внесла стадия, вектором. Тяга берётся отсюда. */
    val dbgStagePx = DoubleArray(DBG_STAGES)
    val dbgStagePy = DoubleArray(DBG_STAGES)
    val dbgStageHits = IntArray(DBG_STAGES)
    /** Сумма модулей смещений стадии по замеряемым клеткам — сколько она РАБОТАЕТ. */
    val dbgStageAbs = DoubleArray(DBG_STAGES)
    /** Если задан, замер идёт только по этим клеткам. */
    var dbgOnly: BooleanArray? = null
    private var dbgSnapX = DoubleArray(0)
    private var dbgSnapY = DoubleArray(0)

    /**
     * ЗАМЕР ВРЕМЕНИ ПО СТАДИЯМ: включается на время опыта, см. PerfBench.
     *
     * Отдельно от замера по импульсу (dbgStages): тот отвечает на вопрос «кто добавил
     * движение», этот — «кто съел время». Имена стадий в dbgTimeNames.
     */
    internal var dbgTimeOn = false
    internal val dbgTimeNs = LongArray(12)
    internal val dbgTimeNames = arrayOf(
        "связи", "лоскуты", "предел длины", "площади", "изгиб", "кость",
        "подготовка контактов", "решатель контактов", "снятие момента",
        "скорости и среда", "ловушка", "пересборка")
    private var dbgTimeT0 = 0L

    private fun tick0() { if (dbgTimeOn) dbgTimeT0 = System.nanoTime() }
    private fun tick1(k: Int) { if (dbgTimeOn) dbgTimeNs[k] += System.nanoTime() - dbgTimeT0 }

    private fun dbgMark() {
        if (!dbgStages) return
        if (dbgSnapX.size < n) { dbgSnapX = DoubleArray(n); dbgSnapY = DoubleArray(n) }
        System.arraycopy(px, 0, dbgSnapX, 0, n)
        System.arraycopy(py, 0, dbgSnapY, 0, n)
    }

    private var dbgSnapVx = DoubleArray(0)
    private var dbgSnapVy = DoubleArray(0)

    /** То же для проходов по СКОРОСТЯМ: импульс берётся прямо из vx, vy. */
    private fun dbgMarkV() {
        if (!dbgStages) return
        if (dbgSnapVx.size < n) { dbgSnapVx = DoubleArray(n); dbgSnapVy = DoubleArray(n) }
        System.arraycopy(vx, 0, dbgSnapVx, 0, n)
        System.arraycopy(vy, 0, dbgSnapVy, 0, n)
    }

    private fun dbgMeasureV(k: Int) {
        if (!dbgStages) return
        val only = dbgOnly
        var m0 = 0.0; var cx = 0.0; var cy = 0.0
        for (i in 0 until n) {
            if (invMass[i] <= 0.0) continue
            if (only != null && !only[i]) continue
            val m = 1.0 / invMass[i]
            m0 += m; cx += m * px[i]; cy += m * py[i]
        }
        if (m0 > 0.0) { cx /= m0; cy /= m0 }
        var dpx = 0.0; var dpy = 0.0; var dl = 0.0; var hits = 0
        for (i in 0 until n) {
            if (invMass[i] <= 0.0) continue
            if (only != null && !only[i]) continue
            val m = 1.0 / invMass[i]
            val ddx = vx[i] - dbgSnapVx[i]; val ddy = vy[i] - dbgSnapVy[i]
            if (ddx != 0.0 || ddy != 0.0) hits++
            dpx += m * ddx; dpy += m * ddy
            dl += m * ((px[i] - cx) * ddy - (py[i] - cy) * ddx)
        }
        dbgStageHits[k] += hits
        dbgStagePx[k] += dpx; dbgStagePy[k] += dpy
        dbgStageL[k] += dl
    }

    private fun dbgMeasure(k: Int, h: Double) {
        if (!dbgStages) return
        var worst = 0.0
        var hits = 0
        val only = dbgOnly
        for (i in 0 until n) {
            if (invMass[i] <= 0.0) continue
            if (only != null && !only[i]) continue
            val dx = px[i] - dbgSnapX[i]; val dy = py[i] - dbgSnapY[i]
            val d = Math.sqrt(dx * dx + dy * dy)
            if (d > 1e-12) hits++
            if (d > worst) worst = d
            dbgStageAbs[k] += d
        }
        if (worst / h > dbgStageMove[k]) dbgStageMove[k] = worst / h
        dbgStageHits[k] += hits
        // Момент считается от общего центра масс замеряемых клеток. Начало отсчёта
        // роли не играет, пока суммарный импульс стадии нулевой, но так надёжнее.
        var m0 = 0.0; var cx = 0.0; var cy = 0.0
        for (i in 0 until n) {
            if (invMass[i] <= 0.0) continue
            if (only != null && !only[i]) continue
            val m = 1.0 / invMass[i]
            m0 += m; cx += m * dbgSnapX[i]; cy += m * dbgSnapY[i]
        }
        if (m0 <= 0.0) return
        cx /= m0; cy /= m0
        var dl = 0.0
        var dpx = 0.0; var dpy = 0.0
        for (i in 0 until n) {
            if (invMass[i] <= 0.0) continue
            if (only != null && !only[i]) continue
            val m = 1.0 / invMass[i]
            val rx = dbgSnapX[i] - cx; val ry = dbgSnapY[i] - cy
            val ddx = px[i] - dbgSnapX[i]; val ddy = py[i] - dbgSnapY[i]
            dl += m * (rx * ddy - ry * ddx)
            dpx += m * ddx; dpy += m * ddy
        }
        dbgStageL[k] += dl / h
        dbgStagePx[k] += dpx / h; dbgStagePy[k] += dpy / h
    }

    /**
     * СНЯТИЕ ИМПУЛЬСА И МОМЕНТА ВНУТРЕННИХ СТАДИЙ — см. InternalMomentum, там и замеры.
     * Контакты копят свои смещения в extDx/extDy, и из снимаемого они вычитаются.
     */
    internal var internalMom: InternalMomentum? = null
    /** Включено ли снятие. Переменной, а не константой, — ради A/B на журнале игрока. */
    internal var cancelSpinOn = CANCEL_INTERNAL_SPIN

    private fun markInternal() {
        internalMom?.mark(px, py, organismOf, organismCount)
    }

    private fun cancelInternalSpin() {
        internalMom?.cancel(organismOf, organismCount, px, py, prevX, prevY, invMass)
    }

    private fun cancelInternalDrift(beforeX: Double, beforeY: Double) {
        var afterX = 0.0
        var afterY = 0.0
        for (i in 0 until n) { afterX += px[i]; afterY += py[i] }
        val dx = (afterX - beforeX - dragShiftX) / n
        val dy = (afterY - beforeY - dragShiftY) / n
        for (i in 0 until n) { px[i] -= dx; py[i] -= dy }
    }

    /**
     * Shape matching, alpha = 1. Проекция кости на позу покоя.
     *
     * ГЛАВНЫЙ ИСТОЧНИК ПАРАЗИТНОГО ДРЕЙФА БЫЛ ИМЕННО ЗДЕСЬ — и это была не физика,
     * а сокращение значащих разрядов float32. Замер на этом теле, 600 кадров удержания
     * мышцы, суммарное смещение центра масс от каждой стадии (идеал — ноль):
     *
     *     стадия              как было      после починки
     *     solveConstraints    1.1e-05        1.8e-05
     *     solveAreas          6.0e-05        (см. AREA_COMPLIANCE)
     *     projectBone        -1.1e-02       -9.5e-06      в 1170 раз меньше
     *
     * То есть проекция кости текла в ТЫСЯЧУ раз сильнее, чем оба ограничения вместе.
     * updateVelocities делит это смещение на h, то есть умножает на 576, и оно попадает
     * прямо в скорость: суммарный импульс тела за 600 кадров был |P| = 9.8 при массе 370.
     * Отсюда и «мышца дёрнулась пару раз, а тело потом само куда-то уплывает».
     *
     * ПОЧЕМУ ТЕКЛО. Всё считалось в МИРОВЫХ координатах: px около 1.55, а смещение от
     * центра кости около 0.05. Разность двух чисел величиной 1.55 несёт ошибку 1e-7
     * АБСОЛЮТНУЮ, то есть 2e-6 ОТНОСИТЕЛЬНО самого смещения. В сумме по кластеру эти
     * ошибки не гасятся, и сумма w*q, которая обязана быть нулём по определению
     * центроида, оказывается порядка 1e-5. Ровно на неё центр масс кости и съезжает —
     * каждый подшаг, всегда примерно в одну сторону, потому что поза покоя постоянна.
     *
     * ТРИ ЛЕКАРСТВА, по вкладу (замер выше; разбирающий их стенд был одноразовым и
     * удалён, цифры перенесены сюда):
     *   1. локальное начало отсчёта — числа порядка размера кости, а не мира: 24x;
     *   2. смещения позы покоя q0 предпосчитаны и досажены суммой в ноль: само по себе
     *      почти ничего не даёт, но нужно для п.3 и убирает работу с горячего пути;
     *   3. суммарная поправка обнуляется ЯВНО: ещё 45x, итого 1170x.
     *
     * Зачёт УГЛОВОЙ поправки тоже пробовался и оказался вреден: линейная утечка от него
     * выросла с 9.5e-6 до 9.8e-5, а угловая не улучшилась. Дело в том, что оптимальный
     * угол best-fit сам по себе даёт нулевой угловой импульс — это условие
     * стационарности того максимума, который ищет полярное разложение. Угловая утечка
     * живёт не здесь, а в solveAreas.
     *
     * ЧЕМ ЗА ЭТО ЗАПЛАЧЕНО, честно. Прежняя версия в позе покоя давала РОВНО ноль:
     * она собирала позицию обратно из тех же самых сумм, из которых считала центроид,
     * и промахи взаимно уничтожались до бита. Здесь q0 предпосчитан, поэтому цель
     * отличается от body.x на 1e-7, и в покое остаётся ненулевая поправка. Замер,
     * 2400 кадров без всякой активности мышц: смещение центра масс 1.3e-3, и это
     * СЛУЧАЙНОЕ БЛУЖДАНИЕ (знак меняется), а не снос. Против 0.742 за 70 секунд после
     * одного сокращения — то есть проиграно 500x там, где выиграно 16x. Вернуть точный
     * ноль в покое, не отказываясь от предпосчитанного r0, у меня не получилось:
     * пробовал и мировые координаты вместо локальных (утечка в покое 1.7e-3, а выбег
     * ХУЖЕ: |P| 0.49 против 0.14), и отказ от досаживания суммы q0 в ноль (3.3e-3 и
     * |P| 0.42). Обе хуже по обоим показателям сразу.
     */
    private fun projectBone(b: Int) {
        val ids = rigidBones[b]
        val q0x = boneRestQx[b]
        val q0y = boneRestQy[b]

        // Начало отсчёта — первая вершина кости. Дальше все числа порядка размера
        // кости, и сокращения значащих разрядов больше нет.
        val ox = px[ids[0]]; val oy = py[ids[0]]

        var cx = 0.0; var cy = 0.0; var wsum = 0.0
        for (i in ids) {
            val w = matchWeight[i]
            cx += w * (px[i] - ox); cy += w * (py[i] - oy)
            wsum += w
        }
        cx /= wsum; cy /= wsum

        var s = 0.0; var t = 0.0
        for (k in ids.indices) {
            val i = ids[k]
            val w = matchWeight[i]
            val ppx = (px[i] - ox) - cx; val ppy = (py[i] - oy) - cy
            s += w * (q0x[k] * ppx + q0y[k] * ppy)
            t += w * (q0x[k] * ppy - q0y[k] * ppx)
        }
        val norm = sqrt(s * s + t * t)
        if (norm < 1e-12) return
        val cos = s / norm; val sin = t / norm

        // Считаются ПОПРАВКИ, а не сразу позиции: только по ним и можно обнулить
        // утечку. Сама поправка мала (1e-6), поэтому её сумма считается точно.
        var sdx = 0.0; var sdy = 0.0
        for (k in ids.indices) {
            val i = ids[k]
            val tx = ox + cx + cos * q0x[k] - sin * q0y[k]
            val ty = oy + cy + sin * q0x[k] + cos * q0y[k]
            boneDx[k] = tx - px[i]; boneDy[k] = ty - py[i]
            val w = matchWeight[i]
            sdx += w * boneDx[k]; sdy += w * boneDy[k]
        }
        val mdx = sdx / wsum; val mdy = sdy / wsum

        // ПОТОЛОК НА СМЕЩЕНИЕ ЗА ПОДШАГ — см. BONE_MAX_STEP.
        //
        // Масштабируется ВЕСЬ набор поправок ОДНИМ множителем, и это принципиально:
        // сумма поправок уже обнулена выше, а умножение нуля на что угодно остаётся
        // нулём. Обрезать поправки по отдельности было бы нельзя — сохранение центра
        // масс, ради которого весь этот код и переписан, сломалось бы сразу.
        var maxD2 = 0.0
        for (k in ids.indices) {
            val dx = boneDx[k] - mdx
            val dy = boneDy[k] - mdy
            val d2 = dx * dx + dy * dy
            if (d2 > maxD2) maxD2 = d2
        }
        var scale = 1.0
        val cap = BONE_MAX_STEP * body.meanLinkLength
        if (maxD2 > cap * cap) {
            scale = cap / sqrt(maxD2)
            boneCapHits++
        }

        for (k in ids.indices) {
            val i = ids[k]
            px[i] += (boneDx[k] - mdx) * scale
            py[i] += (boneDy[k] - mdy) * scale
        }
    }

    /** Сколько раз потолок кости сработал с последнего сброса. Показывается в HUD. */
    private var boneCapHits = 0

    private fun integrate(h: Double) {
        for (i in 0 until n) {
            prevX[i] = px[i]; prevY[i] = py[i]; inContact[i] = false
            if (invMass[i] == 0.0) continue
            vy[i] += GRAVITY * h
            px[i] += vx[i] * h
            py[i] += vy[i] * h
            if (py[i] < GROUND_Y) {
                px[i] += (prevX[i] - px[i]) * GROUND_FRICTION
                py[i] = GROUND_Y
                inContact[i] = true
            }
        }
    }

    private fun updateVelocities(h: Double) {
        for (i in 0 until n) {
            if (invMass[i] == 0.0) { vx[i] = 0.0; vy[i] = 0.0; continue }
            vx[i] = (px[i] - prevX[i]) / h
            vy[i] = (py[i] - prevY[i]) / h
        }
    }

    /** Продольная вязкость: гасит скорость деформации, жёсткое движение не трогает. */
    private fun applyViscosity(h: Double) {
        var k = VISCOSITY * h
        if (k > 0.5) k = 0.5
        for (c in 0 until conCount) {
            val i = conA[c]; val j = conB[c]
            val wi = invMass[i]; val wj = invMass[j]
            val w = wi + wj
            if (w == 0.0) continue
            var nx = px[j] - px[i]
            var ny = py[j] - py[i]
            val len = sqrt(nx * nx + ny * ny)
            if (len < 1e-12) continue
            nx /= len; ny /= len
            val dv = (vx[j] - vx[i]) * nx + (vy[j] - vy[i]) * ny
            val si = k * wi / w; val sj = k * wj / w
            vx[i] += dv * nx * si; vy[i] += dv * ny * si
            vx[j] -= dv * nx * sj; vy[j] -= dv * ny * sj
        }
    }

    /**
     * Анизотропное сопротивление среды на границе тела — то, что и создаёт тягу.
     *
     * Для каждого граничного ребра берётся скорость его середины, из неё выделяется
     * составляющая ВДОЛЬ НОРМАЛИ к ребру, и гасится только она. Тангенциальная остаётся
     * нетронутой: ребро, скользящее вдоль себя, среду не гребёт.
     *
     * Знак нормали не важен: выражение (v·n)·n не меняется при n -> -n, поэтому обходить
     * контур и выяснять, где у тела «наружу», не требуется.
     *
     * Сила пропорциональна ДЛИНЕ ребра: это площадь омываемой поверхности, и без неё
     * мелкие рёбра гребли бы наравне с крупными.
     *
     * Это ВНЕШНЯЯ сила, она осознанно не сохраняет импульс — среда его и уносит.
     */
    /** Диагностика: выключить анизотропное сопротивление среды, то есть тягу. */
    var dbgDragOff = false

    /** Во сколько раз крепче на разрыв связь мышцы с костью. См. TENDON_TEAR_FACTOR. */
    internal var tendonTear = System.getenv("RB_TENDON")?.toDoubleOrNull() ?: TENDON_TEAR_FACTOR

    /** Доля касательного трения от нормального. См. TANGENT_DRAG. */
    internal var tangentDrag = System.getenv("RB_TANGENT")?.toDoubleOrNull() ?: TANGENT_DRAG

    private fun applyNormalDrag(h: Double) {
        if (dbgDragOff) return
        var kd = FLOW_DECAY * h
        if (kd > 1.0) kd = 1.0

        // --- ЗАПАС СРЕДЫ. Догоняет скорость ЦЕНТРА МАСС, см. flowVX. ---
        //
        // Считается ДО цикла по рёбрам и ровно один раз: это одна степень свободы на
        // организм, а не на ребро. Вращение сюда не попадает — у чистого вращения
        // скорость центра масс равна нулю.
        if (FLOW_ENTRAIN > 0.0 && FLOW_MASS > 0.0) {
            // Скорость центра масс КАЖДОГО организма по отдельности.
            //
            // Раньше здесь было одно среднее по всем частицам мира, и это была прямая
            // ошибка: два тела делили один запас среды, поэтому движение одного толкало
            // другое на любом расстоянии, а тяга у обоих падала — запас следовал за
            // средней скоростью пары, а не за собственной скоростью тела.
            // ВЗВЕШЕННО ПО МАССЕ, и это не педантизм.
            //
            // Здесь стояла простая сумма скоростей, делённая на число клеток. Это
            // среднее по частицам, а не скорость центра масс: та есть сумма m*v на
            // сумму m. Пока все клетки весили одинаково, разница пряталась в общем
            // множителе, и код был верен ПО СОВПАДЕНИЮ.
            //
            // На теле с разными радиусами совпадение кончается, и ломается ровно тот
            // инвариант, который обещан в комментарии выше. У чистого вращения
            // сумма m*v равна нулю, а сумма одних только v равна omega, векторно
            // умноженному на N и на разность геометрического центра и центра масс, —
            // то есть НЕ ноль. Вращение начинает заряжать запас, среда толкает тело,
            // толчок снова крутит. Движение из ничего.
            for (o in 0 until organismCount) { comAccX[o] = 0.0; comAccY[o] = 0.0 }
            for (i in 0 until n) {
                if (invMass[i] <= 0.0) continue
                val o = organismOf[i]
                val m = 1.0 / invMass[i]
                comAccX[o] += m * vx[i]; comAccY[o] += m * vy[i]
            }

            // Это демпфер между телом и запасом: за шаг относительная скорость падает
            // на kf * (1 + FLOW_MASS). Выше единицы — переброс через ноль, то есть
            // раскачка, поэтому коэффициент здесь и ограничивается. С этим ограничением
            // модель устойчива при ЛЮБОЙ массе среды, и подбирать её можно свободно.
            var kf = FLOW_ENTRAIN * h
            val limit = 0.9 / (1.0 + FLOW_MASS)
            if (kf > limit) kf = limit

            for (o in 0 until organismCount) {
                val mo = organismMass[o]
                if (mo <= 0.0) continue
                val comVX = comAccX[o] / mo
                val comVY = comAccY[o] / mo
                val dfx = (comVX - flowVX[o]) * kf
                val dfy = (comVY - flowVY[o]) * kf
                flowVX[o] += dfx
                flowVY[o] += dfy
                comAccX[o] = dfx      // переиспользуем под плату, чтобы не заводить массив
                comAccY[o] = dfy
                // Рассеяние запаса в объём жидкости: только сток, никогда источник.
                // Без него запас был бы вечным аккумулятором импульса и тело не
                // остановилось бы никогда.
                flowVX[o] -= flowVX[o] * kd
                flowVY[o] -= flowVY[o] * kd
            }

            // Разгон среды телу СТОИТ: импульс FLOW_MASS * dFlow на каждую частицу.
            // Именно эта строка делает обмен честным — тело не может получить от среды
            // больше, чем вложило.
            for (i in 0 until n) {
                val o = organismOf[i]
                vx[i] -= FLOW_MASS * comAccX[o]
                vy[i] -= FLOW_MASS * comAccY[o]
            }
        }

        for (e in 0 until boundCount) {
            val i = boundA[e]; val j = boundB[e]
            val ex = px[j] - px[i]
            val ey = py[j] - py[i]
            val len = sqrt(ex * ex + ey * ey)
            if (len < 1e-12) continue

            val nx = -ey / len
            val ny = ex / len

            // Скорость середины ребра ОТНОСИТЕЛЬНО увлечённой среды: гребёт ребро целиком,
            // а не каждый конец отдельно. Вычитание общего вектора и даёт длинный накат —
            // когда среда догнала корпус, сопротивление его движению обнуляется, а
            // локальные взмахи плавника по-прежнему гребут в полную силу.
            // Запас берётся СВОЕГО организма: у каждого тела он свой, см. flowVX.
            val o = organismOf[i]
            val vmx = (vx[i] + vx[j]) * 0.5 - flowVX[o]
            val vmy = (vy[i] + vy[j]) * 0.5 - flowVY[o]
            val vn = vmx * nx + vmy * ny

            // Линейная плюс квадратичная. Квадратичная сила равна NORMAL_DRAG_Q * vn*|vn|,
            // поэтому в коэффициенте (он делится на vn) остаётся |vn|.
            var k = (NORMAL_DRAG + NORMAL_DRAG_QUADRATIC * abs(vn)) * len * h
            if (k > 0.5) k = 0.5      // выше — переброс скорости через ноль, то есть раскачка

            val dv = -vn * k
            vx[i] += dv * nx; vy[i] += dv * ny
            vx[j] += dv * nx; vy[j] += dv * ny

            // Трение ВДОЛЬ ребра. См. TANGENT_DRAG.
            if (tangentDrag > 0.0) {
                val tx = ex / len; val ty = ey / len
                val vt = vmx * tx + vmy * ty
                var kt = tangentDrag * NORMAL_DRAG * len * h
                if (kt > 0.5) kt = 0.5
                val dvt = -vt * kt
                vx[i] += dvt * tx; vy[i] += dvt * ty
                vx[j] += dvt * tx; vy[j] += dvt * ty
            }
        }
    }

    /**
     * Гашение отскока от пола: у контактной вершины убирается скорость ВВЕРХ.
     *
     * Это численный эффект, а не физика: контакт зажал позицию, решатель вернул её
     * обратно, а updateVelocities превратил разность позиций в настоящую скорость.
     * При GRAVITY = 0 стадия холостая — тело до пола не доходит.
     */
    private fun applyRestitution() {
        for (i in 0 until n) if (inContact[i] && vy[i] > 0.0) vy[i] *= GROUND_RESTITUTION
    }

    /**
     * Изотропное сопротивление среды. Нормировано на h, поэтому от числа подшагов
     * не зависит. Тягу не создаёт — см. комментарий у MEDIUM_DRAG.
     */
    /** Давление контактов на клетку за текущий тик, мировые единицы смещения. Обнуляется в начале тика. */
    internal var contactPressure = DoubleArray(0)

    /** Разбор: зовётся в конце каждого подшага с его номером. */
    internal var dbgSubstepHook: ((Int) -> Unit)? = null

    /** Диагностика: выключить и изотропное сопротивление среды. */
    var dbgIsoDragOff = false

    private fun applyMediumDrag(h: Double) {
        if (dbgIsoDragOff) return
        var keep = 1.0 - MEDIUM_DRAG * h
        if (keep < 0.0) keep = 0.0
        for (i in 0 until n) { vx[i] *= keep; vy[i] *= keep }
    }

    private fun simulate() {
        // Пересборка после разрывов стоит В САМОМ КОНВЕЙЕРЕ, а не в обёртке над ним.
        // Сначала она была в stepOnce — и не срабатывала в проверках вовсе, потому
        // что стенд зовёт simulate() напрямую: связи помечались порванными сотнями,
        // а убито было ноль. Та же ошибка уже подводила с пересборкой стадий.
        //
        // Ровно один раз за тик: внутри подшагов контур и контакты пересобирались бы
        // по шестнадцать раз, а рвётся обычно пучок связей за один удар.
        java.util.Arrays.fill(contactPressure, 0.0)
        java.util.Arrays.fill(crushedCell, false)
        if (tearsPending) { tick0(); rebuildTimed(); tick1(11) }
        val h = DT / SUBSTEPS
        // Нулевой слот — состояние на НАЧАЛО тика. Промежуточные пишутся ТОЛЬКО когда
        // их кто-то будет читать: в обычном режиме это лишние 242 КБ копирования за
        // тик, вымывающие кэш решателя. См. interpMode.
        val keepSubsteps = interpMode == 2
        histSnap(0)
        histCount = SUBSTEPS + 1
        histHasSubsteps = keepSubsteps
        for (step in 0 until SUBSTEPS) {
            // Длина покоя мышцы доезжает до своего значения за тик, а не прыгает в первом
            // же подшаге — см. muscleScaleOf.
            updateMuscleScale((step + 1).toDouble() / SUBSTEPS)
            // КОНТАКТ ПРИКЛАДЫВАЕТСЯ К СКОРОСТИ ДО ИНТЕГРИРОВАНИЯ, как гравитация.
            // Почему именно так и что было раньше — см. toVelocity в solveContacts.
            if (contacts != null && contactsOn && CONTACT_BEFORE_INTEGRATE) {
                contacts!!.prepare(px, py, prevX, prevY, vx, vy, invMass)
                contacts!!.updateBones(px, py, invMass,
                    if (bonesRigid) boneOf else null, rigidBones)
                contacts!!.solveContacts(px, py, vx, vy, invMass, h, 1.0, toVelocity = true)
            }
            integrate(h)

            // Скобка вокруг ВНУТРЕННИХ стадий: центр масс до и после. Внешние силы
            // (среда, пол, вязкость) идут ниже по скоростям и в скобку не попадают.
            var beforeX = 0.0
            var beforeY = 0.0
            // Только когда тело не держат: при активной тяге посылка «центр масс не
            // должен двигаться» неверна, и поправка даёт растяжение (см. константу).
            val cancel = CANCEL_INTERNAL_DRIFT && dragId < 0
            if (cancel) {
                for (i in 0 until n) { beforeX += px[i]; beforeY += py[i] }
                dragShiftX = 0.0; dragShiftY = 0.0
            }

            // Обход связей меняет направление КАЖДЫЙ подшаг — см. sweepBackwards.
            // Ставится здесь, а не внутри solveConstraints, чтобы фаза шла ровно по
            // подшагам и не зависела от того, сколько раз стадию позвали снаружи.

            // См. SWEEP_FLIP: раз в подшаг или каждый проход.
            if (sweepFlip == 1) sweepBackwards = !sweepBackwards
            // Снимок ДО внутренних стадий: всё, что они внесут сверх формы, снимется
            // перед контактами. См. cancelInternalSpin.
            if (cancelSpinOn) markInternal()
            // ЦИКЛ ПО ВСЕМ ОГРАНИЧЕНИЯМ СРАЗУ, ВКЛЮЧАЯ КОНТАКТ.
            //
            // Смысл в накоплении множителя. Сила при повторении просто умножается на
            // число заходов, и общий цикл с ней делал только хуже (0.096, 0.25, 0.92,
            // 6.25 при одном, двух, четырёх и восьми). Ограничение с накопленным
            // множителем ведёт себя наоборот: повторения его СХОДЯТ, и в равновесии
            // приращение обращается в ноль само. А в скорость идёт именно приращение.
            //
            // Поэтому здесь связи и контакт стоят в одном цикле и делят между собой
            // одну и ту же невязку, вместо того чтобы переписывать работу друг друга.
            for (iter in 0 until SOLVER_ITERS) {
                if (sweepFlip == 2) sweepBackwards = !sweepBackwards
                tick0(); dbgMark(); solveConstraints(h); dbgMeasure(0, h); tick1(0)
                tick0(); dbgMark(); solveFlaps(h); dbgMeasure(9, h); tick1(1)
                tick0(); dbgMark(); solveLinkMaxLength(); dbgMeasure(4, h); tick1(2)
                tick0(); dbgMark(); solveAreas(h); dbgMeasure(1, h); tick1(3)
                tick0(); dbgMark(); solveBend(h); dbgMeasure(2, h); tick1(4)
                tick0(); dbgMark()
                if (bonesRigid) for (b in rigidBones.indices) projectBone(b)
                dbgMeasure(3, h); tick1(5)
                tick0(); dbgMark(); solveLinkMaxLength(); dbgMeasure(4, h); tick1(2)
                // РАЗРЫВ СРАЗУ, А НЕ В НАЧАЛЕ СЛЕДУЮЩЕГО ТИКА. См. TEAR_IMMEDIATE.
                if (TEAR_IMMEDIATE && tearsPending) { tick0(); rebuildTimed(); tick1(11); contactsStale = true }
                val ci = contacts
                if (ci != null && contactsOn) {
                    // Список пар строится на первом заходе — и заново после пересборки:
                    // у нового объекта контактов списка ещё нет.
                    if (iter == 0 || contactsStale) {
                        tick0(); dbgMark(); ci.prepare(px, py, prevX, prevY, vx, vy, invMass); dbgMeasure(6, h); tick1(6)
                        if (cancelSpinOn) internalMom?.noteContacts(ci)
                        contactsStale = false
                    }
                    ci.updateBones(px, py, invMass,
                        if (bonesRigid) boneOf else null, rigidBones)
                    tick0(); dbgMark(); ci.solveContacts(px, py, vx, vy, invMass, h); dbgMeasure(5, h); tick1(7)
                    if (ci.killN > 0) { applyKills(ci); contactsStale = true }
                }
            }
            // ПРЕДЕЛ ДЛИНЫ ПОВТОРНО, УЖЕ ПОСЛЕ КОСТИ.
            //
            // Первый вызов стоит после solveConstraints, но проекция кости идёт ПОЗЖЕ
            // и способна снова растянуть связь сверх предела — она ставит вершины на
            // жёсткую позу, ни на что не оглядываясь. А от этого предела зависит
            // непроницаемость границы: два соседних граничных круга перекрываются,
            // только пока расстояние между ними не больше суммы радиусов. Растянутая
            // костью связь оставляет в мембране щель, и сквозь неё можно воткнуть
            // чужое тело — что и наблюдалось при резком рывке за кость.
            dbgMark(); solveLinkMaxLength(); dbgMeasure(4, h)

            // Снять импульс и момент, внесённые ВНУТРЕННИМИ стадиями. Контакты стоят в том
            // же цикле, но их смещения копятся отдельно и не снимаются: контакт внешний
            // для организма и передаёт импульс между телами законно. См. InternalMomentum.
            tick0(); dbgMark(); if (cancelSpinOn) cancelInternalSpin(); dbgMeasure(12, h); tick1(8)

            // КОНТАКТЫ ПОСЛЕДНИМИ СРЕДИ ПОЗИЦИОННЫХ, и это принципиально.
            // projectBone перезаписывает позиции жёсткой позой; поставь контакты
            // раньше — и кость проходила бы сквозь тело, потому что её проекция
            // просто затирала бы расталкивание. Ценой идёт лёгкая нежёсткость кости
            // в момент удара: следующий подшаг возвращает её на место, а при 16
            // подшагах это незаметно.
            //
            // СПИСОК КОНТАКТОВ СТРОИТСЯ ЗДЕСЬ ЖЕ, а не сразу после integrate, и это
            // была настоящая дыра в непроницаемости.
            //
            // Широкая фаза, DDA и CCD раньше работали по позициям СРАЗУ ПОСЛЕ
            // integrate, то есть по чисто баллистическому предсказанию. А дальше
            // solveDrag и projectBone двигали клетки ещё раз, и порой очень далеко:
            // проекция кости жёсткая, рывок мышью за кость даёт огромное смещение.
            // Перекрытия, возникшие ИМЕННО от этого движения, в список не попадали —
            // и solvePositions про них просто не знал. Не «CCD не справился» и не
            // «частицы мягкие»: пары до решателя не доходили вовсе. Замер на рывке за
            // кость показывал 23 таких пары и проникновение на 0.58 порога.
            //
            // prevX/prevY по-прежнему держат начало подшага, поэтому DDA заметает
            // весь настоящий путь клетки за подшаг, включая ту часть, которую добавили
            // перетаскивание и кость. Это ровно то, ради чего свип и делался.

            dbgMark(); if (cancel) cancelInternalDrift(beforeX, beforeY); dbgMeasure(12, h)

            tick0()
            updateVelocities(h)
            // Отскок: позиционная часть удар гасит целиком, см. solveRestitution.
            dbgMarkV()
            val cr = contacts
            if (cr != null && contactsOn && !contactsStale) cr.solveRestitution(px, py, vx, vy, invMass)
            dbgMeasureV(7); dbgMarkV()
            applyDragVelocity(h)
            applyViscosity(h)
            dbgMeasureV(8); dbgMarkV()
            applyNormalDrag(h)
            dbgMeasureV(10); dbgMarkV()
            applyRestitution()
            applyMediumDrag(h)
            clampSpeed()
            dbgMeasureV(11); tick1(9)
            if (keepSubsteps || step == SUBSTEPS - 1) histSnap(step + 1)
            dbgSubstepHook?.invoke(step)
        }
        // Пластика — РАЗ В ТИК, после всех подшагов: течение медленное, внутри тика
        // ему делать нечего, а стоить оно будет в шестнадцать раз дороже.
        applyPlasticity(DT)
        burstByPressure()
    }

    /**
     * КЛЕТКА ЛОПАЕТСЯ ОТ ДАВЛЕНИЯ: если контакты за тик толкали её сильнее порога, она
     * умирает, как смерть от проникновения — связи рвутся, из контактов и отрисовки она
     * уходит. Кости бессмертны. Раз в тик, чтобы пересборка была одна на всех погибших.
     * Порог в связях смещения за тик, см. PRESSURE_BURST_LINKS; ноль — выключено.
     */
    internal var pressureBurst = System.getenv("RB_BURST")?.toDoubleOrNull() ?: PRESSURE_BURST_LINKS
    internal var pressureBurstCount = 0
    /** Клетки, у которых на этом тике связь порвалась на сжатии. См. CRUSH_BURST. */
    private var crushedCell = BooleanArray(0)
    internal var crushBurstCount = 0
    /** Связь лежит на контуре тела. См. MEMBRANE_TEAR_STRAIN. */
    private var conBoundary = BooleanArray(0)
    /** Связь мышцы с костью — сухожилие. См. TENDON_TEAR_FACTOR. */
    private var conTendon = BooleanArray(0)
    internal var membraneTearCount = 0
    internal var membraneTearStrain = System.getenv("RB_MEMBRANE")?.toDoubleOrNull() ?: MEMBRANE_TEAR_STRAIN
    internal var crushBurstOn = CRUSH_BURST && System.getenv("RB_CRUSH_OFF") == null

    /**
     * ЗАСТРЯВШАЯ В ЧУЖОЙ ТКАНИ КЛЕТКА ЛОПАЕТСЯ: центр внутри живого треугольника другого
     * организма столько тиков подряд. 0 — не убивать, меньше нуля — не искать вовсе.
     */
    internal var trapKillTicks = System.getenv("RB_TRAP")?.toIntOrNull() ?: TRAP_KILL_TICKS
    internal var trapKillCount = 0
    /** Сколько тиков подряд центр клетки в чужой ткани. См. scanTrapped. */
    private var trapTicks = IntArray(0)
    private var trapGridStart = IntArray(0)
    private var trapTriBox = IntArray(0)
    private var trapGridItems = IntArray(0)
    private var trapGridCount = IntArray(0)
    /** Разбор последнего обхода: в чужой ткани, из них в треугольнике без граничных вершин, костей, своих складок. */
    internal var dbgTrapNow = 0
    internal var dbgTrapDeep = 0
    internal var dbgTrapBone = 0
    internal var dbgTrapFold = 0
    internal var dbgTrapNs = 0L
    /** Разбор: сколько тиков клетка пробыла в чужой ткани, прежде чем вышла сама. Корзины — dbgTrapEdges. */
    internal val dbgTrapExit = IntArray(8)
    internal val dbgTrapEdges = intArrayOf(1, 2, 5, 10, 30, 90, 300, Int.MAX_VALUE)
    internal val dbgFoldExit = IntArray(8)
    private fun dbgTrapBin(k: Int): Int { var b = 0; while (k > dbgTrapEdges[b]) b++; return b }
    /** Складки своей ткани тоже лопаются. См. scanTrapped. */
    internal var trapKillFolds = System.getenv("RB_TRAP_FOLD")?.let { it != "0" } ?: TRAP_KILL_FOLDS
    internal var foldKillCount = 0
    private var foldTicks = IntArray(0)

    /**
     * Кто сидит в чужой ткани. Раз в тик.
     *
     * ДЁШЕВО, ПОТОМУ ЧТО СМОТРЯТСЯ ТОЛЬКО КЛЕТКИ С КОНТАКТОМ — граница и мелкие куски.
     * Внутренняя клетка тела в чужую ткань без своей границы не попадёт, а целиком
     * проглоченный кусок теряет границу слой за слоем: после каждой смерти пересборка
     * делает граничными следующих. Треугольники раскладываются по плотной сетке массивами
     * (без хешей), клетка проверяет только треугольники своей ячейки.
     */
    internal fun scanTrapped() {
        val ct = contacts ?: return
        val t0 = System.nanoTime()
        val n = n
        if (trapTicks.size != n) trapTicks = IntArray(n)
        if (foldTicks.size != n) foldTicks = IntArray(n)
        // Всё в локальные: поле lateinit проверяется на каждом обращении.
        val px = px; val py = py; val dead = cellDead; val org = organismOf; val ticks = trapTicks
        val ta = triA; val tb = triB; val tc = triC; val tn = triCount
        dbgTrapNow = 0; dbgTrapDeep = 0; dbgTrapBone = 0; dbgTrapFold = 0
        // ХЕШ ЯЧЕЕК, А НЕ ПЛОТНАЯ СЕТКА НА РАМКУ. Осколки разлетаются, рамка всех клеток
        // растягивается до миллиона ячеек, и почти каждое обращение к такой сетке — промах
        // кэша: 200 мкс на обход. Таблица на ~2 треугольника на корзину целиком лежит в
        // кэше. Совпадение корзин у разных ячеек даёт лишь лишних кандидатов — сама
        // проверка «центр в треугольнике» точная.
        var h = 1024
        while (h < tn * 2) h = h shl 1
        val mask = h - 1
        if (trapGridStart.size < h + 1) { trapGridStart = IntArray(h + 1); trapGridCount = IntArray(h + 1) }
        val start = trapGridStart; val cur = trapGridCount
        java.util.Arrays.fill(start, 0, h + 1, 0)
        val inv = 1.0 / (2.0 * body.meanLinkLength)
        val off = 1048576.0         // сдвиг, чтобы отбросить дробь без floor у отрицательных
        if (trapTriBox.size < tn * 4) trapTriBox = IntArray(tn * 8)
        val box = trapTriBox
        // 1. Ячейки каждого треугольника и сколько записей в корзине.
        for (t in 0 until tn) {
            val a = ta[t]; val b = tb[t]; val c = tc[t]
            val ax = px[a]; val bx = px[b]; val cx = px[c]
            val ay = py[a]; val by = py[b]; val cy = py[c]
            val x0 = (minOf(ax, bx, cx) * inv + off).toInt(); var x1 = (maxOf(ax, bx, cx) * inv + off).toInt()
            val y0 = (minOf(ay, by, cy) * inv + off).toInt(); val y1 = (maxOf(ay, by, cy) * inv + off).toInt()
            // Вытянутый в нитку треугольник — уже не ткань, а раскладывать его дорого.
            if ((x1 - x0 + 1) * (y1 - y0 + 1) > 16) x1 = x0 - 1
            val o = t * 4
            box[o] = x0; box[o + 1] = x1; box[o + 2] = y0; box[o + 3] = y1
            for (yy in y0..y1) for (xx in x0..x1) start[((xx * 73856093) xor (yy * 19349663)) and mask]++
        }
        // 2. Начала корзин и раскладка.
        var run = 0
        for (k in 0..h) { val c = start[k]; start[k] = run; cur[k] = run; run += c }
        if (trapGridItems.size < run) trapGridItems = IntArray(run * 2)
        val items = trapGridItems
        for (t in 0 until tn) {
            val o = t * 4
            for (yy in box[o + 2]..box[o + 3]) for (xx in box[o]..box[o + 1])
                items[cur[((xx * 73856093) xor (yy * 19349663)) and mask]++] = t
        }
        // 3. Клетки с контактом: центр в чужом треугольнике своей корзины.
        for (i in 0 until n) {
            if (dead[i] || ct.contactRadiusOf(i) <= 0.0) { ticks[i] = 0; foldTicks[i] = 0; continue }
            val x = px[i]; val y = py[i]
            val xx = (x * inv + off).toInt(); val yy = (y * inv + off).toInt()
            val k = ((xx * 73856093) xor (yy * 19349663)) and mask
            val oi = org[i]
            var foreign = -1; var fold = false
            for (s in start[k] until cur[k]) {
                val t = items[s]
                val a = ta[t]; val b = tb[t]; val c = tc[t]
                if (a == i || b == i || c == i) continue
                val ax = px[a]; val ay = py[a]; val bx = px[b]; val by = py[b]; val cx = px[c]; val cy = py[c]
                val d1 = (bx - ax) * (y - ay) - (by - ay) * (x - ax)
                val d2 = (cx - bx) * (y - by) - (cy - by) * (x - bx)
                val d3 = (ax - cx) * (y - cy) - (ay - cy) * (x - cx)
                if ((d1 < 0 || d2 < 0 || d3 < 0) && (d1 > 0 || d2 > 0 || d3 > 0)) continue
                if (org[a] == oi) { fold = true; continue }
                foreign = t
                break
            }
            // Складка — центр в СВОЁМ треугольнике, где клетка не вершина: ткань налезла на
            // себя. Считается отдельно, см. trapKillFolds.
            if (fold && foreign < 0) {
                foldTicks[i]++; dbgTrapFold++
            } else {
                if (foldTicks[i] > 0) dbgFoldExit[dbgTrapBin(foldTicks[i])]++
                foldTicks[i] = 0
            }
            if (foreign < 0) {
                if (ticks[i] > 0) dbgTrapExit[dbgTrapBin(ticks[i])]++
                ticks[i] = 0
                continue
            }
            ticks[i]++
            dbgTrapNow++
            if (boneOf[i] >= 0) dbgTrapBone++
            if (ct.contactRadiusOf(ta[foreign]) <= 0.0 && ct.contactRadiusOf(tb[foreign]) <= 0.0 &&
                ct.contactRadiusOf(tc[foreign]) <= 0.0) dbgTrapDeep++
        }
        dbgTrapNs += System.nanoTime() - t0
    }

    private fun burstByPressure() {
        if (!tearingOn || contactPressure.size != n) return
        // Порванное в последнем проходе предела длины ещё не пересобрано, а признак
        // «осталась без связей» берётся из пересборки.
        if ((crushBurstOn || trapKillTicks >= 0) && tearsPending) rebuildTimed()
        if (trapKillTicks >= 0) { tick0(); scanTrapped(); tick1(10) }
        val lim = pressureBurst * body.meanLinkLength
        var any = false
        for (i in 0 until n) {
            if (cellDead[i] || boneOf[i] >= 0 || invMass[i] <= 0.0) continue
            val byPressure = pressureBurst > 0.0 && contactPressure[i] > lim
            // РАЗДАВЛЕННАЯ КЛЕТКА ЛОПАЕТСЯ: связь порвалась на сжатии, и клетка осталась
            // совсем без связей. Иначе она свободной частицей остаётся внутри своей же
            // смятой ткани, где с ней ничто не сталкивается.
            val byCrush = crushBurstOn && crushedCell[i] && isFree[i]
            val byTrap = trapKillTicks > 0 && trapTicks.size == n && trapTicks[i] >= trapKillTicks
            val byFold = trapKillTicks > 0 && trapKillFolds && foldTicks.size == n && foldTicks[i] >= trapKillTicks
            if (!byPressure && !byCrush && !byTrap && !byFold) continue
            cellDead[i] = true; deadCount++
            when { byPressure -> pressureBurstCount++; byCrush -> crushBurstCount++; byTrap -> trapKillCount++; else -> foldKillCount++ }
            vx[i] = 0.0; vy[i] = 0.0
            any = true
        }
        if (!any) return
        for (c in 0 until conCount) if (cellDead[conA[c]] || cellDead[conB[c]]) conDead[c] = true
        tearsPending = true
        rebuildTimed()
    }

    /**
     * Один шаг модели: команды мышцам, их активации, потом физика.
     *
     * Вынесено из render() потому, что при ускорении повторять надо ВСЮ тройку, а не
     * только simulate(). Иначе gaitFrame и активации остались бы на частоте кадров,
     * гребок относительно физики замедлился бы в десять раз, и наблюдал бы ты совсем
     * другой режим, чем тот, который мерил стенд.
     */
    /** Разбор: сколько наносекунд занял последний тик целиком. */
    internal var dbgTickNs = 0L

    private fun stepOnce() {
        val tickT0 = System.nanoTime()
        // Цели мышц при воспроизведении берутся из журнала, а не из клавиатуры и
        // наведения: окна там нет, а записано ровно то, что получилось в игре.
        if (replay != null) replayTickInputs() else { updateMuscleTargets(); recordTickInputs() }
        recordMuscles()
        updateMuscles(DT)
        recordDrag()
        simulate()
        simTime += DT
        logTick++
        playTick++
        if (playTick % PlayerLog.HASH_EVERY == 0) tickHash()
        dbgTickNs = System.nanoTime() - tickT0
    }

    // ================================================================
    //  ЖУРНАЛ ИГРОКА — пишется ВСЕГДА, формат см. PlayerLog
    //
    //  Всё, что меняет физику, проходит через act(). Он же пишет строку в журнал, и
    //  он же исполняет строку при воспроизведении. Двух реализаций одного действия
    //  нет, поэтому и расходиться им не в чем: старая запись по L держала свою копию
    //  захвата и однажды забыла про вес shape matching.
    //
    //  Что в журнал НЕ попадает и почему это не нужно:
    //    - положение мыши без захвата. Физика читает курсор только у схваченной
    //      клетки (applyDragVelocity), а наведение на мышцу пишется результатом —
    //      строкой M;
    //    - пауза, скорость, ускорение, интерполяция, камера. Они меняют число тиков в
    //      секунду и картинку, но не сами тики.
    //
    //  Файл перезаписывается при каждом открытии окна. Без окна (стенды, разбор)
    //  create() не зовётся, и журнал не пишется вовсе.
    // ================================================================
    private var plog: java.io.BufferedWriter? = null
    /** Тиков с запуска окна. В отличие от logTick, сбросом не обнуляется. */
    private var playTick = 0
    private var plogMuscles = DoubleArray(0)
    private var plogCurX = Double.NaN
    private var plogCurY = Double.NaN

    /** Помеченные средней кнопкой клетки. Только для глаз и журнала. */
    private val marks = LinkedHashSet<Int>()
    private var wasMiddle = false

    private fun openPlayerLog(path: String = PlayerLog.FILE) {
        val f = java.io.File(path)
        try {
            val w = java.io.BufferedWriter(java.io.OutputStreamWriter(
                java.io.FileOutputStream(f, false), Charsets.UTF_8))
            val bf = java.io.File(bodyPath)
            w.write("# GENOMEIA PLAYER LOG v1\n")
            w.write("# разбор: gradlew :lwjgl3:playerReplay\n")
            w.write("# начат ${java.time.LocalDateTime.now()}\n")
            w.write("HDR body ${bf.absolutePath}\n")
            w.write("HDR bodyCrc ${PlayerLog.crc(bf)}\n")
            w.write("HDR copies $copies\n")
            w.write("HDR free $freeParticles\n")
            w.write("HDR killFraction $labKillFraction\n")
            w.write("HDR killSeed $labKillSeed\n")
            w.write("HDR killOnDeep ${if (killOnDeep) 1 else 0}\n")
            w.write("HDR ups ${Math.round(1.0 / DT)}\n")
            w.write("HDR substeps $SUBSTEPS\n")
            w.flush()
            plog = w
            println("[RealBodyDemo] журнал игрока: ${f.absolutePath}")
        } catch (e: java.io.IOException) {
            println("[RealBodyDemo] журнал игрока не открылся: ${e.message}")
        }
    }

    private fun closePlayerLog() {
        val w = plog ?: return
        plog = null
        try { w.write("$playTick END\n"); w.close() } catch (_: java.io.IOException) { }
    }

    private fun plogWrite(s: String, flush: Boolean) {
        val w = plog ?: return
        try {
            w.write(s); w.write("\n")
            if (flush) w.flush()
        } catch (e: java.io.IOException) {
            println("[RealBodyDemo] журнал игрока: запись оборвалась, ${e.message}")
            plog = null
        }
    }

    /**
     * ЕДИНСТВЕННАЯ ТОЧКА входа для действий, меняющих физику. Значения передаются
     * уже новые, а не «переключить»: так строка журнала читается сама по себе.
     */
    private fun act(op: Char, a: Int = 0) {
        // Сначала строка, потом исполнение: сцена внутри себя крутит тики, и их
        // строки обязаны лечь ПОСЛЕ строки самой сцены.
        plogWrite(if (op in "BDEGKNX") "$playTick $op $a" else "$playTick $op", flush = true)
        when (op) {
            'R' -> reset()
            'B' -> bonesRigid = a == 1
            'G' -> { gait = a == 1; gaitFrame = 0 }
            'K' -> contactsOn = a == 1
            'X' -> tearingOn = a == 1
            'E' -> bendLevel = a
            'N' -> sceneIndex = a
            'S' -> runScene()
            'P' -> fireBullet()
            'O' -> slamOrganisms()
            'D' -> {
                dragId = a; matchWeight[a] = DRAG_MATCH_WEIGHT
                // Курсор обязан попасть в журнал на первом же тике захвата.
                plogCurX = Double.NaN
                // Отсечка счётчиков на момент захвата: строка DRAG обязана
                // показывать, что натворила ИМЕННО ЭТА тяга. Счётчики
                // накопительные и обнуляются только по R, поэтому таран через O
                // красил строку у следующей же тяги, хотя она ни при чём.
                dragCapBase = speedCapHits
                // Пик именно ОБНУЛЯЕТСЯ, а не запоминается: это максимум, и
                // вычитать из максимума базу бессмысленно.
                peakSpeed2 = 0.0
            }
            'U' -> if (dragId >= 0) { matchWeight[dragId] = 1.0; dragId = -1 }
        }
    }

    /**
     * Входы, которые физика читает КАЖДЫЙ тик: цели мышц и курсор схваченной клетки.
     * Пишутся только при изменении — «держу гребок» это одна строка, а не тысяча.
     * Пишутся здесь, а не в handleInput: за кадр может пройти и ноль тиков, и десять,
     * а значение имеет только то, что увидел тик.
     */
    private fun recordTickInputs() {
        if (plog == null) return
        var changed = plogMuscles.size != muscleTarget.size
        if (!changed) for (m in muscleTarget.indices) if (muscleTarget[m] != plogMuscles[m]) { changed = true; break }
        if (changed) {
            plogMuscles = muscleTarget.copyOf()
            val sb = StringBuilder().append(playTick).append(" M ")
            var any = false
            for (m in muscleTarget.indices) {
                if (muscleTarget[m] == 0.0) continue
                if (any) sb.append(',')
                sb.append(m).append(':').append(muscleTarget[m])
                any = true
            }
            if (!any) sb.append('-')
            plogWrite(sb.toString(), flush = false)
        }
        if (dragId >= 0 && (mouseX != plogCurX || mouseY != plogCurY)) {
            plogCurX = mouseX; plogCurY = mouseY
            plogWrite("$playTick C $mouseX $mouseY", flush = false)
        }
    }

    private fun tickHash() {
        if (plog != null) {
            val h = PlayerLog.stateHash(n, px, py, vx, vy)
            plogWrite("$playTick H ${java.lang.Long.toHexString(h)}", flush = true)
            return
        }
        // При воспроизведении сумма сверяется здесь же: внутри сцены до разбора
        // журнала в replayRun дело не дойдёт, пока сцена не кончится.
        val lines = replay ?: return
        while (replayAt < lines.size) {
            val ln = lines[replayAt]
            if (ln.tick != playTick || ln.op != "H") break
            replayAt++
            replayCheckHash(ln)
        }
    }

    private fun toggleMark(i: Int) {
        if (marks.remove(i)) {
            plogWrite("$playTick UNMARK $i", flush = true)
            println("[МЕТКА] снята: клетка #$i, тик $playTick")
            return
        }
        marks.add(i)
        // Рядом с номером — где клетка была НАРИСОВАНА и в каком режиме смотрели:
        // на замедлении картинка отстаёт от физики на долю тика, и это надо видеть.
        plogWrite("$playTick MARK $i ${fx(i)} ${fy(i)} paused=${if (paused) 1 else 0} " +
            "scale=${controls.timeScale} alpha=$renderAlpha interp=$interpMode", flush = true)
        println("[МЕТКА] клетка #$i, тик $playTick (%.2f с)".format(playTick * DT))
    }

    // --- воспроизведение без окна, см. PlayerReplay ---
    private var replay: List<PlayerLog.Line>? = null
    private var replayAt = 0
    private var replayMuscle = DoubleArray(0)
    internal var replayHashOk = 0
        private set
    internal var replayHashBad = 0
        private set
    internal var replayFirstBadTick = -1
        private set
    internal val currentTick: Int get() = playTick

    /** То же, что create(), но без окна: тело, затем сброс. */
    internal fun replayBoot() {
        buildFromFile()
        reset()
    }

    /**
     * Исполнить журнал. onEvent зовётся ПОСЛЕ исполнения каждой строки-события —
     * для MARK это ровно то состояние, при котором игрок нажал кнопку.
     */
    internal fun replayRun(lines: List<PlayerLog.Line>, onEvent: (PlayerLog.Line) -> Unit,
                           onTick: () -> Unit) {
        replay = lines
        replayAt = 0
        replayMuscle = DoubleArray(muscleTarget.size)
        try {
            while (replayAt < lines.size) {
                val ln = lines[replayAt]
                if (ln.tick < playTick) {
                    println("[воспроизведение] РАССИНХРОН: строка «${ln.raw}» пришла на тике $playTick")
                    replayAt++
                    continue
                }
                if (ln.tick > playTick || ln.op == "M" || ln.op == "C") {
                    stepOnce(); onTick()
                    continue
                }
                replayAt++
                when (ln.op) {
                    "R", "B", "G", "K", "X", "E", "N", "S", "P", "O", "D", "U" ->
                        act(ln.op[0], ln.args.getOrNull(0)?.toInt() ?: 0)
                    "H" -> replayCheckHash(ln)
                }
                onEvent(ln)
                if (ln.op == "END") break
            }
        } finally {
            replay = null
        }
    }

    private fun replayTickInputs() {
        val lines = replay!!
        while (replayAt < lines.size) {
            val ln = lines[replayAt]
            if (ln.tick != playTick) break
            if (ln.op == "M") {
                replayMuscle.fill(0.0)
                val spec = ln.args.getOrNull(0) ?: "-"
                if (spec != "-") for (part in spec.split(',')) {
                    val k = part.indexOf(':')
                    val m = part.substring(0, k).toInt()
                    if (m < replayMuscle.size) replayMuscle[m] = part.substring(k + 1).toDouble()
                }
            } else if (ln.op == "C") {
                mouseX = ln.args[0].toDouble(); mouseY = ln.args[1].toDouble()
            } else break
            replayAt++
        }
        System.arraycopy(replayMuscle, 0, muscleTarget, 0, muscleTarget.size)
    }

    private fun replayCheckHash(ln: PlayerLog.Line) {
        val want = java.lang.Long.parseUnsignedLong(ln.args[0], 16)
        if (PlayerLog.stateHash(n, px, py, vx, vy) == want) { replayHashOk++; return }
        replayHashBad++
        if (replayFirstBadTick < 0) {
            replayFirstBadTick = ln.tick
            println("[воспроизведение] КОНТРОЛЬНАЯ СУММА НЕ СОШЛАСЬ на тике ${ln.tick}: " +
                "дальше состояние уже не то, что видел игрок")
        }
    }

    // ================================================================
    //  ЗАПИСЬ ДЕЙСТВИЙ МЫШЬЮ [L] И ИХ ВОСПРОИЗВЕДЕНИЕ
    //
    //  Зачем. Часть неустойчивости видна только руками: пользователь тащит
    //  конкретный кластер, отпускает, держит — и тело начинает дёргаться.
    //  Описать это словами достаточно точно, чтобы воспроизвести в тесте, не
    //  выходит: результат зависит от того, ЗА КАКУЮ клетку взялись и по какой
    //  траектории вели. Лог снимает этот разрыв — записанное воспроизводится
    //  побитово, потому что симуляция детерминирована.
    //
    //  Запись НАЧИНАЕТСЯ СО СБРОСА, и это обязательно: без известного начального
    //  состояния воспроизвести нечего — тело к моменту нажатия уже прожило
    //  произвольную историю.
    //
    //  Формат построчный и разреженный: строка пишется только когда что-то
    //  изменилось, поэтому «держу мышь на месте десять секунд» это одна строка, а
    //  не триста. При воспроизведении последняя команда держится до следующей.
    //
    //      D <тик> <клетка> <x> <y>   тянуть эту клетку к точке
    //      U <тик>                     отпустить
    //      E <тик>                     конец записи
    // ================================================================
    private var dragLog: StringBuilder? = null
    private var logTick = 0
    private var logLastId = -2
    private var logLastX = 0.0
    private var logLastY = 0.0

    private fun toggleDragLog() {
        val log = dragLog
        if (log == null) {
            // Сброс уже сделан снаружи через act('R'), чтобы попасть в журнал игрока.
            logTick = 0
            logLastId = -2
            val sb = StringBuilder()
            sb.append("# GENOMEIA DRAG LOG v1\n")
            sb.append("# body=").append(bodyPath).append('\n')
            sb.append("# ups=").append(Math.round(1.0 / DT))
                .append(" substeps=").append(SUBSTEPS)
                .append(" organisms=").append(ORGANISMS)
                .append(" free=").append(FREE_PARTICLES).append('\n')
            logMuscles = ""
            sb.append("# dragAccel=").append(DRAG_ACCEL)
                .append(" dragSpeedLimit=").append(DRAG_SPEED_LIMIT)
                .append(" bones=").append(if (bonesRigid) 1 else 0)
                .append(" contacts=").append(if (contactsOn) 1 else 0)
                .append(" bend=").append(bendLevel)
                .append(" gait=").append(if (gait) 1 else 0).append('\n')
            dragLog = sb
            println("[RealBodyDemo] ЗАПИСЬ НАЧАТА, тело сброшено. Нажми L снова, чтобы остановить.")
        } else {
            log.append("E ").append(logTick).append('\n')
            val out = java.io.File("drag-log.txt")
            out.writeText(log.toString())
            dragLog = null
            println("[RealBodyDemo] ЗАПИСЬ ОСТАНОВЛЕНА, строк " + log.count { it == '\n' } +
                ", файл " + out.absolutePath)
            println("----- НАЧАЛО ЛОГА -----")
            print(log)
            println("----- КОНЕЦ ЛОГА -----")
        }
    }

    /**
     * ЗАПИСЬ СОСТОЯНИЯ МЫШЦ. Без неё лог был неполон, и это уже подвело.
     *
     * Воспроизведение гоняло с выключенными мышцами, потому что в логе о них не
     * было ни слова. Записанное перетаскивание при этом сходилось к курсору
     * идеально, а руками тело улетало и не возвращалось — расхождение объяснялось
     * ровно тем, что при записи работал гребок, и тело уплывало СВОИМ ХОДОМ.
     *
     * Пишется строка вида «M тик 0:1.0,3:0.5» — только ненулевые цели и только
     * когда набор изменился. Молчащие мышцы не дают ни одной строки.
     */
    private var logMuscles = ""

    private fun recordMuscles() {
        val log = dragLog ?: return
        val sb = StringBuilder()
        for (m in muscleTarget.indices) {
            if (muscleTarget[m] == 0.0) continue
            if (sb.isNotEmpty()) sb.append(',')
            sb.append(m).append(':').append(muscleTarget[m])
        }
        val now = sb.toString()
        if (now == logMuscles) return
        logMuscles = now
        log.append("M ").append(logTick).append(' ').append(if (now.isEmpty()) "-" else now).append('\n')
    }

    private fun recordDrag() {
        val log = dragLog ?: return
        val id = dragId
        if (id != logLastId) {
            if (id < 0) log.append("U ").append(logTick).append('\n')
            else log.append("D ").append(logTick).append(' ').append(id)
                .append(' ').append(mouseX).append(' ').append(mouseY).append('\n')
            logLastId = id; logLastX = mouseX; logLastY = mouseY
            return
        }
        if (id < 0) return
        // Порог в сотую долю связи: дрожание руки в лог не пишем, оно и в игре
        // ничего не решает, а строк добавило бы сотни.
        val eps = body.meanLinkLength * 0.01
        if (abs(mouseX - logLastX) > eps || abs(mouseY - logLastY) > eps) {
            log.append("D ").append(logTick).append(' ').append(id)
                .append(' ').append(mouseX).append(' ').append(mouseY).append('\n')
            logLastX = mouseX; logLastY = mouseY
        }
    }

    /**
     * Позиция для отрисовки — ИНТЕРПОЛИРОВАННАЯ, по истории подшагов.
     *
     * ЗАЧЕМ. Физика идёт 30 раз в секунду, экран рисует 60..240. Без интерполяции одно
     * и то же состояние показывалось бы по 2..8 кадров подряд, и движение выглядело бы
     * рваным, хотя сама физика ровная. Это чисто визуальная проблема, и решается она
     * чисто визуально: рисуем не «последнее состояние», а точку между двумя
     * сохранёнными, соответствующую тому, сколько реального времени уже накоплено.
     *
     * ПОЧЕМУ ПО ПОДШАГАМ, А НЕ ПО ГРАНИЦАМ ТИКОВ. За тик тело успевает заметно
     * повернуться и изогнуться, и прямая между началом и концом тика срезает эту дугу.
     * История по подшагам (17 состояний при 16 подшагах) даёт ту же дугу кусочно, и
     * срезание падает во столько же раз. Память тут копеечная: 17 * n * 2 double.
     *
     * ЭТО НЕ ВЛИЯЕТ НА ФИЗИКУ ВООБЩЕ. Интерполяция только читает историю; решатель
     * работает с px/py, как и работал.
     */
    /**
     * Какие два слота истории смешивать и с каким весом. Одна формула на обе оси,
     * иначе x и y однажды разойдутся при правке.
     *
     * Режим 1 берёт только границы тика: слот 0 и последний. Режим 2 идёт по подшагам.
     */
    // -1 значит «истории ещё нет, брать сырые px/py». Важно именно -1, а не 0:
    // до первого prepareLerp() слот 0 заполнен нулями, и выбор мышью на первом кадре
    // целился бы в начало координат.
    private var lerpLo = -1
    private var lerpHi = 0
    private var lerpU = 0.0

    private fun prepareLerp() {
        if (interpMode == 0 || histCount < 2) { lerpLo = -1; return }
        if (interpMode == 1 || !histHasSubsteps) {
            lerpLo = 0
            lerpHi = histCount - 1
            lerpU = renderAlpha
            return
        }
        val f = renderAlpha * (histCount - 1)
        var a = f.toInt()
        if (a > histCount - 2) a = histCount - 2
        lerpLo = a
        lerpHi = a + 1
        lerpU = f - a
    }

    private fun fx(i: Int): Float =
        if (lerpLo < 0) px[i].toFloat()
        else (histX[lerpLo][i] + (histX[lerpHi][i] - histX[lerpLo][i]) * lerpU).toFloat()

    private fun fy(i: Int): Float =
        if (lerpLo < 0) py[i].toFloat()
        else (histY[lerpLo][i] + (histY[lerpHi][i] - histY[lerpLo][i]) * lerpU).toFloat()

    /** Снимок состояния в слот истории. Вызывается из simulate(). */
    private fun histSnap(slot: Int) {
        val hx = histX[slot]; val hy = histY[slot]
        for (i in 0 until n) { hx[i] = px[i]; hy[i] = py[i] }
    }

    private fun countInverted() {
        var c = 0
        for (t in 0 until triCount) {
            val i0 = triA[t]; val i1 = triB[t]; val i2 = triC[t]
            val area2 = (px[i1] - px[i0]) * (py[i2] - py[i0]) - (py[i1] - py[i0]) * (px[i2] - px[i0])
            val inv = area2 < 0f
            triInverted[t] = inv
            if (inv) c++
        }
        invertedNow = c
        if (c > invertedPeak) invertedPeak = c
    }

    /**
     * Кто сейчас командует мышцами. Источников три и они складываются по ИЛИ:
     * наведение мышью, удержание цифровой клавиши и автоматический гребок.
     */
    private fun updateMuscleTargets() {
        muscleTarget.fill(0.0)

        // Проверка верхней границы не лишняя: тело может не иметь мышц вовсе
        // (у текущей выгрузки muscle = 0), и тогда массив пуст.
        if (hoveredMuscle in muscleTarget.indices) muscleTarget[hoveredMuscle] = 1.0

        // Цифры 1..9 — держать соответствующую мышцу сокращённой.
        val keys = minOf(9, muscleTarget.size)
        for (m in 0 until keys) {
            if (Gdx.input.isKeyPressed(Input.Keys.NUM_1 + m)) muscleTarget[m] = 1.0
        }
        // 0 — все сразу.
        if (Gdx.input.isKeyPressed(Input.Keys.NUM_0)) muscleTarget.fill(1.0)

        // Автоматический гребок. Доля рабочей фазы — GAIT_DUTY, минимум один кадр:
        // при коротком периоде округление вниз может дать ноль, и гребка не будет вовсе.
        if (gait) {
            gaitFrame++
            val duty = (gaitPeriod * gaitDuty).toInt().coerceAtLeast(1)
            if (gaitFrame % gaitPeriod < duty) muscleTarget.fill(1.0)
        }
    }

    private fun updateMuscles(dt: Double) {
        if (muscleActivationPrev.size != muscleActivation.size) muscleActivationPrev = DoubleArray(muscleActivation.size)
        System.arraycopy(muscleActivation, 0, muscleActivationPrev, 0, muscleActivation.size)
        for (m in muscleActivation.indices) {
            val target = muscleTarget[m]
            // Сокращение и распрямление идут с РАЗНОЙ скоростью — см. константы.
            val rate = if (target > muscleActivation[m]) muscleRateContract else muscleRateRelax
            var k = rate * dt
            if (k > 1.0) k = 1.0
            muscleActivation[m] += (target - muscleActivation[m]) * k
        }
    }

    // =================================================================
    //  ВВОД
    // =================================================================

    private fun handleInput() {
        tmp.set(Gdx.input.x.toFloat(), Gdx.input.y.toFloat(), 0f)
        viewport.unproject(tmp)
        mouseX = tmp.x.toDouble(); mouseY = tmp.y.toDouble()

        // Диалог забирает мышь ПЕРВЫМ. Иначе клик по ползунку, который висит поверх
        // тела, одновременно хватал бы вершину под ним.
        val uiTookMouse = controls.handleInput(Gdx.graphics.width, Gdx.graphics.height)
        if (uiTookMouse) {
            if (dragId >= 0) act('U')
            wasTouched = true
        }

        // Панорама правой кнопкой. ЛЕВАЯ остаётся за перетаскиванием вершины, СРЕДНЯЯ —
        // за пометкой клеток, поэтому ниже проверяется именно кнопка, а не isTouched:
        // тот истинен для любой кнопки и панорама воровала бы захват.
        if (Gdx.input.isButtonPressed(Input.Buttons.RIGHT)) {
            // Сколько мира приходится на пиксель — зависит от зума, поэтому считается
            // каждый кадр, иначе на приближении панорама была бы рывками.
            val unitsPerPixel = viewport.worldWidth * camera.zoom / viewport.screenWidth
            camera.position.x -= Gdx.input.deltaX * unitsPerPixel
            camera.position.y += Gdx.input.deltaY * unitsPerPixel   // экранный Y смотрит вниз
            camera.update()
        }

        val touched = Gdx.input.isButtonPressed(Input.Buttons.LEFT) && !uiTookMouse
        if (touched && !wasTouched) {
            val i = nearestParticle()
            if (i >= 0) act('D', i)
        }
        if (!touched && wasTouched && dragId >= 0) act('U')
        wasTouched = touched

        // ПОМЕТКА СРЕДНЕЙ КНОПКОЙ: клетка, которую игрок считает проблемной. Повторный
        // клик снимает. На физику не влияет, только ложится в журнал с номером тика.
        val middle = Gdx.input.isButtonPressed(Input.Buttons.MIDDLE) && !uiTookMouse
        if (middle && !wasMiddle) {
            val i = nearestParticle()
            if (i >= 0) toggleMark(i)
        }
        wasMiddle = middle

        hoverId = if (dragId >= 0) dragId else nearestParticle()
        hoveredMuscle = muscleUnderMouse()

        if (Gdx.input.isKeyJustPressed(Input.Keys.SPACE)) paused = !paused
        if (Gdx.input.isKeyJustPressed(Input.Keys.R)) act('R')
        if (Gdx.input.isKeyJustPressed(Input.Keys.B)) act('B', if (bonesRigid) 0 else 1)
        if (Gdx.input.isKeyJustPressed(Input.Keys.C)) viewMode = (viewMode + 1) % 3
        if (Gdx.input.isKeyJustPressed(Input.Keys.G)) act('G', if (gait) 0 else 1)
        if (Gdx.input.isKeyJustPressed(Input.Keys.F)) fastForward = !fastForward
        if (Gdx.input.isKeyJustPressed(Input.Keys.E)) act('E', (bendLevel + 1) % BEND_LEVELS.size)
        if (Gdx.input.isKeyJustPressed(Input.Keys.T)) controls.toggle()
        if (Gdx.input.isKeyJustPressed(Input.Keys.Y)) controls.reset()
        if (Gdx.input.isKeyJustPressed(Input.Keys.I)) interpMode = (interpMode + 1) % 3
        if (Gdx.input.isKeyJustPressed(Input.Keys.K)) act('K', if (contactsOn) 0 else 1)
        if (Gdx.input.isKeyJustPressed(Input.Keys.P)) act('P')
        if (Gdx.input.isKeyJustPressed(Input.Keys.O)) act('O')
        if (Gdx.input.isKeyJustPressed(Input.Keys.L)) {
            // Старая запись начинается со сброса — сброс идёт через журнал игрока.
            if (dragLog == null) act('R')
            toggleDragLog()
        }
        if (Gdx.input.isKeyJustPressed(Input.Keys.X)) act('X', if (tearingOn) 0 else 1)
        // J просит у стенда мягкой решётки новый сид разрушения. В обычном демо
        // окно просто закроется — стенда, который откроет следующее, там нет.
        if (Gdx.input.isKeyJustPressed(Input.Keys.J)) {
            LabControl.restartRequested = true
            Gdx.app.exit()
        }
        if (Gdx.input.isKeyJustPressed(Input.Keys.N)) act('N', (sceneIndex + 1) % scenes.size)
        if (Gdx.input.isKeyJustPressed(Input.Keys.M)) act('S')
        // ESC сначала закрывает диалог и только потом выходит: иначе из него не выйти
        // иначе как повторным T, а рефлекс у всех один.
        if (Gdx.input.isKeyJustPressed(Input.Keys.ESCAPE)) {
            if (controls.isOpen) controls.close() else Gdx.app.exit()
        }
    }

    /**
     * Ближайшая вершина к курсору — по НАРИСОВАННЫМ позициям, а не по сырым px/py.
     *
     * Пока интерполяции не было, разницы не существовало. С ней сырая позиция — это
     * конец последнего тика, а на экране тело стоит где-то МЕЖДУ состояниями. На
     * обычной скорости расхождение меньше кадра и незаметно, а на замедлении
     * renderAlpha подолгу держится далеко от единицы, и подсветка уезжает от клетки,
     * в которую целишься. Для отладки это критично: наводишься на одну клетку, а
     * подсвечивается соседняя.
     *
     * Выбор идёт по тому, что пользователь ВИДЕЛ, — это верно и по существу.
     * Стоимость нулевая: fx() это пара умножений, а проход и так был O(n).
     *
     * ФИЗИКУ ЭТО НЕ ТРОГАЕТ. solveDrag по-прежнему тянет px/py к курсору в физическом
     * пространстве; интерполяция живёт только в отрисовке и в выборе.
     */
    private fun nearestParticle(): Int {
        var best = -1
        var bestD2 = (pickRadius * pickRadius).toDouble()
        for (i in 0 until n) {
            // Мёртвую не схватить и не пометить: на экране её нет.
            if (cellDead[i]) continue
            val dx = fx(i) - mouseX; val dy = fy(i) - mouseY
            val d2 = dx * dx + dy * dy
            if (d2 < bestD2) { bestD2 = d2; best = i }
        }
        return best
    }

    private fun muscleUnderMouse(): Int {
        var best = -1
        var bestD2 = (edgePickRadius * edgePickRadius).toDouble()
        for (c in 0 until conCount) {
            val m = conMuscle[c]
            if (m < 0) continue
            // Тоже по нарисованным позициям — см. nearestParticle().
            val i = conA[c]; val j = conB[c]
            val xi = fx(i); val yi = fy(i)
            val ex = fx(j) - xi; val ey = fy(j) - yi
            val len2 = ex * ex + ey * ey
            var t = if (len2 < 1e-18) 0.0 else ((mouseX - xi) * ex + (mouseY - yi) * ey) / len2
            if (t < 0.0) t = 0.0 else if (t > 1.0) t = 1.0
            val dx = mouseX - (xi + ex * t); val dy = mouseY - (yi + ey * t)
            val d2 = dx * dx + dy * dy
            if (d2 < bestD2) { bestD2 = d2; best = m }
        }
        return best
    }

    // =================================================================
    //  ЖИЗНЕННЫЙ ЦИКЛ И ОТРИСОВКА
    // =================================================================

    override fun create() {
        shapes = ShapeRenderer(60000)
        batch = SpriteBatch()
        font = BitmapFont()
        camera = OrthographicCamera()
        viewport = FitViewport(VIEW_WIDTH, VIEW_HEIGHT, camera)
        hudCamera = OrthographicCamera()

        // Зум колесом. Только он и требует InputProcessor: всё остальное опрашивается
        // напрямую, а прокрутка приходит событием и опросом её не поймать.
        Gdx.input.inputProcessor = object : com.badlogic.gdx.InputAdapter() {
            override fun scrolled(amountX: Float, amountY: Float): Boolean {
                // Мир под курсором запоминается ДО зума и возвращается ПОСЛЕ — так
                // приближение идёт к точке под мышью, а не к центру экрана.
                tmp.set(Gdx.input.x.toFloat(), Gdx.input.y.toFloat(), 0f)
                viewport.unproject(tmp)
                val wx = tmp.x
                val wy = tmp.y

                camera.zoom *= if (amountY > 0) 1.15f else 1f / 1.15f
                camera.zoom = camera.zoom.coerceIn(0.05f, 8f)
                camera.update()

                tmp.set(Gdx.input.x.toFloat(), Gdx.input.y.toFloat(), 0f)
                viewport.unproject(tmp)
                camera.position.x += wx - tmp.x
                camera.position.y += wy - tmp.y
                camera.update()
                return true
            }
        }

        buildFromFile()
        startWarmUp()
        reset()
        openPlayerLog()
    }

    override fun resize(width: Int, height: Int) {
        viewport.update(width, height)
        // Позиция ставится ТОЛЬКО в первый раз: иначе изменение размера окна сбрасывало
        // бы панораму и зум, которые пользователь только что настроил.
        if (!cameraPlaced) {
            camera.position.set(viewCenterX(), 0.85f, 0f)
            cameraPlaced = true
        }
        camera.update()
        hudCamera.setToOrtho(false, width.toFloat(), height.toFloat())
    }

    private var cameraPlaced = false

    /** Центр кадра: середина между копиями, иначе вторая уезжает за край. */
    private fun viewCenterX(): Float {
        var lo = Float.MAX_VALUE; var hi = -Float.MAX_VALUE
        for (i in 0 until n) {
            val v = body.x[i]
            if (v < lo) lo = v
            if (v > hi) hi = v
        }
        return (lo + hi) * 0.5f
    }

    override fun render() {
        handleInput()

        // Мышцы обновляются ВНУТРИ паузы-гварда вместе с физикой. Иначе на паузе
        // активации продолжали бы ехать к цели, длины покоя менялись бы без решателя,
        // и при снятии паузы тело получало бы разом накопленную ошибку — рывок.
        if (!paused) {
            var steps = 0
            if (!fastForward) {
                // ФИКСИРОВАННЫЙ ШАГ С АККУМУЛЯТОРОМ.
                //
                // Раньше здесь был ровно один шаг на кадр отрисовки, и DT работал как
                // «предполагаемая длительность кадра». Пока DT совпадал с частотой
                // экрана, это сходилось; после перехода на 60 UPS при отрисовке в 144
                // кадра симуляция пошла бы в 2.4 раза быстрее реального времени, и
                // счётчик simTime врал бы ровно во столько же.
                //
                // DT НЕ ТРОГАЕТСЯ НИКОГДА: детерминизм требует фиксированного шага, а
                // скорость проигрывания меняется числом тиков, а не их длиной.
                // timeScale умножает РЕАЛЬНОЕ время, а не DT. Значит меняется число
                // тиков в секунду, а не их длина: на 0.5x получаются побитово те же
                // состояния, просто показанные на большем числе кадров.
                accumulator += Gdx.graphics.deltaTime.toDouble() * controls.timeScale
                // Потолок на догон. Без него после подвисания (перетаскивание окна,
                // сборка мусора) накопленный долг отрабатывается разом, и тело получает
                // пачку шагов подряд — выглядит как взрыв.
                if (accumulator > MAX_CATCHUP) accumulator = MAX_CATCHUP
                while (accumulator >= DT) {
                    stepOnce()
                    accumulator -= DT
                    steps++
                }
            } else {
                // Крутим шаги, пока не выйдет бюджет. Проверка ПОСЛЕ шага, а не до:
                // хотя бы один шаг за кадр обязан пройти, иначе при просроченном кадре
                // симуляция встанет совсем и это будет похоже на зависание.
                val deadline = System.nanoTime() + FAST_BUDGET_MS * 1_000_000L
                do {
                    stepOnce()
                    steps++
                } while (System.nanoTime() < deadline && steps < FAST_MAX_STEPS)
                // В ускорении долг не копим: реальное время тут ни при чём.
                accumulator = 0.0
            }
            // Доля тика, уже покрытая реальным временем: по ней fx()/fy() выбирают точку
            // в истории подшагов. В ускорении интерполировать нечего — там за кадр
            // проходит много тиков, показываем последнее состояние.
            renderAlpha = if (fastForward) 1.0 else (accumulator / DT).coerceIn(0.0, 1.0)

            // Сглаживание, иначе число в HUD прыгает и его невозможно прочесть.
            stepsAvg += (steps - stepsAvg) * 0.1f
        }
        prepareLerp()
        countInverted()

        ScreenUtils.clear(BG)
        Gdx.gl.glEnable(GL20.GL_BLEND)
        Gdx.gl.glBlendFunc(GL20.GL_SRC_ALPHA, GL20.GL_ONE_MINUS_SRC_ALPHA)
        shapes.projectionMatrix = camera.combined

        shapes.begin(ShapeRenderer.ShapeType.Filled)
        // Заливка идёт ПО ТРЕУГОЛЬНИКАМ: у гексагональной топологии нет ячеек, из которых
        // можно было бы собрать контур, а треугольники ограничения площади её и покрывают.
        for (t in 0 until triCount) {
            val i0 = triA[t]; val i1 = triB[t]; val i2 = triC[t]
            val m = triMuscle[t]
            val act = if (m >= 0) muscleActivation[m] else 0.0
            // ТРЕУГОЛЬНИК НА КРАЮ МЫШЦЫ КРАСИТСЯ ЧАСТИЧНО — по доле мышечных вершин.
            //
            // Площадь сокращает только тот, у которого все три вершины в одном кластере и
            // ни одной кости, см. muscleOfTri. Остальные, кто мышцу задевает, — это либо
            // следующее кольцо за выросшим кластером (см. MUSCLE_TOUCH), либо треугольник
            // с костью в углу: его клетки мышечные и связи сокращаются, а площадь нет.
            // Без этой заливки край мышцы выглядел бы обычной тканью, хотя в редакторе
            // там мышца, — из-за чего и пришёл вопрос, почему мышца у кости не мышца.
            val mv = if (m >= 0) -1 else {
                var k = 0; var any = -1
                if (muscleOf[i0] >= 0) { k++; any = muscleOf[i0] }
                if (muscleOf[i1] >= 0) { k++; any = muscleOf[i1] }
                if (muscleOf[i2] >= 0) { k++; any = muscleOf[i2] }
                if (k == 0) -1 else any
            }
            shapes.color = when {
                triInverted[t] -> INVERTED_FILL
                triTorn(t) -> TEAR_FILL
                boneOf[i0] != -1 && boneOf[i0] == boneOf[i1] && boneOf[i0] == boneOf[i2] ->
                    if (bonesRigid) BONE_FILL else BONE_FILL_OFF
                m >= 0 -> if (act > 0.002) tmpColor.set(MUSCLE_IDLE).lerp(MUSCLE_FILL, act.toFloat()) else MUSCLE_IDLE
                mv >= 0 -> {
                    val a2 = muscleActivation[mv]
                    var share = 0
                    if (muscleOf[i0] == mv) share++
                    if (muscleOf[i1] == mv) share++
                    if (muscleOf[i2] == mv) share++
                    tmpColor2.set(MUSCLE_IDLE).lerp(MUSCLE_FILL, a2.toFloat())
                    tmpColor.set(SOFT_FILL).lerp(tmpColor2, share / 3f)
                }
                else -> SOFT_FILL
            }
            shapes.triangle(fx(i0), fy(i0), fx(i1), fy(i1), fx(i2), fy(i2))
        }
        // Кости заливаются ещё и по своим связям: у мелких костей треугольников может
        // не быть вовсе, и без этого они на картинке пропадут.
        if (viewMode == 1) {
            for (i in 0 until n) {
                if (boneOf[i] == -1) continue
                shapes.color = if (bonesRigid) BONE_FILL else BONE_FILL_OFF
                shapes.circle(fx(i), fy(i), body.radius[i] * 0.9f, 10)
            }
        }
        shapes.color = ACTIVE
        if (hoverId >= 0) shapes.circle(fx(hoverId), fy(hoverId), body.meanLinkLength * 0.5f, 14)
        shapes.color = DOT
        // Точки рисуются СВОИМ радиусом, а не общим: иначе разница масс между клетками
        // не видна глазами, а она теперь влияет на физику.
        for (i in 0 until n) if (!cellDead[i]) shapes.circle(fx(i), fy(i), body.radius[i] * 0.22f, 6)

        // РЕЖИМ 2: НАСТОЯЩИЕ РАДИУСЫ КЛЕТОК.
        //
        // В обычном режиме клетка рисуется точкой в 22% своего радиуса — это метка
        // положения, а не размер. Из-за этого перекрытия соседей не видно вовсе,
        // хотя в физике оно есть: при радиусе 0.5 и шаге решётки 0.6 соседи
        // перекрываются на 40%.
        //
        // Здесь же рисуются ТРИ радиуса сразу, и разница между ними существенна:
        //
        //   белый    радиус клетки из файла. Из него берётся МАССА (пропорционально
        //            площади) и он же задаёт размер, который рисует редактор.
        //   голубой  радиус КОНТАКТА, он же мембрана. Берётся из длины граничных
        //            рёбер, а не из радиуса клетки, потому что сшивание контура
        //            зависит от расстояния между соседями, а не от того, какой
        //            размер нарисовал игрок.
        //
        // Голубой ЗАМЕТНО МЕНЬШЕ белого, и это осознанно: контакт срабатывает
        // раньше, чем сходятся нарисованные круги. Иначе несвязанные граничные
        // клетки попадали бы в вечный ложный контакт — запас между «сшить контур»
        // и «не задеть лишнего» на этом теле всего 1.6x.
        if (viewMode == 2) {
            val ctR = contacts
            shapes.color = DOT
            for (i in 0 until n) if (!cellDead[i]) shapes.circle(fx(i), fy(i), body.radius[i], 14)
            if (ctR != null) {
                shapes.color = CONTACT_COLOR
                for (i in 0 until n) {
                    val r = ctR.contactRadiusOf(i)
                    if (r > 0.0) shapes.circle(fx(i), fy(i), r.toFloat(), 14)
                }
            }
        }
        shapes.end()

        shapes.begin(ShapeRenderer.ShapeType.Filled)
        shapes.color = GROUND_COLOR
        shapes.rectLine(-1f, GROUND_Y.toFloat(), 5f, GROUND_Y.toFloat(), 0.006f)
        shapes.color = LINK
        for (c in 0 until conCount) {
            val i = conA[c]; val j = conB[c]
            shapes.rectLine(fx(i), fy(i), fx(j), fy(j), 0.0015f)
        }

        // КОНТАКТНЫЕ ЧАСТИЦЫ. Рисуются кружком СВОЕГО радиуса, умноженного на
        // CONTACT_SCALE, — то есть ровно тем кругом, которым клетка и сталкивается.
        // Так видно настоящую геометрию контакта, а не приблизительную метку: если
        // круги налезли друг на друга, значит контакт обязан был сработать.
        // Кости сюда попадают наравне с мягкой тканью: граница у них общая.
        val ctDraw = contacts
        if (contactsOn && ctDraw != null) {
            shapes.color = CONTACT_COLOR
            for (e in 0 until boundCount) {
                for (v in intArrayOf(boundA[e], boundB[e])) {
                    shapes.circle(fx(v), fy(v), ctDraw.contactRadiusOf(v).toFloat(), 12)
                }
            }
            // Свободные частицы рисуем отдельно: они не лежат ни на одном граничном
            // ребре, и цикл выше их просто не видит.
            for (i in 0 until n) {
                if (!isFree[i] || cellDead[i]) continue
                shapes.circle(fx(i), fy(i), ctDraw.contactRadiusOf(i).toFloat(), 12)
            }
        }

        // Граница: то, что реально омывается средой и создаёт тягу.
        shapes.color = BOUNDARY_COLOR
        for (e in 0 until boundCount) {
            val i = boundA[e]; val j = boundB[e]
            shapes.rectLine(fx(i), fy(i), fx(j), fy(j), 0.005f)
        }

        // Пары изгиба — только в отладочном режиме и только когда стадия включена:
        // иначе они закрывают контур сплошной сеткой и мешают смотреть на само тело.
        if (viewMode == 1 && bendLevel > 0) {
            shapes.color = BEND_COLOR
            for (c in 0 until bendCount) {
                val i = bendA[c]; val j = bendB[c]
                shapes.rectLine(fx(i), fy(i), fx(j), fy(j), 0.002f)
            }
        }
        shapes.end()

        // Метки средней кнопкой — поверх всего, двойным кольцом, чтобы не спутать с
        // подсветкой под курсором.
        if (marks.isNotEmpty()) {
            shapes.begin(ShapeRenderer.ShapeType.Line)
            shapes.color = MARK_COLOR
            val r = body.meanLinkLength * 0.6f
            for (i in marks) {
                shapes.circle(fx(i), fy(i), r, 20)
                shapes.circle(fx(i), fy(i), r * 1.25f, 20)
            }
            shapes.end()
        }

        drawHud()
    }

    private fun drawHud() {
        batch.projectionMatrix = hudCamera.combined
        batch.begin()
        var y = Gdx.graphics.height - 14f
        val line = 18f

        font.color = HUD_TEXT
        font.draw(batch, "REAL BODY FROM GENOME EDITOR  -  XPBD + shape matching", 16f, y); y -= line * 1.4f

        font.color = HUD_MUTED
        // conCount это МЯГКИЕ связи: внутрикостных в нём намеренно нет. У тела
        // целиком из кости здесь ноль, и это не ошибка выгрузки.
        font.draw(batch, "cells = $n   soft links = $conCount   area triangles = ${triCount}" +
            "   (%.2f per cell)".format(triCount.toFloat() / n), 16f, y); y -= line
        font.draw(batch, "substeps = $SUBSTEPS   soft compliance = $SOFT_COMPLIANCE   viscosity = $VISCOSITY /s", 16f, y); y -= line
        font.draw(batch, "medium drag = $MEDIUM_DRAG /s (isotropic, no thrust)   normal drag = $NORMAL_DRAG on $boundCount boundary edges", 16f, y); y -= line

        font.color = if (degenerateBones > 0 || boneCapHits > 0) HUD_WARN else HUD_MUTED
        font.draw(batch, "bones: ${rigidBones.size} rigid clusters" +
            "   ${degenerateBones} single-cell IGNORED   step cap hits = $boneCapHits", 16f, y); y -= line

        font.color = HUD_MUTED
        font.draw(batch, "muscles: ${body.muscleClusters.size} clusters   hovered = $hoveredMuscle", 16f, y); y -= line

        font.color = if (invertedPeak > 0) INVERTED_FILL else HUD_MUTED
        font.draw(batch, "INVERTED triangles: now = $invertedNow   peak = $invertedPeak", 16f, y); y -= line

        // --- наблюдение за дрейфом ---
        //
        // Дрейф показывается В КЛЕТКАХ (в средних длинах связи), а не в мировых единицах:
        // «уехал на 0.04» само по себе ни о чём не говорит, а «уехал на одну клетку»
        // сразу понятно. Импульс рядом нужен, чтобы отличить две разные вещи: тело ещё
        // едет по инерции (|P| большой, дрейф растёт) или уже стоит, а уехало раньше
        // (|P| около нуля при выросшем дрейфе). Это ровно то различие, на котором в
        // PhysicsAudit держится вся проверка честности.
        val ddx = comX() - startCx
        val ddy = comY() - startCy
        val drift = sqrt(ddx * ddx + ddy * ddy)
        var pxSum = 0.0; var pySum = 0.0
        for (i in 0 until n) { pxSum += vx[i]; pySum += vy[i] }
        val momentum = sqrt(pxSum * pxSum + pySum * pySum)
        font.color = HUD_TEXT
        font.draw(batch, "sim time = %.1f s   drift = %.4f (%.2f cells)   |P| = %.3f"
            .format(simTime, drift, drift / body.meanLinkLength, momentum), 16f, y); y -= line

        // ДИАГНОСТИКА ТЯГИ ПРЯМО В КАДРЕ.
        //
        // Вынесено сюда после двух записей, которые воспроизводились как исправные,
        // хотя руками симптом был. Догадки кончились: пусть те же самые величины
        // видно в тот момент, когда всё ломается, а не только в разборе лога.
        //
        //   cell->cur   отставание схваченной клетки от курсора, в связях. Тяга
        //               исправна, когда оно идёт к нулю.
        //   body->cur   расстояние от ЦЕНТРА МАСС организма до курсора. Оно НЕ
        //               обязано быть нулём: схваченная клетка может стоять на
        //               курсоре, а центр тела законно висеть в стороне. Важен
        //               РОСТ этого числа, а не само значение.
        //   cap         срабатывания потолка скорости. Он правит частицы по одной
        //               и импульс не сохраняет — любое ненулевое число здесь
        //               означает движение из ниоткуда.
        if (dragId >= 0) {
            val gx = px[dragId] - mouseX
            val gy = py[dragId] - mouseY
            val cellGap = sqrt(gx * gx + gy * gy) / body.meanLinkLength
            val o = organismOf[dragId]
            var mm = 0.0; var cxx = 0.0; var cyy = 0.0
            for (q in 0 until n) {
                if (organismOf[q] != o || invMass[q] <= 0.0) continue
                val w = 1.0 / invMass[q]
                mm += w; cxx += w * px[q]; cyy += w * py[q]
            }
            val bodyGap = if (mm > 0.0) {
                val bx = cxx / mm - mouseX; val by = cyy / mm - mouseY
                sqrt(bx * bx + by * by) / body.meanLinkLength
            } else 0.0
            // И пик, и потолок берутся ОТ МОМЕНТА ЗАХВАТА, а не от сброса.
            val capHere = speedCapHits - dragCapBase
            val vPeak = sqrt(peakSpeed2) * DT / body.meanLinkLength
            font.color = if (capHere > 0) INVERTED_FILL else HUD_TEXT
            font.draw(batch, ("DRAG  cell->cur = %.2f   body->cur = %.2f   peak = %.2f of %.1f   cap = %d")
                .format(cellGap, bodyGap, vPeak, MAX_SPEED_CELLS_PER_TICK, capHere), 16f, y)
            font.color = HUD_TEXT
            y -= line
        }


        // Изгиб контура: показывается всегда, потому что он МЕНЯЕТ ФИЗИКУ и по картинке
        // это не всегда очевидно — тело просто становится упрямее.
        // Контакты: число сработавших, обрезок CCD и обоих потолков. Потолки в норме
        // должны быть нулями — ненулевое значит удар или что-то пошло не так.
        font.color = if (contactsOn) HUD_TEXT else HUD_MUTED
        val ct = contacts
        font.draw(batch, if (contactsOn)
            "CONTACTS [K] on   now = %d   ccd clamps = %d   link cap = %d   speed cap = %d   torn = %d   TEAR[X] %s, killed = %d"
                .format(ct?.lastContacts ?: 0, ct?.lastToiClamps ?: 0, linkCapHits, speedCapHits,
                    if (::linkTorn.isInitialized) linkTorn.count { it } else 0,
                    if (tearingOn) "on" else "OFF", tornTotal)
        else "K -- self-contact (OFF)", 16f, y); y -= line

        font.color = if (bendLevel > 0) HUD_WARN else HUD_MUTED
        font.draw(batch, if (bendLevel > 0)
            "CONTOUR BEND [E] = %.0e on %d pairs  -- thrust cost, see BEND_LEVELS"
                .format(bendCompliance(), bendCount)
        else "E -- contour bend (OFF, %d pairs available)".format(bendCount), 16f, y); y -= line

        font.color = if (controls.timeScale != 1.0) HUD_WARN else HUD_MUTED
        font.draw(batch, "TIME SCALE [T] = x%.2f   INTERP [I] = %s".format(controls.timeScale,
            when (interpMode) {
                0 -> "off (raw physics state)"
                1 -> "tick bounds (2 snapshots/tick)"
                else -> "by substeps (%d snapshots/tick)".format(SUBSTEPS + 1)
            }), 16f, y); y -= line

        font.color = if (fastForward) HUD_WARN else HUD_MUTED
        font.draw(batch, if (fastForward)
            "FAST FORWARD [F] -- x%.0f  (%.0f steps/frame, budget %d ms)"
                .format(stepsAvg, stepsAvg, FAST_BUDGET_MS)
        else "F -- fast forward (real time now)", 16f, y); y -= line * 1.4f

        font.color = HUD_MUTED
        font.draw(batch, "LMB drag   HOVER a muscle edge   1..9 hold a muscle   0 hold ALL   " +
            "G auto-gait" + if (gait) " [ON, period $gaitPeriod]" else "", 16f, y); y -= line
        font.color = HUD_TEXT
        font.draw(batch, "СЦЕНА [N выбрать, M запустить]: %d/%d  %s".format(
            sceneIndex + 1, scenes.size, scenes[sceneIndex].name), 16f, y); y -= line
        font.draw(batch, "SPACE pause   F fast   E bend   R reset   B bones   C view (норма/кости/радиусы)   P bullet   O slam   L rec   X tear   RMB pan   MMB mark   wheel zoom",
            16f, y); y -= line
        font.color = if (marks.isNotEmpty()) MARK_COLOR else HUD_MUTED
        font.draw(batch, "LOG %s  tick %d   MARKS [MMB] = %s".format(
            if (plog != null) PlayerLog.FILE else "OFF", playTick,
            if (marks.isEmpty()) "none" else marks.joinToString(" ") { "#$it" }), 16f, y); y -= line
        if (paused) { font.color = HUD_WARN; font.draw(batch, "PAUSED", 16f, y) }
        batch.end()

        // Диалог рисуется ПОСЛЕДНИМ, поверх всего: он и логически сверху, и свои
        // begin/end у него собственные — рисовать его внутри чужой пары нельзя.
        controls.render(shapes, batch, font, Gdx.graphics.width)
    }

    /** Идёт прогрев: печатать нечего, окна у этой копии нет. */
    internal var quiet = false

    /**
     * ПРОГРЕВ КОДА РАЗРУШЕНИЯ ПРИ ЗАПУСКЕ.
     *
     * ЗАЧЕМ. Первое же столкновение в игре заметно подлагивает, и это не работа, а
     * компиляция: пути разрыва, пересборки и контактов до первого удара не исполнялись ни
     * разу и идут в интерпретаторе. Замер на журнале 12:17 (тик первого тарана): в холодном
     * процессе 78–107 мс, в прогретом — 22–28 мс при том же объёме работы.
     *
     * КАК. Отдельная копия тела в фоновом потоке получает таран и несколько тиков живёт с
     * разрушением. Общего состояния с игрой у неё нет вовсе — только скомпилированный код,
     * а он в JVM общий на процесс. Поэтому на результат симуляции прогрев не влияет:
     * контрольные суммы шести журналов игрока после него те же.
     *
     * Поток фоновый и с низким приоритетом: он не должен отбирать время у отрисовки.
     */
    private fun startWarmUp() {
        if (!WARMUP_ON_START) return
        val t = Thread({ warmUpBlocking(WARMUP_TICKS) }, "warmup")
        t.isDaemon = true
        t.priority = Thread.MIN_PRIORITY
        t.start()
    }

    /** Сам прогрев. Отдельно от потока, чтобы его можно было позвать из замера. */
    internal fun warmUpBlocking(ticks: Int) {
        val t0 = System.nanoTime()
        try {
            val w = RealBodyDemo(bodyPath, copies, freeParticles, labKillFraction, labKillSeed, killOnDeep)
            w.quiet = true
            w.replayBoot()
            // Через воспроизведение журнала, а не через обычный тик: тот опрашивает
            // клавиатуру, а прогрев идёт в чужом потоке и до появления окна.
            val script = listOf(
                PlayerLog.Line(1, "O", emptyList(), "1 O"),
                PlayerLog.Line(ticks, "END", emptyList(), "$ticks END"),
            )
            w.replayRun(script, onEvent = {}, onTick = {})
        } catch (e: Throwable) {
            println("[RealBodyDemo] прогрев не удался: $e")
            return
        }
        if (!quiet) println("[RealBodyDemo] прогрев разрушения: %d тиков за %.0f мс".format(
            ticks, (System.nanoTime() - t0) / 1e6))
    }

    override fun dispose() {
        closePlayerLog()
        shapes.dispose(); batch.dispose(); font.dispose()
    }
}

/** Запуск: зелёная стрелка. Путь к выгрузке можно передать аргументом. */
fun main(args: Array<String>) {
    if (StartupHelper.startNewJvmIfRequired()) return
    val path = if (args.isNotEmpty()) args[0] else "body-export-медуза.txt"
    val config = Lwjgl3ApplicationConfiguration().apply {
        setTitle("Организм из редактора — XPBD + shape matching")
        setWindowedMode(1100, 720)
        useVsync(true)
        setForegroundFPS(144)
    }
    Lwjgl3Application(RealBodyDemo(path), config)
}
